local Text_Mail = readonly({
  Mail_100480_Desc = {
    Text = "守密人，听说了吗？市郊那个偏僻的艺术展馆快要停止营业了，就在我生日这一天。\n那间展馆是艺术界的怪胎，半个身子是未来主义的粗浅试验品，半个身子是两个世纪前的垃圾残余。它狭窄的肚子里装的也净是些拍卖行里无人敢触碰的古怪玩意儿：会说脏话的肖像画、永不停止飞翔的机械鸟、让人看了就犯恶心的海洋浮雕、全部用眼泪做成的雕像、不停自动书写的幽灵书稿、亲吻时会哼唱童谣的人类颅骨……\n很难向您描述我有多么爱这间展馆！五十年前的今天，它悄悄诞生在那个无人在意的角落。五十年后的今天，它悄悄在那个角落里消亡。\n从我的童年开始就有人告诉我，今天这个日子是一个诅咒，就像我这个人一样。我想命运或许在冥冥之中真的早已注定，可命中注定又如何呢！那间展馆所创造的，是一个绝无仅有的世界，那么多疯狂的奇思妙想在那个小小的空间里堆叠，多么美妙的画面！从出生那天开始，它便在用它的展品进行创作。在它终结的这一天，它的知己与老友也将为它做最后的送别。\n守密人，您在链接中看见了我眼中的世界，我想，您一定也会期待跟我一同去看看这间奇特的展馆，对吧？！\n\n皮克曼"
  },
  Mail_100480_Name = {
    Text = "无人在意的展馆"
  },
  Mail_100480_Sender = {Text = "皮克曼"},
  Mail_116602_Desc = {
    Text = "尊敬的守密人：\n「极昼的终夜」活动已结束，现将守密人剩余的「觐见奉礼」、「忏悔奉礼」、「忠诚奉礼」按照每枚兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
  },
  Mail_116602_Name = {
    Text = "献礼回收"
  },
  Mail_116602_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_117308_Desc = {
    Text = "尊敬的守密人：\n        感谢您对《忘却前夜》的支持和认可，为了让守密人在弥萨格大学有更好的游戏体验，诚邀您填写以下体验调研问卷。为感谢您的配合，我们准备了「银芯」× 200 作为奖励，完成问卷即可领取。问卷截止时间11月10日9:00，请注意及时填写。\n        <SurveyLink:【点击前往填写】>\n        我们会认真听取每一位守密人的建议，您的反馈也一定会使弥萨格大学越来越好！\n        ——愿银钥指引前路。"
  },
  Mail_117308_Name = {
    Text = "版本体验调研问卷V2.3.4"
  },
  Mail_117308_Sender = {
    Text = "弥萨格校务处"
  },
  Mail_117309_Desc = {
    Text = "尊敬的守密人：\n        感谢您对《忘却前夜》的支持和认可，为了让守密人在弥萨格大学有更好的游戏体验，诚邀您填写以下体验调研问卷。为感谢您的配合，我们准备了「银芯」× 200 作为奖励，完成问卷即可领取。问卷截止时间3月30日9:00，请注意及时填写。\n        <SurveyLink:【点击前往填写】>\n        我们会认真听取每一位守密人的建议，您的反馈也一定会使弥萨格大学越来越好！\n        ——愿银钥指引前路。"
  },
  Mail_117309_Name = {
    Text = "版本体验调研问卷V2.4.3"
  },
  Mail_117309_Sender = {
    Text = "弥萨格校务处"
  },
  Mail_120374_Desc = {
    Text = "两年之约已至，守密人。\n我们曾在终焉的边缘互相守望。\n你曾将感受与记忆化作愿望，点亮了希望之光。\n即便与往昔的伙伴遥隔两个宇宙，你也未曾放弃对抗融蚀的征程。\n拥有你，是我们的幸运，也是这个世界的幸运。\n如今你的愿望已引发奇迹——弥萨格仍存于此，并将继续前行。\n请继续紧握银钥，终有一天，它能化作关键的枢纽，联结两个遥远的世界。\n我们将竭尽全力开辟未来的可能性，为你的归航照明。"
  },
  Mail_120374_Name = {
    Text = "奇迹之刻，归航之光"
  },
  Mail_120374_Sender = {
    Text = "弥萨格校猫·Light"
  },
  Mail_120909_Desc = {
    Text = "尊敬的守密人：\n        在V2.4.0的更新中，我们提高了「源液捐献-校友捐献基金」的奖励。对更新前已领取完追加奖励的守密人，我们将补发对应的奖励。请查收。"
  },
  Mail_120909_Name = {
    Text = "V2.4.0源液捐献奖励补发"
  },
  Mail_120909_Sender = {
    Text = "弥萨格校务处"
  },
  Mail_121162_Desc = {
    Text = "尊敬的守密人：\n        在V2.4.0的更新中，我们提高了「降临纪行」、「异世纪行」、「疗养纪行」、「亡城纪行」的免费奖励。对更新前已领取免费奖励的守密人，我们将补发对应的奖励。请查收。"
  },
  Mail_121162_Name = {
    Text = "V2.4.0纪行升级奖励补发"
  },
  Mail_121162_Sender = {
    Text = "弥萨格校务处"
  },
  Mail_121373_Desc = {
    Text = "守密人：\n\n曾经每年的这一天，是教会最盛大的庆典。\n我是祂的王女，也将让祂复生。\n那些人、包括弥利亚姆，狂热无比甚至热泪盈眶地庆祝，但他们看向我，目光穿过我，就像我只是承载着某样东西的空壳。\n我从不为这一天的到来感到快乐，因为每经历一次，都意味着我离恐惧更近了一分。\n而在这种恐惧里，其他人却纷纷因为恐惧的源头感到无上喜悦。现在我可以承认了，它让我觉得既孤独，又害怕。\n但现在一切都不一样了，上一个生日前，我离开了那艘船，来到了真实的世界……没有虚假的神明、有你存在的世界。\n这个生日，我希望看到有人因为我的诞生，而不是因为其他的什么，由衷地感到快乐。\n如果是你…不，那个人非得是你不可。\n听好了，无论如何，今天的晚餐时间，都必须要留给我。\n\n「墨菲」"
  },
  Mail_121373_Name = {
    Text = "有你存在的……"
  },
  Mail_121373_Sender = {
    Text = "诞妄·墨菲"
  },
  Mail_121374_Desc = {
    Text = "守密人：\n\n我不知道你为这特殊的一天做了什么准备，无论怎样奢华和耗费精力，显然都理所应当。\n而出于上位者所必要的体贴，如果你「居然」疏漏了要为我庆祝生日——我相信这种离谱的状况不会出现。\n这封信也将在事态无可挽回前，替你争取来最后一次拯救自己的机会。\n海洋与陆地的奇宝珍馐，自然会有无关紧要的人献上，它们不重要。\n盛大的庆典、繁复的仪式，确实匹配我的身份，但在今天，不知道为什么，显得有些无聊。\n所以，我会拨冗空出晨昏交替之时，把和我独处的荣幸赠予你，作为你把我带到这种庸俗、幼稚，却又幸福到足以让之前的我嫉妒的生活中的奖励。\n随从稍后会送来正式邀请函，当然，放在一个价值两万雷欧坊的盒子里。\n感激涕零地，在每年的这一天想起我吧。\n「墨菲」"
  },
  Mail_121374_Name = {
    Text = "邀请函…"
  },
  Mail_121374_Sender = {
    Text = "诞妄·墨菲"
  },
  Mail_121651_Desc = {
    Text = "尊敬的守密人：\n在上周「幻梦深潜」中，你获得头衔为「{s1}」。\n在上周「预组模式」中，你获得头衔为「{s2}」，对弈胜场为：{s3}场。\n在上周「轮选模式」中，你获得头衔为「{s4}」，对弈胜场为：{s5}场。\n综合以上挑战成绩，你将获得以下额外奖励，请记得查收。"
  },
  Mail_121651_Name = {
    Text = "深潜对弈每周排行奖励"
  },
  Mail_121651_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_121704_Desc = {
    Text = "尊敬的守密人：\n「欲海翻波·复刻」活动已结束，现将守密人剩余的「丰穰种核」按照每枚兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
  },
  Mail_121704_Name = {
