  },
  Mail_121704_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_122522_Desc = {
    Text = "尊敬的守密人：\n「雨镇幽影·复刻」活动已结束，现将守密人剩余的「苍白野兽头骨」、「幽影野兽头骨」和「殷红野兽头骨」按照每个兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
  },
  Mail_122522_Name = {
    Text = "雨镇幽影货币回收"
  },
  Mail_122522_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_122567_Desc = {
    Text = "尊敬的守密人：\n「雾境的燔礼」活动已结束，现将守密人剩余的「迷雾之视」、「迷雾之梦」、「迷雾之源」按照每枚兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
  },
  Mail_122567_Name = {
    Text = "雾境的燔礼货币回收"
  },
  Mail_122567_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_122568_Desc = {
    Text = "哈，可怜的孩子，你根本不知道自己要面对怎样的绝望。什么时候你才能意识到自己的选择没有意义？为一个虚无缥缈的目标押上你渺小的性命？多么壮烈、多么令人陶醉啊！你总是一副踌躇满志、仿佛下一刻就要献身去拯救世界的姿态，真叫人发笑。\n\n不过，谁让我答应过会帮你回家呢？对一只小狗许下的承诺，我总会履行的。说起来，我简直迫不及待想看看，你会拿出怎样的意志去把这场疯狂推到终点？啊……好奇，真是太好奇了！\n\n伟大的「救世主」，把你的荒唐、你的固执，还有那不值一提的倔强都带上吧。开往虚无的列车一旦启动，除了毁灭，便再也没有停歇的可能。\n\n自我满足的疯子……在祂的梦里撑得更久些吧，我会帮助你、等待着，好好欣赏你最终的答案！"
  },
  Mail_122568_Name = {
    Text = "开往虚无的列车"
  },
  Mail_122568_Sender = {
    Text = "熔毁·朵尔"
  },
  Mail_122569_Desc = {
    Text = "主君，\n我一直认为，骑士不是穿在身上的甲胄与纹章，而是刻在心里的忠诚与守护的意志。您以行止与抉择，向我真正诠释了何为骑士。由此我得见骑士之真意：不是以名自重，而是以人相护；不是因荣而勇，而是因责而立。\n\n我明白自己尚不合格——在您为守护希望而战的时刻，我未能随行并肩。我从未忘记过去与您立下的誓言，我将向您献上骑士的忠义，守护您的安全，排除您的敌人。\n\n我时常会回想起第一次同行调查，您带领我们拨开伦蒂尼恩的迷雾，看清最终的真相。那时所有的欢笑与悲泣，都沉淀为我生命中不可磨灭的力量。\n\n如今虽然只能在远方守望、为您准备如此微薄的赠礼……但是为了不辜负主君的期许，我从未懈怠自己的训练。待您归来，请允许我追随您的步伐，我将作为主君之盾永远存在！我的守护之剑将为您闪耀！"
  },
  Mail_122569_Name = {Text = "守望者"},
  Mail_122569_Sender = {Text = "奥吉尔"},
  Mail_122570_Desc = {
    Text = "守密人阁下，\n自葬骸城一别之后，我时常想念与你并肩作战的时光。听闻你又一次选择了唯有王者独行的孤绝之路，果然，你就是这世上如此特殊的存在，从不循常人之轨。\n\n我深信，极致的苦痛能够淬炼出更为馥郁的灵魂。你历经的这场漫长试炼，早已超越凡俗之痛的范畴。我已可以想象，你那由苦难酿成的气息，将是何等复杂、何等震撼。不，如果是你，你注定会超越我所有的想象，打破我对完美一切的认知。\n\n为此，我将继续等待。等待那场只为你我存在的盛宴。在时间的尽头、在永恒起始的寂静之中，你将以怎样的姿态，为我献上这场……贯穿命运之味的飨宴？\n\n阁下，请收下我的礼物，请延长这份痛苦……不要辜负，我的期待。"
  },
  Mail_122570_Name = {
    Text = "等待的筵席"
  },
  Mail_122570_Sender = {
    Text = "杜勒赛因"
  },
  Mail_122571_Desc = {
    Text = "才刚重逢，话还没说上几句，时间就已所剩无几……但你知道的，离别从来不是我们故事的结局。\n\n有件事一直没告诉你……其实，我早已为你备好一束玫瑰。只是迟迟没有送出去，它已经枯萎了。但我在这里向你保证——下次见面，我一定会为你重新准备一束。\n\n而你，你也答应过我，一定会再次来到我面前。我们拉过钩的，绝对、绝对不能食言。\n\n写信总觉得词不达意，纸上写不出我全部的心意。不过……待到命运再度将我们牵引至彼此面前的那一天，我将亲手为你献上那束玫瑰。记住了，我们都要信守约定！\n\n愿银钥指引前路。再见……%player%。"
  },
  Mail_122571_Name = {
    Text = "玫瑰的约定"
  },
  Mail_122571_Sender = {Text = "拉蒙娜"},
  Mail_122572_Desc = {
    Text = "守密人，\n与漆黑灾厄对抗的记忆仍在我的大脑中以高优先级循环读取，你所换取的和平就像是一次极小概率的馈赠事件。然而你的离去，对你的搭档、所有与你建立过连接的个体而言，正以无法终止的进程持续消耗着他们的意识。\n\n科研部从未放弃寻找最终的一线希望。值得庆幸的是，经过无数个没有你意识反馈的昼夜周期后，我们终于锁定了你的踪迹。在这艰险的旅途中，我能够捕捉到恐惧的信号，然而我也深知，恐惧不会使你屈服，只会让你的意志更加坚韧。\n\n此时此刻我的躯壳依旧在实验室运行，大脑却持续生成哭泣的指令。别再干扰我的思绪了，我逃课最多的学生啊，请你不要再缺席我的课堂了……继续勇敢地向前迈步吧，我会为你备好补给，等待与你重逢的那一天。"
  },
  Mail_122572_Name = {
    Text = "重逢之日……"
  },
  Mail_122572_Sender = {Text = "朵尔"},
  Mail_122573_Desc = {
    Text = "无数次，我静观文明的星火在时间长河中明灭，见证记忆的城邦在虚无中坍缩。历史化作书卷被漆黑的火焰吞噬，古往今来的智慧如沙塔般堆积，却终究无法言说那唯一的真理。\n\n人类之于原初的混沌，不过微尘——却也正因这渺小，那敢于直面深渊、向神明挥刃的勇气，才显得如此震彻心魄。\n\n此刻，贯穿万千宇宙的维度之门，正为你洞开。\n\n祂的降临带来命定的混沌，万物的秩序在祂的阴影下战栗。而你，不过是凡胎肉体，却以不可撼动的意志，立于祂的面前。你的可能性，是我无尽预知中唯一无法捕捉的谬误，是我长久等待中那个颠覆一切的变数。\n\n你就是原初的诘问，亦是终末的解答。"
  },
  Mail_122573_Name = {
    Text = "门扉背后"
  },
  Mail_122573_Sender = {Text = "塔薇"},
  Mail_122574_Desc = {
    Text = "失去重要之人的剧痛，那份对自身无能为力的憎恶……我曾深陷其中，无法自拔。但如今，我已听见远方明灯的召唤，感受到它温暖而坚定的指引。恩人，自蒙您启示，我仿佛终于踏上了那条早该行走的路——一条真正属于我的、不容置疑的正道。\n\n曾经笼罩我的、深渊般的黑暗，已不再是我的归宿。而那始终闪烁在意识深处的光芒，也从未真正离我而去。如今我更清晰地看见它、感知它、走向它。我也愿将这真正的信仰，这光所带来的清醒与安宁、觉醒与救赎，带给无数仍在命运迷途中挣扎的灵魂。\n\n而当我凝视您对抗整个混沌洪流的身影——那邪恶而深邃的黑暗，非但未能使您屈服，反而成为映照您信念的幕布。它在您的光芒前溃散、嘶吼、退却，却终究无法遮蔽您分毫。正因这无尽的暗潮汹涌，您所代表的光，才显得如此璀璨、如此不朽、如此接近神性。\n\n引领我的恩人、赐我光明之人啊，您的信念将是我不灭的明灯。现在，正是我以全部生命回应您的时刻。我将以这颗聆听神意的「圣心」回应这道光、回应您纯净的指引……为此我与卡斯托尔会全力以赴。\n\n接受我的供奉吧！请您见证，我这由您重塑的、纯洁而虔诚的信仰。"
  },
  Mail_122574_Name = {
    Text = "明灯的召唤"
  },
  Mail_122574_Sender = {
    Text = "波吕克斯"
  },
  Mail_122575_Desc = {
    Text = "亲爱的老顾客，\n就在那道流转微光的门扉之后，你珍视的朋友们早已等待多时。\n\n不过，请不要掉以轻心哦。维度穿梭从来诡谲而危险，你会见证千面幻象如记忆的浮影般此起彼落，它们映照渴望、也映照恐惧。那是原初意志创造的混沌画卷，即便是我，也无法窥其全貌。因此，每一次跨越，既是对信念的考验，也是对愿望的度量。\n\n但我也深知，对于你我这样的人而言，为了寻找崭新的藏品、为了那些闪耀在灵魂深处的珍视之物，一切的未知与付出，都是值得的。我理解你的选择，也尊重这份近乎固执的珍重。\n\n在这遵循等价法则的宇宙里，你付出的代价，终将以另一种形式归来。\n\n收下这份赠礼吧，待到一切尘埃落定，欢迎你再度光临我的小店。为了实现那时的愿望，你愿意付出什么样的代价呢？"
  },
  Mail_122575_Name = {
    Text = "珍视之物"
  },
  Mail_122575_Sender = {
    Text = "达芙黛尔"
  },
  Mail_123134_Desc = {
    Text = "尊敬的守密人：\n        在V2.4.0的更新中，您在「异梦视界」中的「再见永无乡」与「再见，永无乡」挑战3星奖励获取异常的问题。据您之前的调查和挑战通关记录，我们将为您一次性发放之前未能领取的奖励内容。请查收。"
  },
  Mail_123134_Name = {
    Text = "V2.4.0异梦视界奖励补发"
  },
  Mail_123134_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_123501_Desc = {
    Text = "亲爱的守密人：\n\n想不想在这个特殊的日子，和我这个可爱的女孩子，来一场有趣万分的约会？\n来嘛来嘛，去鬼屋里玩一下不会把你吓死的~你可是「守密人」诶，一定不会被那些人类扮演的「妖魔鬼怪」吓到，对不对？\n（信纸上用随意的横线划掉了一行文字：我可是在认真计划生日的行程，绝不是为了好玩而想看你被吓坏的样子……）\n好了，不开玩笑了。难得今天是我的生日，我才不想搞砸呢！所以现在，我，茉夏，正式邀请你去伦敦金融城新开的那家餐厅共进晚餐——\n那里的热茶和炖鱼令我想起了「家乡」的味道，而在这个世界，除了你，我找不到能够分享的人……\n所以你一定会来的对不对？要是让我这个可爱的女孩子伤心，小心下次你睡觉时我拿着斧子站在你床头！\n\n茉夏"
  },
  Mail_123501_Name = {
    Text = "「打开我」"
  },
  Mail_123501_Sender = {Text = "茉夏"},
  Mail_123543_Desc = {
    Text = "守密人：\n\n又一年，我亲爱的。\n在浮华的光影里，漫天飘散的流言与绯闻中，小心翼翼地藏起每一丝可能露出马脚的软弱，用每一分价值换取最大化的利益——应当是这样，我才能依然以赢家的姿态站在这里。\n但没有，我变得偶尔也有些懒散和软弱，而且会十分欣然地满足你递函来时，那些小姑娘们的愿望。\n不过我并不觉得这是什么坏事，我已经历一场漫长的隐秘战争太久了。当然，只要有一线可能，一丁点机会，我依然会一次又一次地从「那位」的手中尝试逃脱。\n只是，在那些温暖而可爱的缝隙，又或者，在类似今天这种特殊的日子，我允许自己开一些小差，比如——邀请您一同去看一场歌剧，进一场晚餐。\n因为我明白，我必然不会是孤独的，我已拥有十分合我心意的同谋。\n\n索蕾尔"
  },
  Mail_123543_Name = {Text = "同谋"},
  Mail_123543_Sender = {Text = "索蕾尔"},
  Mail_123544_Desc = {
    Text = "展信安：\n\n久疏问候，守密人。请原谅，近段时间未有书信往来，并非是刻意疏远与你的关系，只是我每次提笔，总是无法鼓起勇气，去落下问候的开篇。\n这段时间里，我穿越过无数破碎的时间，也因此得以见证世界一次次走向终结，目睹一幕幕无可挽回的悲剧。像是一位旁观者，在这冰冷寂静的空洞里，默默注视着一切的发生。\n每当这时，我都在想，我们这一生是否注定要充满荒诞和离别？无论是当初的自己，还是你在卡达斯迎来的一切，是否命运已经将一切标定好了剧本，我们只能按照这个剧本出演它需要的角色？\n我没有思考出结论，我不像祂，无法看清世间的一切，所以我想，如果是……拥有祂的一部分权柄的你，能否解答这个问题呢？\n因此我写下了这封信，希望它能将我的视线带到你的身边，亦希望能与你一起探讨这个或许永远不存在答案的谜题。所以能否冒昧请你携带这封信，与你一同……面对接下来的路呢？\n………………………………\n我无法冒着扰动时空的风险前往你身旁，但请让我……在这个空无一物的死寂中，再看看你吧。\n\n「拉蒙娜」"
  },
  Mail_123544_Name = {
    Text = "思绪的谜题"
  },
  Mail_123544_Sender = {
    Text = "「拉蒙娜」"
  },
  Mail_123545_Desc = {
    Text = "可敬的苍白使者：\n\n此前我询问弥萨格中那位无比聪慧的女士，是否还有闲置的场所来供我培育一些花朵。\n朵尔女士很轻松地为我找来了一间房间，虽然第一次推门时，其内散发出的陈腐气味让我怀疑自己是否走错了地点，但经过一番打理，现在它已经能很好的承担自己的职责，给这些孩子们提供一个温暖的家了。\n可由于毫无经验，我不得不适当地施以一些外力，来确保这些孩子可以正常成长下去。\n所幸，在奥尔拉小姐的指导下，我成功将它们培育到了现在的阶段。\n当然，这其中并没有使用任何特殊能力。\n如果计算没有出现疏漏，它们会在我生日当天绽放，虽然我一直重复生日这天并无特别，但出现这种难得一见的巧合，确实很难不让人觉得，或许这真的是父神为我安排的小小礼物。\n不知你是否有兴趣与我在这小小的花园一叙，共度这平凡却又特别的一天？\n我已备好亲手烘烤的饼干和你上次推荐的红茶，期待与你分享这份难得的礼物，以及独属于生命的芬芳。\n\n萨尔瓦多"
  },
  Mail_123545_Name = {
    Text = "室内花园"
  },
  Mail_123545_Sender = {
    Text = "萨尔瓦多"
  },
  Mail_123546_Desc = {
    Text = "搭档：\n\n你有没有听过这样一个故事？\n曾经有一只魔鬼，因为意外被封在了瓶子里，过了许多个百年。\n第一个百年，祂许诺给救出祂的人以无尽的财富和权柄。\n第二个百年，祂许诺给救出祂的人以永久的健康与寿命。\n第三个、第四个、第五个，很久很久之后，祂终于等来了打开瓶盖的渔夫——祂没有回应渔夫的呼唤，甚至也不再想把这个世界闹得天翻地覆，只是假装自己是一只普通的空瓶子，沉默地被重新抛回了海中。\n在我小的时候，我读不明白这个故事。直到我知道了漫长无望的等待，究竟是怎样沉闷而苦痛，将奢求变得比绝望更难以忍受。\n然而在我的理智有任何反应之前，我的心就一次又一次地把我留在了同一个地方。\n魔鬼和人类的区别大概在于，我竟然有些感谢这种痛苦。因为在我们分别的时候，它提醒着我你的存在与珍贵，令我不会迷失在任何没有你的彼端。\n在我诞生的这天，在我最想念你的这天，它也依然沉坠地将我束缚，令我依然等待着你，思念着你。\n希望下一个今天，我能亲手递给你我切下的第一块蛋糕。\n\n拉蒙娜"
  },
  Mail_123546_Name = {Text = "故事"},
  Mail_123546_Sender = {Text = "拉蒙娜"},
  Mail_123547_Desc = {
    Text = "弥萨格的食堂与后勤部往我的房间门口放了一堆毫无必要的东西，极其妨碍出入，你们最好是尽快把它拿回去。\n怎么了，这个世界的口粮是多到没有更有意义的去处了吗？\n这一天只会是我变强路上的角注，帮我标注又一个周期的过去，一年，再下一年，每年我都会变得比上一年更强。\n如果礼物实在没有去处，可以拿给另一个我，她大概会十分高兴吧。\n而我，看在你那些傻不拉唧的天真和坚持的份上……看在那些我最不擅长的东西的份上。\n只要我还存在一天，我就会继续变强，与此同时……\n还不明白吗？你们这些傻子的敌人，也会是我的敌人。\n这种恶心的话我只说一次，明年不要再送礼物了，更加不要什么生日晚餐。\n\n「H」"
  },
  Mail_123547_Name = {Text = "拿回去"},
  Mail_123547_Sender = {Text = "「H」"},
  Mail_123548_Desc = {
    Text = "亲爱的守密人：\n\n你知道吗？前几天，一位神秘的女士突然来拜访了弥萨格。她穿着一身我从未见过的、闪闪发亮的黑色贴身长裙——我问了詹金和梅森，她们也没见过那么漂亮的衣服。\n怎么形容好呢？那身衣服好像是用最漂亮的长发纺织成的，又柔软、又轻盈、又高贵，表面流淌着水一般特殊的光泽……\n詹金看我很好奇，大着胆子去询问了那位神秘女士，她笑着说裙子的材质是来自东方的绸缎，由一种叫做「蚕」的幼虫吐出的丝线织成，款式则叫做「旗袍」……然后，她送了艾继丝一大卷——她说那叫「一匹」相同的「绸缎」……\n「绸缎」太珍贵了，所以我仿照着她附赠的图样，给每个伙伴缝制了一个「荷包」。今年的生日宴会上，我会把「荷包」送给大家……守密人，你有空一起来参与吗？\n如果你太忙碌的话，我会让布朗把荷包送到你的宿舍。\n\n艾继丝"
  },
  Mail_123548_Name = {
    Text = "神秘女士"
  },
  Mail_123548_Sender = {Text = "艾继丝"},
  Mail_123549_Desc = {
    Text = "小树苗：\n\n你知道树是如何记录时光和成长的吗？用一圈又一圈的年轮。\n它们藏于体内，从不轻易示人，直到一株幼小的新芽，逐渐成长为参天的巨树，支撑起一隅高耸的天穹。那岁月的斑痕，则不留痕迹地藏于内心深处。\n今日，是新的年轮记录的起点。在新的一岁里，我们仍需历经许多尚未料及的风雨。\n但那颗由我寄托在你口中的种子，一定会寻觅到适合培育它的土壤，然后生根发芽的，对不对？\n\n泰旖丝"
  },
  Mail_123549_Name = {Text = "年轮…"},
  Mail_123549_Sender = {Text = "泰旖丝"},
  Mail_123644_Desc = {
    Text = "不知不觉，这已经是我在弥萨格度过的第三个生日，我学到了很多东西。\n比如，在我生日的这一天，同样是冬渡节，一个适合赠送礼物的日子。\n虽然你有非常多极其强大的敌人，但我最擅长的就是杀人。我不知道其他让人高兴的做法，也不擅长挑选礼物，不过每次顺利交付任务，我的雇主似乎都很开心。\n所以我已经想好了我要送给你的礼物，一次杀人委托，不限使用对象，不限使用期限。\n只需要告诉我，目标是谁，你想祂怎么死？如果是我能打过的人，我会用最快的速度，替你扭断祂的脖子，就算祂是棘手到如同神的存在，我也可以向你保证，我的放弃绝不会在我的死亡之前到来。\n\n希洛"
  },
  Mail_123644_Name = {
    Text = "说吧，你想谁死？"
  },
  Mail_123644_Sender = {Text = "希洛"},
  Mail_124059_Desc = {
    Text = "尊敬的守密人：\n「沉渊之祀·复刻」活动已结束，现将守密人剩余的「祀者之泪」、「祀者之血」和「祀者之髓」按照每个兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
  },
  Mail_124059_Name = {
    Text = "沉渊之祀活动货币回收"
  },
  Mail_124059_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_124290_Desc = {
    Text = "守密人：\n\n如您所知，欢欣对我而言，其实是种有点陌生的情绪。\n我时常觉得，常世是水面上我无法理解的喧闹，在我还未曾融入其中之前，属于我的枯萎就已经到来了。\n它偶尔让我感到向往，但更多的时候，令我惶惑又窒息。只是在每个像今天这样的日子，为了不让爸爸和妈妈伤心，我都拼命地忍耐着……直到迎来解脱的那天，直到海洋接纳了我。\n我以为，只有幽深的水是我的归宿。然而，守密人，因为你，还有弥萨格各位的存在，即使是我这样与常世格格不入的人，也会开始能够体会某些真实的温暖。就像睡莲上浮时，阳光同样会亲吻她的叶片与花瓣。\n虽然凌乱，我却觉得无论如何都有必要将这些心绪落在纸上，再将它寄给您，请原谅我偶尔的任性吧。\n我只是希望您能知道，在过早被荒寂掩埋的水中，您给我带来了多么可贵的上浮。\n愿您永远欢乐，永远安宁。\n\n宁菲亚"
  },
  Mail_124290_Name = {Text = "上浮"},
  Mail_124290_Sender = {Text = "宁菲亚"},
  Mail_124291_Desc = {
    Text = "守密人：\n\n今天清晨，我的床头出现了一封信函，内容是邀请我参加我自己的生日宴会，落款是「绘者」俱乐部。\n我这才想起上个月我偶有闲暇，便答应了珊担任「绘者」新一期创作大赛的模特。在这之前，我已经推辞过不知多少次。站在模特展台一动不动任人描摹的那些时间里，我回忆起身在蹈海者祭坛的日子。那时的我同样迎承着所有人的目光，但那些目光中只有恐惧和敬畏，却没有一丝触动、赞许与欣赏。\n今晚于绘者俱乐部大堂举办的生日冷餐会上，也会展出当天十余位绘者精心刻画的手绘作品。虽然对你的审美缺乏信心，但多受熏陶总不会是坏事。神母特邀你作为出席嘉宾，一同品鉴他们对「我」的诠释吧。\n\n「墨菲」"
  },
  Mail_124291_Name = {
    Text = "绘者……"
  },
  Mail_124291_Sender = {
    Text = "「墨菲」"
  },
  Mail_124292_Desc = {
    Text = "守密人： \n\n茜尔维娅告诉我，偶尔向亲密关系袒露自己的需求，有助于缓解那种无时无刻都在追随我的恐惧，我不确定这是否奏效，但毫无疑问，今天是个好时机。\n你愿意实现我一个愿望吗，我可以把今天实验室的配给全部都给你。\n不，不是一包咖啡豆。\n虽然那种恐怖的黑色夺走了我几乎所有的亲密关系，如影随形地惊吓着我，然而你已经战胜过它了。\n你让我们安全地生活在弥萨格，或者至少迄今还安全地生活在弥萨格。\n是时候摆脱不健康的咖啡因依赖了，守密人，你可以在今天傍晚挪出一点时间吗？\n如果你在我身边的话，或许我能鼓起勇气在光源不那么充足的地方，小憩一会儿，哪怕是一小会儿。\n\n很想记起安心入睡是什么感觉的温柯尔"
  },
  Mail_124292_Name = {
    Text = "愿望……"
  },
  Mail_124292_Sender = {Text = "温柯尔"},
  Mail_124293_Desc = {
    Text = "守密人{Male=先生,Female=小姐}：\n\n今天清晨，一场梦唤醒了我。\n我仔细地回忆梦境里的一切：微风在温暖的阳光下吹拂，玫瑰与郁金香铺满整片土地，一千只银鸥与快乐的人们正齐声歌唱……我已经许久未曾置身于如此幸福的场景。我想我大概是在童年的庄园，在柯蕾特的花房，或者是西岱的某个公园……可当我转身的时候，我看见了弥萨格那些美丽的哥特式大楼，还有您，守密人{Male=先生,Female=小姐}。您站在花与阳光之间，成为了这首诗里最美妙的那段辞令。\n我深爱西岱，守密{Male=先生,Female=小姐}。可那一刻我忽然惊觉，我已开始习惯与迷恋这里的一切，这世上终于有了比西岱更令我魂梦牵萦的地方。\n生日，是一段岁月的结束，也是另一段岁月的开始。在新岁月开始的这一天，不知道弥萨格后花园绽放的阳光与玫瑰之间，会不会有那位愿意带我一起聆听微风、令我魂梦牵萦的人呢？\n\n奥尔拉"
  },
  Mail_124293_Name = {
    Text = "花与诗之梦"
  },
  Mail_124293_Sender = {Text = "奥尔拉"},
  Mail_124294_Desc = {
    Text = "亲爱的守密人：\n\n前些日子，我总想着送你一份特别的礼物。詹金提议不如亲手为你做一件新衣，我觉得这主意再好不过了。\n这是我在纺织厂工作时最拿手的剪裁款式，希望如今看来还不算过时……其他的我难得支持了我的决定，上面那些活泼的条纹与格纹，都是不同的我制作的。还有这个歪歪扭扭的可爱老鼠图案，是猫「24」坚决要加上的，说这代表布朗，是猫人格的我最喜欢的东西——不知道是不是合适，但希望你能喜欢。\n新的一年，我依然没有什么生日愿望。你总是那样温柔，年年都嘱咐我要好好庆祝。可比起被庆祝，能够为你亲手缝制一点什么，更让我感到踏实和欢喜。\n请收下这件满载心意的新衣吧。\n\n梅森"
  },
  Mail_124294_Name = {
    Text = "一件新衣"
  },
  Mail_124294_Sender = {Text = "「24」"},
  Mail_124295_Desc = {
    Text = "啧：\n\n难以置信，作为伟大的迷宫之主，我居然在这种艰难的磨难里又成功存活了一年。\n听好了！这全都是你和这个蠢学院的错！\n就算你们再怎么对我进行胡言乱语的洗脑，这些乱七八糟的琐事本来就应该由专门的人来干，好吧，我已经很了不起了，我都没有称祂们为奴隶。\n那些老顽固称这个为……什么来着，对，进步。\n等等，我怎么也在被这套逻辑带着跑了，啊啊啊，烦死了！（此处有一堆因为信件主人发脾气而导致的凌乱折痕。）\n不管了，既然我有「进步」，那你也得拿出你的诚意来，今年这个如此盛大的日子，你总不能还和前两年一样等着我提醒吧。\n给你三十分钟，守密人，带着礼物来见我。\n不然我就在你睡觉的时候，让我的子嗣爬到你脸上。\n\n阿格里帕"
  },
  Mail_124295_Name = {Text = "进步"},
  Mail_124295_Sender = {
    Text = "阿格里帕"
  },
  Mail_124296_Desc = {
    Text = "守密人！\n\n我看到了！一幅多么精彩的画面！我很确定那不是梦境！我就站在那里，站在弥萨格墓园那座宏伟的纪念雕像旁边，从那里望着那些绵延不绝的无字墓碑，我确信它们能带给我前所未有的灵感，但我没有想到，它们带给我的远比我想象的要多得多，它们用令人敬佩的慷慨嘲笑着我贫瘠的想象力。\n我看到了那些调查员们的幽魂，他们在那个带着薄雾的美丽黄昏中一起站起身。我没能看清他们的脸庞，但我看到他们的动作——像是优雅的舞蹈，又像是神秘的仪式。他们正向着黑池，向着弥萨格与您的方向致意。现代沙龙上的艺术家们痴迷于描绘个体，常常会斥责这些宏大的画面，可我从来不这样觉得。面对食尸鬼的舞会我万分欣喜，而今天，这幅画面让我不得不流下泪来。\n我想这一定不是巧合。就在今天，恰巧是在我生日这一天，他们向我展示了他们宏伟的共舞，我想他们一定是想让我传达一些什么。我除了画笔一无所长，但这已经足够了不是吗？\n这幅画的草稿已经画好了，守密人，请一定要来我的画室看看！那些已经没有了名字的传奇调查员们，他们想要向您讲述的夙愿，都在我的那张画布之上了！\n我没有贸然为这幅画命名，我想，这个资格只应属于您。\n另：我真的不是去翻找尸体的，我向您保证！\n\n皮克曼"
  },
  Mail_124296_Name = {
    Text = "调查员的夙愿"
  },
  Mail_124296_Sender = {Text = "皮克曼"},
  Mail_124297_Desc = {
    Text = "您好，守密人：\n\n您有没有在害怕，或者说——既害怕，又期待着妾身会在妾身生辰这天，借着庆祝的名义，带来一些什么呢？\n虚与委蛇的亲昵，突如其来的香艳夜晚，或者诡谲又令人迷醉的昏沉幻境？\n啊，统统没有，哪怕是妾身，偶尔也会说些严肃的无趣话题。\n您应该很清楚妾身是什么样的存在，耽于享乐，哪怕楼宇将倾。\n爱和欲，医治不了乏味这门世间最大的病症，但作为引出权力和混乱鲜味的药引，却再精妙合适不过。\n奈何这千百年的时光，大概是妾身对戏折子研究得实在太过深入，总会有些庸人剖心挖肝，说我看见了你孤苦无依的寂寞灵魂。\n呼。\n即使是喜爱逢场作戏的妾身，也经常觉得有些反胃。\n而您……您是为了什么与妾身链接呢，为了控制，为了约束，为了借力？\n您要守护更多的东西，就必然需要更高的权柄，而对权柄的渴望，则会催生更大的野心，它何时会成熟，何时又会被吸吮入腹……真是令妾身光是想想就兴味盎然，甘愿在您身边流连更多、更多年月。\n嘘，不用告诉我答案。\n在每年此日，掳去您一夜的梦，品尝揣摩您的野心是否在滋长，您的意图是否有偏移，便是妾身送给自己最好的生辰贺礼。\n万望勿怪。\n\n「千扇」"
  },
  Mail_124297_Name = {Text = "良宵"},
  Mail_124297_Sender = {Text = "徐"},
  Mail_124298_Desc = {
    Text = "守密人：\n\n训练、战斗、巡逻，从我进入军队服役的那一刻，就已经习惯了用所有集体需要的事务，填充自己的所有时间。\n后来带领亚兰族在沙漠中迁徙，这些事务也愈加膨胀，以至于像定律一样刻进了我的脑海，以至于来到弥萨格，我也始终把集体日程的优先级位于私人事务之前。\n但在与其他人，尤其是与你的相处中，我意识到，无论是作为唤醒体，还是作为人类，我们都需要一些只属于自己的时间，用来体会那些与重要之人的相处。\n因为这种可贵的关系，锚定了我们在时间的存在，也使我们的存在真正具有无可替代的意义。\n虽然有些冒昧，我已经取消了今日所有的集体事务，腾出了一整天。\n只需要几个小时，不，就算是一小时，或者几刻钟，只要你愿意分出一些私人时间给我，它都将成为我度过这个特殊日子的意义。\n\n艾尔瓦"
  },
  Mail_124298_Name = {
    Text = "私人时间"
  },
  Mail_124298_Sender = {Text = "艾尔瓦"},
  Mail_124299_Desc = {
    Text = "小家伙：\n\n一年时光对你来说或许漫长，但对于原质之海的穿行者而言，那不过是时光无垠的汪洋里转瞬即逝的一捧海水。幸运的是，在这海水里还有一些让人印象深刻的晶莹水滴。\n解忧小铺的折扣日，自然是其中最值得珍藏的那一颗。并不仅仅因为它会带来金券，更重要的是，我知道在这一天，有一位客人一定会来到这间小店。\n所有人与人的连接都是生意，而一切生意也都是人与人的连接。每位客人都会在一个特定的时间走进属于他们的小店，每个小店都会在特定的时间迎来属于它们的客人。在漫长的时光里，我见过无数珍宝，而到了最后，这些幼稚的时刻将成为最为珍贵的藏品——它们是这漫长时光存在的缘由。\n这一年时光里，最珍贵的那个新藏品正在珍藏展柜中，静静地等待着那位属于它的客人。\n早点过来吧，小家伙。\n解忧小店已经早早歇业。今天，它的门只为一人而开。\n\n达芙黛尔"
  },
  Mail_124299_Name = {
    Text = "新的藏品"
  },
  Mail_124299_Sender = {
    Text = "达芙黛尔"
  },
  Mail_124300_Desc = {
    Text = "守密人：\n\n不知你是否还记得，我们一同位于门扉前的片刻时光？那天我将真理揭开了一条狭缝，为你展示出宇宙的真实。\n意外的是，在你经历遥望无数世界的永远时，我竟在转瞬即逝的须臾间，出现了一丝无法理解的情绪。\n我时常思考那一瞬间的感觉是什么，为什么通晓真理的我会产生无法理解之物。\n我思考了许久，以现实世界为基准裁量体系而言，那是足以被称作「永恒」的时光。\n在这相对宇宙而言都略显漫长的时间里，我意识到了，这或许就是尚未被定义的奇迹。\n在这特殊的日子，我想邀请你与我链接，透过我的目光，去观测一些我未曾观测过的存在，这一次我们所观测的……将不再是被既定的一切。\n我们将一同寻找，这真理之外的未来。\n\n塔薇"
  },
  Mail_124300_Name = {
    Text = "真理之外"
  },
  Mail_124300_Sender = {Text = "塔薇"},
  Mail_124301_Desc = {
    Text = "守密人：\n\n今年也与往年一样，我停下了所有其他事务，安静地与自己独处，试图重新撰写、翻新那些与故国有关的回忆。\n它们离我更远了，即使我逼迫自己习惯这副类人身躯，想尽办法一遍遍记叙与穿越海洋相关的知识、经历，在这个日渐消逝的世界中，遗忘依然比铭记容易太多太多。\n唯一的慰藉，即是如今我们这些远离了利莫里亚的旅人，依然还有此处可以停留，能够遵循吾王的旨意，安静地追随，安静地等待。\n我深知您为此牺牲与付出的一切，我不知该如何对您表达我的感激，在此身得以回到利莫里亚之前，若有任何能用到我的地方，我同样愿意为此献出我所有的光亮。\n\n您真诚的法洛思"
  },
  Mail_124301_Name = {Text = "灯塔"},
  Mail_124301_Sender = {Text = "法洛思"},
  Mail_124302_Desc = {
    Text = "亲爱的守密人：\n\n自加入弥萨格那天起，纷繁的规矩就缠上了我。不许带仆从在会场散步，不许在校园广场踩踏学生的面颊，不许在礼堂举办多人集体活动……\n弥萨格那些讨厌的卫道士们禁锢了我，这并非伊萨拉乌的女王应当享有的生活。我理当享用我应得的一切，醉人的美酒、柔软的背脊，还有心爱的仆从……在这个我理应肆意的生辰之日，这样的念头自然地生发出来。\n夜已深，我对琐事的耐心已然耗尽。我不会派你去执行午夜任务，也不会让你自行猜测。我需要你待在我的身边。\n现在就来我的庄园，不要犹豫，脱下你所有不必要的衣物和头衔。\n今晚，以及以后的每个夜晚，你都属于我。\n\n你可以把这当作你的第一项永久职责。\n\n旺达"
  },
  Mail_124302_Name = {Text = "规矩"},
  Mail_124302_Sender = {Text = "旺达"},
  Mail_124303_Desc = {
    Text = "守密人：\n\n汀克特告诉我，她用个人演唱会的收入计划了一场生日后的星际旅行，想带我一起去。可是……如果我也同行，她一定会分神照顾我。我不愿让她的快乐因我而打折扣。\n她那么热爱生命里的光，迷恋这宇宙中万千的色彩与流动的星河。若是带上我，她大概就无法那样自在地歌唱、尽情地凝视了吧……\n所以……能不能请你帮我劝劝她？请让她独自去旅行，去不同的星球开演唱会，去拥抱她向往的所有风景……或者由你代替我参加这次旅行？毕竟汀克特和我都很感谢你，想要回报你的恩情……如果你愿意的话……\n只是，请不要告诉她这是我的意愿。我不愿成为她自由旅途里的那道牵绊。\n\n菲茵特"
  },
  Mail_124303_Name = {
    Text = "关于旅行"
  },
  Mail_124303_Sender = {Text = "菲茵特"},
  Mail_124304_Desc = {
    Text = "恩人：\n\n与波吕克斯一同生活在弥萨格的这些日子，如此宁静，如此明亮，仿佛是一场幻梦……\n波吕克斯他现在虽然依旧守着那些礼节，说着些文雅端正的话，我却能清晰感到，他正一点一点变回从前那个他。那些属于「圣子」的、令人屏息的距离感，正在柔软的日常中悄悄消融。这一切温柔的转变，都要归功于您。\n我时常在想，该用什么来报答这份恩情呢？我不像波吕克斯那般手巧，能编出令您惊叹的礼物。飞行的乐趣，您也已与我体会过多回。关于如何在这个特别的日子与您分享喜悦，我默默思考了许久。\n也许……您会喜欢我的羽毛吗？常有人说，它拥有一种能令人心情宁静的柔软。所以，若您有一日感到疲倦，或只是想要一处安静的角落，请随时来到我身边吧。我的羽翼，永远愿为您垂下。\n\n卡斯托尔"
  },
  Mail_124304_Name = {Text = "羽毛"},
  Mail_124304_Sender = {
    Text = "卡斯托尔"
  },
  Mail_124305_Desc = {
    Text = "我的小·囚·犯：\n\n听说弥萨格最近正在流行一款角色扮演游戏，什么女巫、狼人呀……啧，听起来一点都不浪漫呢~我倒是想到了一个更好玩的游戏！\n这样，你来扮演囚犯、我来扮演看守。当我挥动小皮鞭时，我要听到大声的呻吟声哦~蜡烛在你的身躯之上流淌，带来滚烫的痛感与快乐……啊，光是想象一下那幅画面，就已经开始感到甜蜜了呢~\n哎呀，看到这儿，你一定又皱起眉头了吧？真是不乖哦，今天可是我的生日呀~亲爱的小囚犯，总该满足我一点点任性的愿望吧？\n实在不行的话……那……换你来当看守，我来做你的俘虏，怎么样？我会满足你的啦~\n\n潘狄娅"
  },
  Mail_124305_Name = {
    Text = "角色扮演"
  },
  Mail_124305_Sender = {Text = "潘狄娅"},
  Mail_124306_Desc = {
    Text = "守密人：\n恩人，今天是我的生日。在这个特别的日子里，我想向您说说我的近况：在戈利亚和萝坦老师的指导下，我好像……越来越能触碰自己血脉中的力量了。它不再沉睡，而是随着每一次练习，在我身体里低鸣、奔涌，逐步解放。\n\n\n\n我说不清具体何时才能完成最终的蜕变，成为更纯粹的深海族裔。也许明天，也许下个星期，也许下个月……但请您知道，无论这个过程还有多长，路上还有多少磨难，您当初鼓励我的话，我一直…都牢牢记得。我会继续努力的。\n\n还有一件事我必须表示抱歉，我刚刚从弥萨格邮政处获知，随邮件发出现金的话，需要额外缴纳2块手续费。\n为了补上去年份额，我会从积蓄中再支出一笔来。它们对我来说得来不易，但深海的血脉有承诺必定兑现。\n\n凯刻斯"
  },
  Mail_124306_Name = {
    Text = "手续费……"
  },
  Mail_124306_Sender = {Text = "凯刻斯"},
  Mail_124307_Desc = {
    Text = "守密人：\n\n听好了，今晚无论如何，跟我一起去「那家店」。\n伪装用的衣服已经寄给你了，务必、千万，不能让别人认出我们！\n「那家店」的限量甜品开售了，那个不知道哪里来的可恶家伙肯定收买了一批人，不能让他们知道本小姐的行踪。\n虽说那个家伙为了不让我买到，把伦蒂尼恩所有蛋糕店的限量款都预定了，但是嘛……哼哼。\n本小姐已经提前买通了「那家店」的主厨，让他把最最好吃的那款，从菜单上给去掉了。\n哼，本小姐今天就要让那个家伙知道，有些事情可不是单纯靠金钱就行的。\n到时候我们悄悄从后门溜进去，把经过三重加密的铁盒打开，就能得到那份限量款中的限量款了。\n作为报酬，我会把一块（划掉），一半的蛋糕分给你！\n今晚十一点，我在房间等你，你必须、一定要来！知道了么！\n千万要保密，不然泄露了消息让那个家伙知道了我们的行踪，就一切都完蛋了！\n\n墨菲"
  },
  Mail_124307_Name = {
    Text = "抢糕大作战"
  },
  Mail_124307_Sender = {Text = "墨菲"},
  Mail_124308_Desc = {
    Text = "守密人：\n\n很遗憾地通知你，伦蒂尼恩剧院已经完全取消了卡茜亚大师的魔术表演，原因有：票价过高、大家最近见到的怪事太多导致对魔术缺乏兴趣、连续几场表演都有观众失踪至今未归、经常有警察找到剧院老板要求卡茜亚大师暂停表演前去配合调查等等等等。\n最近受到黑池异动的影响，我的表演确实偶尔有些小失误，这些都是小事，但第二点是卡茜亚大师绝对无法容忍的！\n我为此冥思苦想，终于想到了一个完美的新表演！什么尸体操纵、死者复生、维度穿越、情绪感染、巨大触手……统统不值一提！之前受那只可恶的维度猎犬影响，时间的操控一向是本行业的禁忌，但在那只恶犬被封印之后，卡茜亚大师的魔术事业将重新登上一个新的台阶！\n演出时间就定在今晚，完全免费，守密人在第一排正中间的座位已经预留，还有惊喜的互动环节在等待着你！享受你作为新时代最伟大的魔术演出里第一个互动观众的荣幸吧！\n为了重拾卡茜亚大师的荣耀！\n\n卡茜亚"
  },
  Mail_124308_Name = {
    Text = "卡茜亚，让魔术再次伟大！"
  },
  Mail_124308_Sender = {Text = "卡茜亚"},
  Mail_124309_Desc = {
    Text = "主人：\n\n茜尔维娅姐姐刚才来告诉我，今年的生日，她们会带我去乘坐摩天轮。\n莉莉在画本上读到过，摩天轮是一种很大很大的轮子，坐在上面就可以慢慢慢慢地转到天上，看小鸟在旁边飞来飞去，听起来就非常幸福。\n不过茜尔维娅姐姐说“实际上有一些区别”。莉莉也不明白是怎么回事。\n她还说，摩天轮要去的地方太高了，我最好能带上一位监护人。\n莉莉不懂监护人是什么意思，但莉莉想和主人一起去云朵之间旅行。\n午饭后，我和茜尔维娅姐姐会在宿舍外等你。\n\n莉莉"
  },
  Mail_124309_Name = {Text = "摩天轮"},
  Mail_124309_Sender = {Text = "莉莉"},
  Mail_124310_Desc = {
    Text = "守密人（这次我终于写对了！厉害吧！）：\n\n又到了写这些肉麻东西的时候，我都已经习惯了。比是 此时此克 现在，我和布朗正为今天请你吃什么头疼呢！\n东区小巷里的街头美食当然好吃，但今天我打算带你和布朗吃点好的——也就是你们西区佬爱吃的那些东西。\n比如那些沾满了酱料和香料的私家菜，量又小，盘子又大，还贵得离谱，简直就和抢钱一样。想到这里，我就觉得钱包开始漏风了，那一定是金钱离开时，留下的闯伤。\n但你是除了姐姐和布朗外，我最重要、最喜欢的人，东区人可不会对自己人吝啬，所以今天所有花销都由我和布朗支付。\n可别小看我们，我们可是靠送牛奶送报纸传话跑腿还有其他业务挣了不少钱的，你就放心点吧！\n\n你的好伙伴詹金和布朗"
  },
  Mail_124310_Name = {
    Text = "今天我和布朗买单！"
  },
  Mail_124310_Sender = {Text = "詹金"},
  Mail_124311_Desc = {
    Text = "亲爱的守密人：\n\n你一定已经听说了茜尔维娅彻底摧毁弥萨格地下赌场的丰功伟绩吧？但今天是我的生日，要是没有什么肾上腺素飙升的好活动，岂不是浪费了一年一度的好日子？\n经过反复斟酌，我决定特邀你作为我的好华生，和我一道出手拿下近日里从西岱流窜至此、盗窃大博物馆宝藏的暗夜怪盗。\n我在校外那间「阿波罗吧」小酌的时候，偶然听到过他们眉飞色舞地吹嘘自己搜刮昂贵珠宝的战绩。酒保没往心里去，我可是听出来了，祖母绿、蓝宝石、钻石冠冕，和失窃物完全一致。为了避免打草惊蛇，我好好地在他们身上做了记号，准备等他们返回据点，来一个人赃俱获。\n今晚七点，校门口弥萨格专列停车点，我们不见不散。\n\n莱克"
  },
  Mail_124311_Name = {
    Text = "狩猎计划"
  },
  Mail_124311_Sender = {Text = "莱克"},
  Mail_124312_Desc = {
    Text = "守密人：\n\n弥萨格的时光转动得似乎比其他的地方都更加轻盈。几次掌声，几次谢幕，一年的时间便又过去。\n这一年里，我有了一些新的习惯。以前当我站上舞台的时候，即便是再拥挤的剧院在我眼中也空无一人。我在空旷的舞台上，对着空旷的剧场舞蹈，整个世界回荡着的只有一双舞鞋的声音。而现在，每当帷幕拉开，我都会看见你。万千的座椅空空如也，独你一人望向我。在你的目光里，我的舞重新拥有了意义。\n一年过去，你的舞姿依然是那么笨拙，可你在台下那些跃动的目光，却能轻易地超越台上那些庸凡的舞步。那些目光是一道溪流，将我日渐凡俗的舞步一一清洗。在这些舞者与观众的共舞里，我正逐渐靠近那个我一直所追寻的殿堂。我终于领悟到，对于舞蹈而言，观众与舞者同样重要。\n好几个月时间里，我一直在为一支舞做准备。它沐浴着你的目光孕育，在你的剪影里诞生。如今，它已经准备好。\n我想，它会期望在今晚，看到你成为第一个见证它的人。\n\n莉兹"
  },
  Mail_124312_Name = {
    Text = "舞者与观众"
  },
  Mail_124312_Sender = {Text = "莉兹"},
  Mail_124313_Desc = {
    Text = "守密人：\n\n得益于此地的接纳，这一年里，我与王交谈的时日颇多。尽管神国的降临仍然遥远，但利莫里亚的时光，似乎正在弥萨格续延。\n你与王都曾告诉我，信仰不应该是我生命的全部。我曾固执己见，但最近经历的事，似乎让我的心态有所转变。过于频繁的祷告，或许会令吾主感到叨扰。除了虔心的侍奉之外，吾主或许也希望祂的信徒有着属于自己的浅薄生活。\n明悟了这一点后，我尝试去做了一些微小的改变。我拜访了伦蒂尼恩所有有名的糕点师，请他们教授了我烘焙的方法。他们有一些不传之秘，我也已通过吾主的赐福让他们开了口。昨日，我第一次进行了一些尝试，几名信徒告诉我他们觉得味道很不错，但他们的味觉与忠诚一样令人怀疑。\n我想邀请你今日来我的庭院里品尝。我相信你的品味，也相信你的坦率。如果不好吃的话，希望你能直言不讳，我将认真加以改进。\n不胜感激。\n\n弥利亚姆"
  },
  Mail_124313_Name = {
    Text = "另一个专长"
  },
  Mail_124313_Sender = {
    Text = "弥利亚姆"
  },
  Mail_124314_Desc = {
    Text = "守密人阁下：\n\n关于生命与死亡的意义，想必你已经听得厌烦了吧？在葬骸城那些亡灵们绚丽的记忆里，我学会的最重要的事是，比起探寻进食的意义，更重要的，在于面前餐桌上的食物本身。\n在人类的远古时代，我们的祖先便已经探寻出了一切关于进食的内涵——激情，欲望，享用。并非为了活着而进食，是为了进食而活着。遗憾的是，那些原始纯真的欲望在漫长的时光里被逐渐遗忘，这个群体变得越来越复杂。\n因此，我将今天的晚宴主题命名为「纯粹」。在这个具有仪式感的日子里，一切复杂的事务都将离我们远去。这张餐桌之上，只有纯粹的、原始的激情与欲望，只有品鉴者与食物，只有你我。\n请收下我最诚挚的邀请。你不会拒绝我的，对吗？\n\n杜勒赛因"
  },
  Mail_124314_Name = {
    Text = "纯粹的晚宴"
  },
  Mail_124314_Sender = {
    Text = "杜勒赛因"
  },
  Mail_124315_Desc = {
    Text = "我最亲爱的守密人大人：\n\n我的心好像正在生长……我知道这对唤醒体而言听上去很奇怪，但它与之前不同了，我要怎么向您形容呢？\n无论那些好人们如何温柔地、怜惜地对待我，尝试温暖我，在哥哥离开之后，我的胸口始终空洞，我越在太阳下行走，越被那些温暖抓挠。反而阴暗和潮湿更让我安心，仿佛只要一直待在阴冷的地方，哥哥严厉和令人疼痛的爱意就一直没有离开。\n可是现在，在这些与您愈加亲密的年月之后，每次见到您，每次那些您赠予的疼痛落在我的皮肉上，传导到我的骨头上——啊啊，我胸膛里的幸福日渐增长。只要您毫不怜惜地责打我，侮辱我，蹂躏我，我就知道，这个世界上始终有我真正能容身的地方。\n这种幸福能延续到下一年吗，再下一年呢？如果生日许下的愿望都实现，我唯一的愿望，就是被您一直用轻蔑的眼光审视着，还有疼痛……更多更多的疼痛。您扬手时，我首先感受到的将是那股熟悉的、残酷的、幸福的香气。\n\n非常非常希望被您责打的雷娅"
  },
  Mail_124315_Name = {Text = "我的心"},
  Mail_124315_Sender = {Text = "雷娅"},
  Mail_124316_Desc = {
    Text = "守密人\n\n尽管我很想知道您最近的练习情况，但请放心，今天并非是来督促您进行音乐训练的。\n今日清晨，我如往常般前往音乐室，但我迟到了三十五分钟。清晨七点进行音乐训练，这个习惯我维持了数十年，它在今日轻易地打破了。原因是在路过学校走廊时，我听见了一阵知更鸟的啼鸣。\n维持多年的习惯被打破并非一件容易接受的事，于我而言更是如此。奇怪的是，我并未如想象般那样因此而对自己感到失望与愤怒。刚开始的时候，我感到一阵慌张。但随后，我不得不承认，萦绕在我脑海中的旋律是愉悦。\n伦蒂尼恩总是在知更鸟的啼鸣中被唤醒，这个声音我每天都能听见，奇怪的是，这么多年来，这是我第一次注意到它们。我在走廊上静静凝听它们的歌声，在那三十五分钟里，我竟觉得这宇宙至高的旋律就藏在它们细小的喉管里。\n或许是这里的生活令人懈怠，或许是这里的气氛让人变得柔软。无论如何，我想它一定与您有关。\n我用了十分钟便欣然接受了这个变化。生命如同音乐一般有其亘古的节奏与变化，诞生之日，或许便是这些变化注定发生的节点。我也想感谢您，让我有这样的机会去静下心聆听我曾忽视之物。愉悦，没错。我想，这会是我迈入一个新的乐章的开始。\n为此，我想邀请您在今日黄昏的时候与我一同去校外的密林。自然在黄昏时的声音与清晨不同，但我想，它们都会是我们音乐生命里新的启迪。\n\n哈姆林"
  },
  Mail_124316_Name = {
    Text = "自然之音"
  },
  Mail_124316_Sender = {Text = "哈姆林"},
  Mail_124317_Desc = {
    Text = "贵人：\n\n我刚刚看到了菲茵特写给您的那封生日邮件……果然，姐姐她总是这样为他人着想，只是姐妹之间从来没有亏欠，我也从未将她视作我的拖累，若没有她的保护，我也不会拥有如今开巡回演唱会的机会。\n尊敬的贵人，您一直是我最重要的听众。所以这次，我也悄悄为您准备了一张船票——诚挚地邀请您与我们一同踏上这次星际旅程。若有您同行，相信姐姐心里的负担感也会减轻许多。\n另外请您放心，旅途中我们绝不会打扰您的私人时光。我和姐姐都希望，您能尽情享受这段旅程，自由地去感受每一片星云、每一场未知的相遇。\n\n汀克特"
  },
  Mail_124317_Name = {
    Text = "旅行邀约"
  },
  Mail_124317_Sender = {Text = "汀克特"},
  Mail_124318_Desc = {
    Text = "守密人： \n\n生日又近，思绪却总不经意间飘回西岱。尤其怀念那些艺术展上的雕塑。它们静默的姿态，曾无数次叩击我灵感的大门。\n在工作室里终日与雕塑为伴，缺乏艺术的交流，长久以来，也觉乏味。去年此时，为给自己庆生，我雕砌了无数个雕塑蛋糕。起初的兴味盎然，如今也已复归于平静。\n而今行动不便，重返西岱已成奢望。若你恰有前往调查的计划，可否为我留意艺术展中的新作？我渴望借由你的眼睛，再次触碰那片多元而包容的艺术之美。\n作为报答，我愿为你再创作一个雕塑，就叫《守密人在西岱》，怎么样？\n\n珊"
  },
  Mail_124318_Name = {
    Text = "西岱怀想"
  },
  Mail_124318_Sender = {Text = "珊"},
  Mail_124770_Desc = {
    Text = "守密人：\n\n由于每年我进入实验室的权限都会被取消，以至于这个日子以一种并不令人愉快的方式变得特殊，为了不将时间浪费在缺乏效率的琐事上，我去了一趟档案馆。\n在那里我发现了两样东西，其中一本是作业本，上面布满了毫无价值的空白。\n另一本也是作业本，它让我发现我低估了知识汪洋的浩渺，因为上面的推演过程和结论，让我知道了世界上居然还有存在比不存在价值更低的事物。\n而这两本作业本，上面都写着同一个名字，我们伟大的弥萨格守密人%player%。\n艾瑞卡告诉我，你想知道该送我什么生日礼物。\n你可以送我一个答案。\n我也很想知道，哪个答案的事实会更震惊我。是单纯地被发挥到极致的懒惰和敷衍，还是你认真学习了一整个学年，最后在徒劳的绝望中留下了这些学术垃圾。\n如果是前者，只要有充分的理由，并且能证明你已经全盘掌握了课堂上教授的知识，我可以替你向学院提交免作业申请。当然，这并不代表我支持这种可能会令你彻底怠惰的散漫，但只要你能一直通过我的考验，我不是那种老古板，并不介意给我的学生一些特权。\n如果是后者，作为你的第一监护人，相信我，无论你是多么难以塑形的材料，我们都能在我掌握的技术中，找到一项，用以提高你过于贫瘠的智识，救你脱离无知而努力的痛苦境地。\n今天下午四点，我会在档案馆，亲自考察你对课堂知识的掌握，不要迟到。\n\n朵尔"
  },
  Mail_124770_Name = {Text = "特权"},
  Mail_124770_Sender = {Text = "朵尔"},
  Mail_124771_Desc = {
    Text = "弥萨格的小狗：\n\n今年你也困在那些循环往复的日常里，闯祸，拯救世界，结交朋友，学习新知识，继续为世界捏造一些一切如常的假象。\n原来即使把你的脑子从身体里摘出来，灵智从一个维度抽离到另一个维度，也并不会影响到你荒唐到让人发笑的奔走和忙碌。\n真是又忙又吵啊，亲爱的小狗狗。\n你不相信那些事实，你非要延续他们的痛苦，让灭亡的过程延续得更拖沓一些，你的目的是什么，你到底是在装傻，还是人类真的能傻成这样呢？即使我确实剖开过你这个身体的脑叶皮层，这些对我来说依然是未解之谜。\n恭喜你，你真的让我产生了一丝动摇，我居然开始怀疑，如果观察你为我带来了如此巨大的乐趣，那么一切还能说毫无意义吗？\n像你擅长做的那些毫无意义的事一样，毫无意义地祈祷吧，祈祷对象是谁都无所谓。\n祈祷你能一直桎梏住我，小狗狗，这样我和你，都能在毫无意义的世界中，找到些许乐趣。\n\n「朵尔」"
  },
  Mail_124771_Name = {Text = "祈祷吧"},
  Mail_124771_Sender = {
    Text = "熔毁·朵尔"
  },
  Mail_124772_Desc = {
    Text = "搭档：\n\n在每年生日这天给你写信，好像不知不觉就成了一种惯例。\n我还记得，第一个给你写信的生日，也是父亲第一次答应我自己安排生日行程，我邀请你和我一起外出，再后来，我们一起经历了太多个第一次。\n很多事物在那之后都改变了许多，仔细想来，又好像并没有什么改变，我们依然行进在我们所认定的那条道路上，我们的身边依然有彼此陪伴，以及，你依然是对于我来说，最重要的那个搭档。\n所以，虽然父亲刚刚送来了一个蛋糕，询问我晚上是否愿意出席他为我举办的宴会，我对今晚也有一些其他安排。\n伦蒂尼恩上映了一部新电影，受欢迎得异乎寻常，不过学院和协会已经共同确认过，其中不存在任何灵性反应。\n这说明它的确只是一部非常精彩的「普通」作品。\n我正好有两张票，你可以假设我没有破例去麻烦索蕾尔夫人，因为它的票实在太过难买。\n那么，搭档，你愿意把这段时间留给我吗？或许，我们可以暂时从那些我们日日在处理的异常状况中脱离出来，陪伴彼此度过一个「普通」的晚上。\n之后的每一个明天，当我们醒来，不论世界发生什么，我都会和你一起面对。\n\n拉蒙娜"
  },
  Mail_124772_Sender = {Text = "拉蒙娜"},
  Mail_124773_Desc = {
    Text = "守密人：\n\n得益于我与那个我之间的特殊联系，以及我和你之间的链接，即使没有时刻陪伴在你身边，我也对你过去一年的动向略有知晓。\n你活跃于另一个世界，似乎依然给它带来了名为「希望」的改变，即使日复一日地在黑池中仰望着，这种如同光芒一样的能量，也同样温暖到了我。\n我开始重拾起了之前的日程，但和之前不一样，现在我并不是再以徒劳挣扎的心态，去面对那种注定的寂灭。你教会了我新的东西，在注定的终点之前，每个存在为了延续而拼尽全力的过程，正是文明、灵魂、意志之所以有意义的原因。\n不论对于我所在的世界来说，这段时间有多么短暂，我会继续尝试下去。哪怕仅仅只是为了再见到那些熟悉的面孔，和他们交谈几句，这种尝试也并不是毫无意义的。\n直到你停止之前，我都会继续走在这条路上，请允许我任性地将它视作某种与你并肩的方式，这样，或许你能在不断行进的路上，偶尔想到，始终有这样一个我，在全力做着与你一样的事情。\n\n「拉蒙娜」"
  },
  Mail_124773_Sender = {
    Text = "「拉蒙娜」"
  },
  Mail_124774_Desc = {
    Text = "杀掉目标很简单，善后却是件麻烦事。\n本来今年想遵循去年的惯例，再帮你杀个人。\n然而我注意到你一直没有使用我送给你的上一份礼物，经过认真思索，虽然不知道是不是出于这个原因，不过我发现了自己的疏漏。\n你完全可以放心，虽然对于过去那些雇主，我一向只提供杀死敌人的服务，但为了避免各种各样的麻烦，对于销毁痕迹这件事，我也很有经验。就算你想杀掉的家伙处于那些繁琐的规律和秩序的保护下，你也不需要有任何心理负担，我会把一切都处理好的。\n我保证，没有任何人能追查到你头上。\n想好人选之后，就把名字告诉我，无论我在哪里，都会立刻赶去帮你解决祂。\n祝你节日快乐，也希望你在我出生的这天感到快乐，守密人。\n\n\n希洛"
  },
  Mail_124774_Name = {
    Text = "经常杀人的人都知道\n……"
  },
  Mail_124774_Sender = {Text = "希洛"},
  Mail_124775_Desc = {
    Text = "好吧，显然你们没有准备停止这种行为，据我所知，那个我也已经习惯了「赠送礼物」的惯例。\n但有一天你会为这种善意后悔的，相信我。\n现在想想，那可能也是我最后悔的一件事，该死，我可没想过我会为了杀人后悔。\n没人比我更清楚，所谓歉意的毫无价值，不过在那一天到来之前，我会尽力做些什么来弥补，仅仅只是因为我想做。\n当你将来因为那件事怨恨我的时候，不用为此感到任何心理负担。\n我会全盘接受你们的怒火。\n\nH"
  },
  Mail_124775_Name = {
    Text = "你会后悔的"
  },
  Mail_124775_Sender = {
    Text = "血链·希洛"
  },
  Mail_124776_Desc = {
    Text = "守密人：\n\n又到了诞生的这天，按理说是庆祝拥有生命的日子，所以每当这天来临，我都会生出一些奇妙的感觉。\n我的出生似乎就是为了追逐死亡，当脱离死亡这个主题后，生命……或者说意识依然在延续的瞬间，对我来说到底意味着什么呢？\n生前，痛苦和愧疚的拉扯，和我的生命是如此难以分割地纠缠不清，以至于仿佛直到死亡来临后，生命才第一次真正属于我。\n去年、今年，或许还有今后的每一年。我拥有了漫长到几乎无尽的时间来体会，每一天都与前一天相似，又与前一天不一样。在生命不再被痛苦与目的缠绕的时候，它的终点会变成什么样子，或者所谓的终点，还会再到来吗？\n这个命题太庞大了，我有些想不明白。\n但想要记录下这些陌生思绪的情绪是如此真实，我又觉得答案好像昭然若揭。\n至少对我来说，是这些切实的、珍贵的瞬间，不论我的思绪是多么纷杂，不论我怎样地难以找到根系，我明确地知道，它们能够飘向哪里，被哪里接纳，而我也同样迫不及待地想将它们表露给您。\n或许明年的今天，我能找到一些更加自我的意义，不过现在，我希望能够自私地保留这些小小的，只有您和我知晓的依赖。\n是的，守密人，您和弥萨格的大家，是我内心无人知晓的根系。\n感谢您，一如既往地，愿您永远欢乐，永远安宁。\n\n宁菲亚"
  },
  Mail_124776_Name = {Text = "根系"},
  Mail_124776_Sender = {Text = "宁菲亚"},
  Mail_124777_Desc = {
    Text = "余最近发明了一种新的放松方式——神国午休。\n不同于一般短暂、仓促的午休，在进行神国午休时，余会离开久坐的青石王座，将腕触构建成阻绝声音的球体，再用特制海水填满整个空间。\n这些海水不仅可以发出余想要的香气、变成余想看的景色，更可从各个方向以合适的强度支撑余的身体。\n因此，无论余摆出何种动作，都可以体验到这般，如置身最高等羽绒床榻内的温暖包裹感。\n届时，余便可以在心仪的芬芳中放松心神，享受与世隔绝的宁静，枕靠余最喜爱的枕头安然入睡。\n作为余最中意的臣子，余认为生辰当日，最适合同你分享这份闲适。若你有意，可来上次跟你说过的秘密地点。无需担心你的安危，余会单独为你开辟一个空间，让你免受余外溢梦境的影响。\n别忘记带上你最舒适的枕头。\n\n图鲁"
  },
  Mail_124777_Name = {Text = "午休"},
  Mail_124777_Sender = {Text = "图鲁"},
  Mail_124778_Desc = {
    Text = "我的明灯：\n\n我与卡斯托尔已经适应了弥萨格的生活，逃离了教会血腥的尔虞我诈后，我感觉我正在找回过去的自己。\n虽然现在日常言行间还是不可避免的掺杂一些「圣子」的影子，但相信过不了多久，我便可将那傲慢和疏离完全洗去，仅保留对神明的谦卑和贯彻将行之路的决意。\n早些时候我收到了一份有些意外的礼物，是一本装裱精美的书籍，讲的是有关离乡之人回到故乡，找回自己童年的故事。与之一同送来的还有一张纸条，上面写着「祝你早日找回最初的自己」。\n这句话映入眼帘的第一幕，过往那些回忆便浮上心头——弥萨格大家的关心，明灯你的指引，还有兄长他……温暖的拥抱。\n因此今年生日，我想邀请弥萨格的大家，一同来参加我和哥哥的生日宴会。没有大家的帮助，我们绝无找回最初时光的可能。\n我用最近一段时间积攒的积蓄包场了一间饭店，那里的主厨对世界各地的菜系都有涉猎，相信每位都可以在那里品尝到自己最熟悉的味道。\n\n波吕克斯"
  },
  Mail_124778_Name = {
    Text = "找回童年"
  },
  Mail_124778_Sender = {
    Text = "波吕克斯"
  },
  Mail_124779_Desc = {
    Text = "我决定接受郊外的那家地下竞技场的邀请，去打一场生死不论的比赛。\n虽然在鳟鱼俱乐部的日子很好，可这太平淡了，每天不是杀鱼就是杀鱼，也许我确实彻底征服了鳟鱼，但征服鳟鱼可算不上征服！\n我体内的战士之血在沸腾，它们一直渴望一场令人血脉贲张的战斗，而现在，机会来了。\n跟我联系的那个秃头说给我找来了三条纳泰巨蟒，两头鬼面熊，四只瑟里纳森鳄和一堆我记不住名字的奇怪生物，足以让我尽情厮杀一整晚。\n我特地让他们把比赛安排在了今天，为的就是能在生日当天向你展示——我，尤乌哈希，最后的罗马战士，征服世上一切猛兽的盛况！\n今天洒满场地的将不再是鳟鱼边角料，而是鲜血和异兽猛禽的尸块！\n\n尤乌哈希"
  },
  Mail_124779_Name = {
    Text = "征服猛兽"
  },
  Mail_124779_Sender = {
    Text = "尤乌哈希"
  },
  Mail_124780_Desc = {
    Text = "「银钥骑士」：\n\n守密人！刚刚我正在改装「幻影号」的时候，莫丝突然给我送了一大——包零件，说是给我的生日礼物，我才想起来今天是我生日！\n所以我赶快写了封信给你，真是的，我怎么又把今天忘记了，明明我已经写了……写了多少张纸条来着？\n不过这些都不重要，重要的是，我想起来之前说的生日当天要干什么了——我要骑上「幻影号」，带着你和莫丝一起绕整个伦蒂尼恩一百圈！\n虽然莫丝完全不懂机械，但她那袋零件实在太多了，多到我可以找齐所有需要的零件。现在改装后的「幻影号」，已经是超级加强原型版了（暂时的）！\n我给这场冒险起了个名字，叫做诺缔拉与守密人与莫丝与「幻影」的冒险，怎么样，是不是很直接很好记？这样我就肯定不会忘记这场冒险啦。\n嘿嘿，真是令人期待呀，守密人再稍微等一下哦，「幻影骑士」诺缔拉和「漩涡骑士」莫丝马上就到！\n「幻影」冒险团，出击！\n\n正在开足马力冲过来的诺缔拉"
  },
  Mail_124780_Name = {
    Text = "「幻影」出击！"
  },
  Mail_124780_Sender = {Text = "诺缔拉"},
  Mail_124793_Desc = {
    Text = "尊敬伟大<Del:可爱>的守密人{Male=先生,Female=小姐}：\n\n咳咳，好久没有联系,我们亲爱的守密人{Male=先生,Female=小姐}想我了么~\n现在你可是弥萨格的大名人啦，所有学生都在学习你的英勇事迹，任何能稍微跟你沾上一点点边的东西都能在黑市卖出天价！\n不过这也正常嘛，毕竟谁让你是「活着的传奇」，弥萨格唯一的守密人呢？\n这一年里弥萨格也发生了很多有趣的事——奥瑞塔跟几个姜饼成为了朋友，朵尔教授为了给脑缸换个造型搞炸了十七个实验室，卡斯托尔被阿格里帕骗去帮她考试，结果那是门常识课，最终成绩比她自己考还差！\n哦对，还有那只可恶的小耗子，居然把我宝贵的胶卷偷走了，那可是我好不容易才拍到的「24」小姐的猫形态！\n除此之外还有很多，我把它们整理了一下，作为校报的新年特别刊一起寄给你啦。\n什么？你好奇我是怎么联系到你的？嘿嘿，这是秘密哦，我才不会说是我用了很多独家机密跟某位一看就很难对付的夫人换的呢！\n新的一年里就让我们一起努力吧，新年快乐，%player%！\n\n汉娜·皮斯利"
  },
  Mail_124793_Name = {
    Text = "新年特别刊"
  },
  Mail_124793_Sender = {
    Text = "汉娜·皮斯利"
  },
  Mail_124794_Desc = {
    Text = "苍白使者：\n\n银霜将至，请允许我先在这里向你表达最真挚的祝福。\n\n上次我去莉莉安济贫院探望孩子时，有些孩子偷偷问我「冬渡使者真的存在吗？」。\n我很好奇这些孩子为何会有这种想法，如果我没记错，去年应该每位孩子都收到了来自「冬渡使者」的礼物。\n结果孩子们对我说——「我看到那个帅帅的男人把礼物交给了戴安娜院长，他看起来一点都不像冬渡使者！」。\n想来应该是勋爵阁下为济贫院赠送礼物时，不小心被孩子们发现，才产生了后续的这些小小疑惑。\n\n因此今年银霜夜，我准备了两套非常传统的冬渡使者服饰，想请苍白使者你与我一同扮演冬渡使者，为这些孩子送上礼物。\n我相信一定会有孩子在晚上偷偷睁开双眼，记下我们红衣红帽的形象，再于冬渡节兴高采烈地告知大家——「我看到冬渡使者了！」。\n同时我也特地为你准备了一份礼物，希望你能喜欢。\n冬渡节快乐。 \n\n萨尔瓦多"
  },
  Mail_124794_Name = {
    Text = "冬渡使者"
  },
  Mail_124794_Sender = {
    Text = "萨尔瓦多"
  },
  Mail_124991_Desc = {
    Text = "尊敬的守密人：\n「多重疗愈·复刻」复刻活动已结束，现将守密人剩余的活动货币「记忆拼图」按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人记得查收。"
  },
  Mail_124991_Name = {
    Text = "记忆拼图回收"
  },
  Mail_124991_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_125448_Desc = {
    Text = "尊敬的守密人：\n「海城旧闻」活动已结束，现将守密人剩余的「梨膏糖」按照每枚兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
  },
  Mail_125448_Name = {
    Text = "梨膏糖回收"
  },
  Mail_125448_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_126321_Desc = {
    Text = "尊敬的守密人：\n「织者自缚」活动已结束，现将守密人剩余的「丝绒座票根」按照每枚兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
  },
  Mail_126321_Name = {
    Text = "丝绒座票根回收"
  },
  Mail_126321_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_126934_Desc = {
    Text = "守密人：\n\n又到了这个特殊的日子。呵，不必担心，今年我不会对你施加心理暗示，我只是想邀请我最特别的患者，去某个地方散散心。\n那里有繁茂的树林，清澈的河水，充满了自然的气息，能够令你忘却钢铁森林的疲惫。还会有柔软的地毯，温暖的火炉，明亮的灯光，助你舒缓城市快节奏的压力。\n我们可以在那里漫步、读书、谈天说地，无论你想要倾诉什么，我都很乐意倾听。\n啊，光是想象那样的情景，就已经让我心潮澎湃……\n我知道，此时此刻，你一定会有些不安。毕竟，我无法保证自己不去享受你那满是甜蜜的痛苦回忆。但你仍旧会来的，对不对？\n不单是因为今天是我的生日，也是因为，你需要着我，需要向我倾诉，需要我的倾听。\n乖孩子，我明白的，而且，我也会等待着你。来，忘记繁忙的日常和沉重的责任，享受这安宁的一刻。\n\n克莱门汀"
  },
  Mail_126934_Name = {
    Text = "安宁的一刻"
  },
  Mail_126934_Sender = {
    Text = "克莱门汀"
  },
  Mail_126935_Desc = {
    Text = "又是无聊的一天。\n我试过了很多法子——非利士传统的宴会，和伦蒂尼恩那些帮派玩一些小孩子把戏，没有一个能配得上作为巨人之王诞临之日的礼物。\n非利士人以战斗与杀戮为乐，曾经的这个日子，我与最强大的战士们在营地中欢聚、战斗，用力量与鲜血纪念这伟大的一天。\n和平。乏味的和平。我理解你们这些人对于和平的向往，并非每个人都有一颗属于战士的野心。不过，不要以为这些虚假的和平会影响到伟大的非利士之主。\n曾经属于我的一切，领土，财富，权力，非利士不灭的荣耀……在我夺回它们那一天，我会邀请你的，守密人。我会让你坐在我身旁最尊贵的宾客席位上，看着伟大的巨人之王重获他的荣光。\n本来打算直接结束这乏味的一天，不过我刚刚听说，那些被打散的帮派组建了一个联盟，要在今天的晚宴上围剿巨人之王。\n相比非利士人的战争，这只是个幼稚的游戏。不过在这无聊的和平日子里，能有这样的余兴节目，也值得让我感到欣慰。\n来重新见识下非利士之主征战的英姿吧。站在我身旁，或者站在我对面，怎样都行。\n不过要快一点。太晚的话，就只有收尸的份了。\n\n戈利亚"
  },
  Mail_126935_Name = {
    Text = "余兴节目"
  },
  Mail_126935_Sender = {Text = "戈利亚"},
  Mail_126936_Desc = {
    Text = "尊敬的守密人：\n\n您好。为了更好地服务弥萨格师生，艾瑞卡于前几天自行进行维护及升级，您幸运地被选为测评本次升级结果的人选。本次评估以线下方式进行，需要你对自动人偶艾瑞卡最新安装的LY-S-761号情感模块进行功能评价。该测试预计会占用您90分钟，请您提前做好规划，避免日程冲突。\n以下是本次测评的内容：\n1.请与艾瑞卡进行一段至少15分钟的开放式深度聊天，话题围绕「生日」进行，以测评艾瑞卡对特定情感的理解范围与深度。\n2：请模拟「赠送生日礼物」场景与艾瑞卡互动，以测评其情感识别与共情回应的准确性、灵活性及舒适度。\n3：请在测评中后期，有意提及艾瑞卡于前期对话中涉及的个人细节（例如她对于生日的态度、认知等），以测评其长期互动记忆与关联能力是否正常运行。\n\n请您在上述测评完成后，对艾瑞卡说「艾瑞卡，生日快乐」以结束测评，人偶将自动进入数据上传模式。\n感谢您的参与，完成测评后，艾瑞卡会赠送特殊小礼物。也请您在未来继续支持，您最贴心的助手艾瑞卡会永远陪伴在您的身边。\n\n艾瑞卡"
  },
  Mail_126936_Name = {
    Text = "生日升级测评"
  },
  Mail_126936_Sender = {Text = "艾瑞卡"},
  Mail_126937_Desc = {
    Text = "哈啊，今天是怎么回事，怎么无论我走到哪里，大家都在有意识地回避我？甚至我还没有开口，就连连摆手，说自己这里不舒服，那里疼痛，搞得我都没有办法开口要求决斗了。\n难得「生日」这天不需要什么理由，就能理直气壮和别人战斗，这样一来，岂不是和平常日子没什么两样？\n嘁，去年不应该把他们打那么惨的。但这也是没办法的事情，毕竟从这颗星球诞生前，我就在不断磨炼自己的剑技，寻常人无法承受，也是理所当然的。\n不过，你和他们不同，你可是守密人啊！\n所以你知道我想说什么吧？还是去年那个地点，让我们痛痛快快打一场吧。这次，不会有人打扰我们的战斗了。\n\n萝坦"
  },
  Mail_126937_Name = {
    Text = "唯一的对手"
  },
  Mail_126937_Sender = {Text = "萝坦"},
  Mail_126938_Desc = {
    Text = "最最最亲爱的主人：\n\n您听说了吗？今天市长豪宅会举行一场超豪华的舞会，所有绅士淑女都以能参加这个舞会为荣。\n当然啦，作为女仆，珈伦没有资格参加。但是您，弥萨格守密人，我亲爱的、最亲爱的主人，您配得上世界上一切美好的事物，当然也配得上这次舞会。\n所以珈伦已经替你接受邀请啦，还贴心地为你叫了马车，打点好了一切，到时候你只需要和珈伦一起前往市长家就可以了~\n珈伦会穿上自己最漂亮的衣服，带上自己最闪耀的首饰，让大家都见识到万能女仆的厉害，为您长脸，为您增光！\n啊，当您看到这封信时，我应该已经在您的门外等候了，那些马车啊，送来新衣服和首饰的仆人啊，也已经就位，唯一的小问题就是，这些服务还未付账……\n但我最善良可爱的主人绝不会为这些小事而烦恼，对不对？市长还在等着我们呢~\n\n您最可爱、最耀眼的女仆\n珈伦"
  },
  Mail_126938_Name = {
    Text = "豪华舞会"
  },
  Mail_126938_Sender = {Text = "珈伦"},
  Mail_126940_Desc = {
    Text = "守密人守密人！前几天，詹金说她找到了和奥瑞塔家很像的地方，好像叫做水……唔，奥瑞塔忘记了。\n总之，詹金说那里会有海豚、小鱼、水族馆和好多好多水母，还说它们都愿意成为奥瑞塔的朋友哦！\n奥瑞塔喜欢朋友，奥瑞塔想要很多很多朋友，所以奥瑞塔想在生日的时候，邀请自己最喜欢的朋友，也就是守密人一起去。\n快点收拾东西和我出发吧，奥瑞塔已经等不及了。\n\n想要认识很多很多新朋友的奥瑞塔"
  },
  Mail_126940_Name = {
    Text = "水族馆的新朋友！"
  },
  Mail_126940_Sender = {Text = "奥瑞塔"},
  Mail_126941_Desc = {
    Text = "守密人：  \n\n谢谢您今日凌晨陪我在海边散步，那些拍击的海水，明亮的星空，都令我感觉心安，也会令我想起了……很久很久以前的事情。\n那时候，船员们禁止与我交谈，所以大多数时间里，我只能眺望不断变化的海面，和盘旋在空中的海鸟。海员们望着那些海鸟飞翔的样子，会无意识向我许愿。\n偶尔，他们想要化为飞鸟，飞回家乡，飞回所爱之人的身旁；偶尔，他们想要航行快点结束，用船上的货物，换取富足的钱财；偶尔，他们也会祈祷遇到浪漫的爱情，或是邂逅传说中的海妖人鱼……\n但无论是多么繁杂的愿望，到了深夜也会变得统一，化为安眠的渴望。这时候，我会回应他们的祈望，令海风平和，令海水温柔。\n所以，如果守密人你也难以入眠，请不要凌晨再在海边独自徘徊，而是来寻找我吧。\n我想要分担您的压力，成为一个有用的人，而庇护你安眠，就是现在我所能做到的。\n这也是……我于这特殊的日子许下的「愿望」。\n\n希莱斯特"
  },
  Mail_126941_Name = {
    Text = "祝您安眠"
  },
  Mail_126941_Sender = {
    Text = "希莱斯特"
  },
  Mail_126942_Desc = {
    Text = "承命运洪恩，弥萨格大学守密人，贤明仁德之主君：\n\n万安！\n写这封信时，我一直在犹豫，但诚实亦是骑士的美德之一。作为主君的骑士，我需对您献出全部的忠诚，绝无隐瞒，故我也必须对你说实话——\n在生日这一天，主君，我请求您来到我的房间，为我阅读睡前故事。\n请允许我……靠在主君的身边，在您所讲述的那些梦幻而美好的故事中入眠。\n其实，这曾是我幼年时的期愿之一。但骑士的训练容不得一刻怠惰，我也早已过了听故事的年纪，所以，我一直将它埋在心里，从未诉之于口。但您……主君您是不同的，我不想对您隐瞒什么……\n如果主君您觉得不妥，也请告知于我。从此我不会再提出这样过分的请求，加倍刻苦训练。\n等待您的回复。\n\n奥吉尔"
  },
  Mail_126942_Name = {
    Text = "骑士的请求"
  },
  Mail_126942_Sender = {Text = "奥吉尔"},
  Mail_126943_Desc = {
    Text = "小煤球：\n\n今天，莫丝，生日！\n朋友说，生日，写信，给小煤球，小煤球，会来，玩！\n莫丝，不会，写信。但是，朋友，会！\n朋友，教，莫丝。莫丝，开心！\n其实，莫丝，忘记了，生日。\n但是，莫丝，想跟，小煤球玩！\n所以，莫丝决定，今天，就是生日！\n小煤球，贝壳，收集，金色，白色，都有~\n看到小煤球，开心~朋友，做饭，好吃~\n小煤球，老地方~\n让朋友，做了，大餐！一起吃！\n莫丝，等你~\n\n莫丝"
  },
  Mail_126943_Name = {
    Text = "生日！来玩！"
  },
  Mail_126943_Sender = {Text = "莫丝"},
  Mail_126944_Desc = {
    Text = "守密人： \n\n前几日，您说过想要向流星雨许愿，所以我特意安排了此次航行。感谢您接受了我的邀请，我会按照约定，准时在海边等待您的到来。\n请您放心，此次为短期航行，我也已经彻底查清了附近的海域，保证带领您平安航行到流星雨降落的位置，并协助您获取陨石。\n这样，您就可以亲手碰触到流星许愿，而在这样近的距离下，流星也一定会倾听到您的心愿，实现您的心愿吧！能够成为引领您许下心愿之人，将是我做过的最特殊的事情之一，我深感荣幸。\n再次感谢您，是您让我在这个特殊日子找到了新的「领航使命」。请您务必按时赴约，我会一直等候您的到来。\n\n克珀珊特"
  },
  Mail_126944_Name = {
    Text = "\n\n触手可得的心愿"
  },
  Mail_126944_Sender = {
    Text = "克珀珊特"
  },
  Mail_129637_Desc = {
    Text = "展信安：\n\n不记得第几次穿过钟楼后的花圃时，我曾偶然留意过其中的玫瑰园。\n此后我数次踏过此地，经历黑池不安涌动的时刻、死亡与对峙的时刻、时序洄流逆转的时刻，它们都凌然地、静静地伫立在那里，一如既往。\n这一画面唤醒了不属于我的记忆中，拉蒙娜曾想赠与你的那捧玫瑰，我也因此稍感安心。\n尽管你我二人遥隔维度，但我始终相信，无论遭遇何种困境，你与那个「拉蒙娜」总能保持冷静无畏的姿态，找到破局之路。\n毕竟，无论世情如何变迁，玫瑰们总是兀自绽放。\n\n「拉蒙娜」"
  },
  Mail_129637_Name = {
    Text = "玫瑰花圃…"
  },
  Mail_129637_Sender = {
    Text = "「拉蒙娜」"
  },
  Mail_129806_Desc = {
    Text = "守密人：\n\n海城的宅邸里，华灯已上。不知您此刻身在何处，身侧何人？\n岁初，古国最重要的日子，一个庆贺团圆与新生的节日。这一天，妾身已经历过许多次，但从未感到过腻烦。寒冬已过，万物生长，人们是如此地盼望，盼望着能像这片土地一样，把一切的不堪都抛诸昨日，迎接一个新的开始。\n那些陈旧的伤口与欲念，并非能够轻易抛弃之物。辞旧，迎新，多么美好祝愿啊……或许疼痛会重新生长，欲念将永不消逝，可今夜，至少今夜，人们将举杯欢庆，庆贺一个新的世界、新的自己。\n因此，在旧年与新岁交替之时，人们便以烟火相迎。\n在一切有趣的事物中，烟火是妾身的挚爱之物。所有人都看着它，看它燃烧，升空，绽放，如同仰望神明一般，仰望那短暂的、无与伦比的辉煌。\n您有注意过吗？在仰望烟火的时候，每个人的心里都是干净的。他们忘记了仇恨，忘记了苦难，忘记了所有的肮脏不堪。一切人心都变成宁静的湖，纤尘不染的湖面上，只有烟火美丽的倒影。\n嘘……不要问烟火之后是什么。新生或许是种奢求，但，不要因此辜负了它的绽放。\n在所有不堪的事物里，烟火是最为纯净的东西。今夜，妾身愿将自己那份也赠予您。\n抬起头来，不要眨眼。看着那些璀璨的星辰升起，在烟火绽放的时候，迎接一个新的自己吧，守密人。\n\n「千扇」"
  },
  Mail_129806_Name = {Text = "烟火"},
  Mail_129806_Sender = {Text = "徐"},
  Mail_130223_Desc = {
    Text = "尊敬的守密人：\n「颠倒的新生」活动已结束，现将守密人剩余的「纯白鳞粉」、「红色鳞粉」、「耀光鳞粉」按照每枚兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
