  Mail_131093_Desc = {
    Text = "尊敬的守密人：\n「燃烧的群宴·复刻」活动已结束，现将守密人剩余的「原生胫骨」、「圆叶菊石」和「螺旋遗迹」按照每个兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
  },
