  Mail_131093_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_131767_Desc = {
    Text = "吾@2！@3乃@2至高@3混@4与毁@2！高呼@4……！\n\n哎呀呀！看看你都干了些什么！！！你触碰到了至高神明的禁忌！这下好了，祂的低语已经响彻你所在的世界，黑色的灾难将从你的通讯器开始蔓延，吞没你身边的一切……\n小可怜，你的莽撞真的让我很难办。但也不用太绝望，不幸中的万幸，你遇到了我——伟大的教派仙女、神明应选之人、至高之神的代行者、宏大教派的法定继承者、苦难的解救者、神王的挚友！我是善意与关爱之神的意志，见不得这世间的苦难，我将用我至高无上的力量，拯救每一位愚笨的小捣蛋鬼。\n噢，本仙女看见了你嘲讽的眼神。没有关系，善神爱世人，从不介意世人的愚钝。对救世主的不信任，是每一个信徒的必经之路。这些见面礼，便是神的代行者对你的恩赏。\n现在，光明的道路已经为你指明：带上你的诚意，去到位于@3城的@2大教堂，向善意之神献上你的忠诚，你便将获得梦寐以求的力量，从这噩梦的诅咒之中解脱。当然，需要一并献上的还有你的财富。请不要误会，善意之神从不在意世俗的回报，但祂的信徒们办事也是需要花钱的。不要吝啬这些俗气的东西，亲爱的信徒，一分钱一分货。\n高呼善意之神的名号，等待着神迹降临的时刻吧！\n\n伟大的教派仙女，神明应选之人"
  },
  Mail_131767_Name = {
    Text = "请勿触碰本@2"
  },
  Mail_131767_Sender = {Text = "卡拉布"},
  Mail_132339_Desc = {
    Text = "尊敬的守密人：\n「神王复苏·复刻」活动已结束，现将守密人剩余的「惫倦绪思」、「悲愁绪思」、「欢悦绪思」按照每个兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
