  Mail_132339_Name = {
    Text = "神王复苏货币回收"
  },
  Mail_132339_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_132458_Desc = {
    Text = "尊敬的守密人：\n        感谢您对《忘却前夜》的支持和认可，为了让守密人在弥萨格大学有更好的游戏体验，诚邀您填写以下体验调研问卷。为感谢您的配合，我们准备了「银芯」× 200 作为奖励，完成问卷即可领取。问卷截止时间8月17日9:00，请注意及时填写。\n        <SurveyLink:【点击前往填写】>\n        我们会认真听取每一位守密人的建议，您的反馈也一定会使弥萨格大学越来越好！\n        ——愿银钥指引前路。"
  },
  Mail_132458_Name = {
    Text = "版本体验调研问卷V2.5.3"
  },
  Mail_132458_Sender = {
    Text = "弥萨格校务处"
  },
