  Mail_132605_Desc = {
    Text = "唧唧唧，唧唧唧唧唧！\n（守密人，愚人节快乐！）\n唧唧唧，唧唧！\n（证件照，留念！）\n「杂乱的潮湿海獭爪印」\n「一大堆火漆滴蜡失败留下的模糊贝壳拓印」\n                                                         ——一个端端正正的海獭爪印落款"
