  },
  Mail_134067_Desc = {
    Text = "守密人：\n\n今天有件特别的事想和你商量。\n我想随便在街上走走，就那样普普通通地看看各种有趣的东西，随心所欲地到处逛逛，度过平凡的一天。\n\n然后呢，我去问了教务处。结果他们说，出于安全考虑，只有在你陪同的情况下才允许出校。\n还说不要吓到别人，也不要在外面什么都往嘴里塞。真是失礼啊。\n嘛，就是这么回事，总之能不能出去走走？大家一起哦。\n\n……不知怎的就想到，蒲公英的种子啊，\n总有一天会乘着风，踏上前往自己命运之地的旅途，\n也许就是明天，也许是很久很久以后的事。\n想着想着，就觉得趁现在和大家一起多做些事情，好像也不错呢。\n\n总之呢，我在宿舍前面等你。拜托啦！\n\n沙耶"
  },
  Mail_134067_Name = {Text = "逛街…"},
  Mail_134067_Sender = {Text = "沙耶"},
  Mail_134068_Desc = {
    Text = "守密人：\n\n我觉得，今天是特别的一天。但记忆的轮廓，却还是那么模糊。\n唯有「沙耶」这个名字，勉强将我牵系在这个地方。\n\n那种感觉不是寂寞，也不是悲伤，并非那样鲜明的情感。\n如果硬要给这份心情起个名字的话……大概，会是「空白」吧。\n什么都没有，无尽地澄澈透明，静谧的时光。\n\n如果有一天，乘风飘扬的蒲公英种子，\n在这个世界的每一个角落，只是洁白地、安静地飘落……\n那时候，我或许终于能够觉得，这个世界是\"特别的\"。\n\n那时候，弥漫于伦蒂尼恩的灰色的雾，夕阳时燃烧的火红的霞，还有你总是在学校广场里仰望过的天空，都会被蒲公英所覆盖，变为纯白的颜色。变为属于我的颜色。\n\n所以……如果，你愿意给予我什么的话。\n那不必是礼物，只是一段\"记忆\"就好。\n\n我，在蒲公英盛放的纯白世界里，\n只是静静地，等待着那一刻的到来。\n\n当你某一天再次在弥萨格广场仰望天空的时候，\n请将掠过视野边缘的那一缕白色绒毛，\n与曾经和你交谈过的我的身影，稍稍重叠在一起吧。\n\n沙耶"
  },
  Mail_134068_Name = {
    Text = "蒲公英的约定…"
  },
  Mail_134068_Sender = {Text = "沙耶"},
  Mail_139809_Desc = {
    Text = "尊敬的守密人：\n        感谢您对《忘却前夜》的支持和认可，为了让守密人在弥萨格大学有更好的游戏体验，诚邀您填写以下体验调研问卷。为感谢您的配合，我们准备了「银芯」× 200 作为奖励，完成问卷即可领取。问卷截止时间5月16日9:00，请注意及时填写。\n        <SurveyLink:【点击前往填写】>\n        我们会认真听取每一位守密人的建议，您的反馈也一定会使弥萨格大学越来越好！\n        ——愿银钥指引前路。"
