    Text = "尊敬的守密人：\n「镜像囚徒·复刻」活动已结束，现将守密人剩余的「常识之书」、「数理之书」、「文学之书」按照每枚兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
