  },
  Mail_141507_Desc = {
    Text = "守密人：\n\n诞生之日，于你而言，这或许是一个重要的日子吧？\n于我而言，命运之网上每一天的重量都是均等的。是其他的故事，为这个日子赋予了特殊的意义。\n我在这一天诞生，在这一天领悟预言，在这一天得到编织命运的纺轮，在这一天看到那些繁复的命运丝线、还有丝线尽头的噩梦。\n对命运的编织者，这一天碌碌无奇。对舞台上的演员，这一天值得庆贺。而在所有的身份里，更令我欢悦的，是作为演员的自己。\n守密人，今日，命运剧院的灯光皆已熄灭，只有一个舞台灯火辉煌。你曾提到过，想要更多的看到我曾经历过的命运。而现在，这座舞台将要上演的，便是一段关于我自己的故事。\n我并不知道它将要上演的是哪一段。我将回忆送上舞台，她将在那些强烈的时刻中，选择一段你最期待看到的，在今夜的舞台上呈现。\n那故事或许令我痛苦，或许令我难堪，但这些并不重要，不是么？我想，偶尔让纺轮自己编织，做一个纯粹的观众，是一件令人愉悦的事。\n这场演出唯一的入场券，现在已经在你的手上。带着这封信件前来吧，守密人。今夜，一段再无他人知晓的故事，等待着你的到来。\n\n阿拉克涅"
  },
  Mail_141507_Name = {
    Text = "隐秘的故事"
  },
  Mail_141507_Sender = {
    Text = "阿拉克涅"
  },
