  },
  Mail_142101_Desc = {
    Text = "好久不见，%player%：\n\n当你收到这封信的时候，我应该正经过亚格罗的上空，每年的这个月，我的巡猎旅程总是会更远一些。\n没有什么比敌人的惨叫和痛嚎更适合作为生日配乐了，何况我准备了足够的牢笼，只要还有蠢货敢信奉那些除了痛苦，不会带来任何救赎的伪神，无论天涯海角，我都会让他们意识到自己的错误。\n偶尔，在魇穿过云层，能够看见月亮的时候，确实会有些荒唐的念头从我脑海里一闪而过。\n比如这种时光会在何时突如其来、无可违逆地被迫停止，就像生活当初毫无征兆地陷落一样。\n不过随后我就会被自己逗笑，当我踏入它的那天，我就在一条没有退路的征程上，我相信你一定明白我的意思，小朋友。在这个世界上，没有比你和我境况更相同的人。\n我们都选择了一些没有选择的选择，好消息是，我们都很享受自己的选择。\n新的一年，只要吹响我送给你的猎哨，我依然会随时出现在你身边。\n当然，如无意外，还是先让我专心享受这趟旅程吧，下个月，我会带给你纪念品和一些新的见闻。\n祝你一切顺利，祝你快乐。\n\n你亲爱的「舅舅」"
  },
  Mail_142101_Name = {Text = "见闻"},
  Mail_142101_Sender = {
    Text = "你亲爱的「舅舅」"
  },
