  Mail_145468_Desc = {
    Text = "尊敬的守密人：\n「如果一切如常·复刻」活动已结束，现将守密人剩余的「海滨特产贝壳」按照每枚兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
