  Mail_145468_Name = {
    Text = "海滨特产贝壳回收"
  },
  Mail_145468_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_146401_Desc = {
    Text = "历法是一种无聊的发明。所有日子都没有什么区别，包括今天。\n按照你们的历法，今天是我诞生的日子。诞生这个词对我而言不算准确。我是一块从混沌中被撕扯出来的残骸，在无数场战斗中磨砺成形的刀刃。铸就我的不是母体，是每一个曾与我交锋的对手。而你，是他们中至关重要的一位。\n你们很重视这样的日子。宴会，礼物，祝词——我不需要这些。\n我只需要一场战斗。\n这段时间以来，你做过许多不可思议的事情。但我知道，你所展示出的，还远远不是你的极限。\n今天黄昏，训练场。带上你的武器，我会在那里等着你。不必在意胜负，不必顾虑伤亡。剑刃毫无保留相撞的那一刻，是我唯一期待的贺礼。让我看看，一块@4的碎片，究竟能做到些什么。\n我想，你会让我感到惊喜的，我的「对手」。"
  },
  Mail_146401_Name = {
    Text = "唯一的期待"
  },
  Mail_146401_Sender = {
    Text = "蚀灭·萝坦"
  },
  Mail_146873_Desc = {
    Text = "尊敬的守密人：\n「临时文本」活动已结束，现将守密人剩余的「临时文本」、「临时文本」、「临时文本」按照每枚兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
