  Mail_148478_Desc = {
    Text = "尊敬的守密人：\n        在第 {s1} 期「学期课题-高阶课题」中获得的奖励尚未领取，现以邮件的附件将未领取的奖励发放给您，注意及时清理背包后领取。"
