  Mail_148478_Name = {
    Text = " {s1} 期高阶课题未领取奖励补发"
  },
  Mail_148478_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_148514_Desc = {
    Text = "尊敬的守密人：\n        在 V1.4.3.5 版本更新中，我们于「异梦视界：亵渎」新增了关卡「新王」。由于部分守密人未及时知悉这一更新内容，误以为「异梦视界：亵渎」已全部通关完成。\n        为此，在本次 V2.6.2 版本更新中，我们已为更新前已通关「新王」后续关卡的守密人补齐「新王」关卡的通关进度，并同步补发相应的首通奖励，请查收。"
  },
  Mail_148514_Name = {
    Text = "「亵渎」进度补齐"
  },
  Mail_148514_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_148515_Desc = {
    Text = "亲爱的守密人：\n\n嗒哒~是不是出乎预料呢？这是本仙女在弥萨格的第一个生日，所以——\n居然！没有任何促销邮件、礼拜邀请，甚至连末日预言也没有~\n不过不必失望，本仙女当然是有给最特殊的教徒准备一些更珍贵，更好的福利啦。\n作为全知全能的仙女教母，当然能够预料到那些理所当然的疑惑和防备，虽然那会让本仙女感到些许伤心难过，不过，为了普及教派的福泽，轻微的牺牲总是在所难免。\n所以，请退一万步思考，来试一试嘛，反正也不会有什么损失，万一是真的呢？对不对？\n这可是一年仅一次，无论如何都不该错过的机会哦~\n不需要任何供奉，也不需要任何许诺与交换，仅仅只需要与仙女教母共进一场甜蜜的下午茶，您就能够得知冰雪之下，到底埋藏着多少对您真挚的感情。\n这难道不是一个具有诱惑力的提议吗？\n备注：请务必携带足够用于买单的至少10、100、1000雷欧坊，多多益善。\n\n在那家我们都知道的店等待着您的\n卡拉布"
  },
  Mail_148515_Name = {
    Text = "☆☆☆超级福利邮件☆☆☆"
  },
  Mail_148515_Sender = {Text = "卡拉布"},
  Mail_149949_Desc = {
    Text = "此信已在阴阳两界流转千遍，切勿删除！\n\n七月半，鬼门开，阴风起，幽魂归。\n吾乃磐龙古国扈城■■■，一纸陋是也！\n奉中元敕令、持招魂符牒，今夜降咒于此。见字之人，魂将入册，名已上簿，若不在子时前转与五十位阳世之人，必将——\n文书临存档前一息崩坏……\n啵啵奶茶必短三颗珍珠……\n银芯通讯器电量永远卡在1%，充之不盈……\n\n乖乖照做，咒自解，符自焚，厉鬼不缠，灯亦长明。\n转发！！立刻！！！"
  },
  Mail_149949_Name = {
    Text = "【中元警告】胆敢删信者，必遭……"
  },
  Mail_149949_Sender = {Text = "一纸靥"},
  Mail_149985_Desc = {
    Text = "主君：\n\n唐突来信，希望不会令您感到冒昧。但有些心事，只有对您才能倾诉。\n昨夜，我久违地做了一场梦，在梦里，我回到了旧日的家中。一切都那么亲切，父亲温柔宽厚的手掌，女佣在清扫时哼出的乡野歌谣，还有那匹属于我的白色矮种马......我本以为，它们早已被我遗落在记忆的泥沼，重新在梦中见到，还是那样的温暖。\n醒来后，我看见窗外弥萨格的师生正闲聊着路过，如此宁静美好，一时间竟让我觉得，这幅画面和梦里也没什么不同。 同时，我还发现，那附着在我身上的无形之物，自今晨起一直十分安静。难道说，生日这天真的会遇上些幸运的事吗。\n若当真如此，或许，我也可以在今日贪心一次......\n我知道人们往往喜欢在生日当天许愿，作为对一整年的期许。我早已不敢奢望获得谁人的生日祝愿，但的确有一个想要获得的机会。\n正如主君将信任交付给我一样，我也不会对您有所保留，因此，请准许我将愿望告知与您：\n如果下次主君有任务安排的话，请任命我为护卫，与您同行吧。\n无论如何，我希望在您最需要帮助的时候，永远能第一时间挡在您的身前，成为您最坚实的护盾。\n这便是我为今年许下的心愿。\n\n奥吉尔"
  },
  Mail_149985_Name = {
    Text = "生日愿望…"
  },
  Mail_149985_Sender = {
    Text = "负誓·奥吉尔"
  },
  Mail_18019_Desc = {
    Text = "亲爱的守密人：\n系统检测到当前账号进行了一次退款行为。制作组已于{s1} 根据您的退款订单对应的虚拟货币部分进行了扣除。若相应货币在扣除后出现负数，则需要恢复为正数后才能正常适用。\n如有疑问请和客服联系。"
