  },
  Mail_18029_Desc = {
    Text = "你好，守密人，这是您在幻梦深潜中获得的排行奖励。"
  },
  Mail_18029_Name = {
    Text = "幻梦深潜排行奖励"
  },
  Mail_18029_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_18031_Desc = {
    Text = "亲爱的守密人：\n\n前路漫漫且荆棘密布，在这样艰辛的时刻，我们更需要彼此同协，一同前进。\n随信附上今日特批的灵啡肽补给，还请收下。\n愿银钥指引前路。\n另：本次特批补给至此发放完毕，感谢您的辛勤与努力。\n\n弥萨格校委会后勤部"
  },
  Mail_18031_Name = {
    Text = "鞘内补给发放"
  },
  Mail_18031_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_18034_Desc = {
    Text = "你好，守密人，您在幻梦深潜累计积分奖励未领取，现以邮件的附件将奖励发放给您。"
  },
  Mail_18034_Name = {
    Text = "幻梦深潜累计奖励未领取"
  },
  Mail_18034_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_18035_Desc = {
    Text = "亲爱的守密人：\n\n前路漫漫且荆棘密布，在这样艰辛的时刻，我们更需要彼此同协，一同前进。\n随信附上今日特批的灵啡肽补给，还请收下。\n愿银钥指引前路。\n另：您的特批补给剩余{s1}天，请合理安排调查时间。\n\n弥萨格校委会后勤部"
  },
  Mail_18035_Name = {
    Text = "鞘内补给发放"
  },
  Mail_18035_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_20231_Desc = {
    Text = "亲爱的守密人，相位对弈的新赛季开始了，您的段位从 {s1} 重置为{s2}。新赛季段位奖励已重置，可通过提升段位获取更多荣誉与奖励！{s3}\n{s4}"
  },
  Mail_20231_Name = {
    Text = "相位对弈赛季邮件"
  },
  Mail_20231_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_21453_Desc = {
    Text = "亲爱的守密人：\n\n冒昧打扰，不知您最近还好吗？\n抱歉在百忙之中打扰您，詹金他们给我准备了一个小型生日宴，我想了很久很久，还是决定自己来给您送出这封邀请函。\n工坊收留的孤儿大多记不住自己的出生日期，莎拉小姐就把我们出现在孤儿院的日子定为我们的生日。只有我不一样，莎拉小姐说，我是在一个极度寒冷的冬夜被丢在济贫院门口的，她想要我的一生不再冰冷苍白，所以选了一个温暖的日子作为我的生日。所以，这是一个我的、被关心被爱护着的日子。这对我来说是重要的一天，我希望守密人也能来与我一同度过，这是我的一个小小心愿。当然，不能被满足的话也没关系，因为守密人有很多事情要处理，艾继丝知道的。\n如果这份邀请给您添了任何麻烦，请您一定要告诉我，并接受我诚挚的歉意。但如果、万一您真的能腾出时间来的话，也非常非常欢迎您来参加他们的胡闹，说不定、有可能会非常有趣，毕竟是詹金准备的嘛。\n\n艾继丝"
  },
  Mail_21453_Name = {
    Text = "百忙之中打扰…"
  },
  Mail_21453_Sender = {Text = "艾继丝"},
  Mail_21454_Desc = {
    Text = "喂：\n我一直搞不明白，出生的日子到底有什么好值得庆祝的？值得大家如此大动干戈？\n去年的今天，有个学生来问我的生日日期。笑死人了，我诞生那时，这个星球上还没有时间的概念，更别提生日了。但她缠得我实在没办法，我就告诉她「是昼夜交汇平分的时候」，也不知道她最后是怎么理解的。\n写这封信，是为了提醒你，今晚12点后记得把我房门口那些花收起来，熏死人了！\n\n萝坦"
  },
  Mail_21454_Name = {
    Text = "那些花…"
  },
  Mail_21454_Sender = {Text = "萝坦"},
  Mail_21455_Desc = {
    Text = "艾瑞卡今天送来了一大包咖啡，说是我的生日礼物，还说里面是你今年一整年的配给。<Del:但 你是自愿的吗 如果不>\n 如果这是朵尔还是谁给你做的恶作剧，那虽然很舍不得，我还是可以把它……还你。毕竟那可是咖啡！我少喝两杯都困得不行，一整年不喝？你怕不是会睡得和图鲁一样。倒不是说他不好，就是，黑色的东西会在夜里出现……总之，如果你需要的话，随时可以将咖啡拿回去，当然如果你把咖啡留在这里，<Del:我也 那就>我想我会非常高兴的。这样我就终于可以做我想做的那个实验：将咖啡因提取并浓缩成可以通过表皮吸收的药剂，贴在身上一直保持清醒，一直一直……\n\n\n很希望进行这个实验的温柯尔"
  },
  Mail_21455_Name = {
    Text = "咖啡……"
  },
  Mail_21455_Sender = {Text = "温柯尔"},
  Mail_21456_Desc = {
    Text = "生日？\n非要说的话，我的生日可不是什么好日子。成百上千个无辜的生命在这一天死去，就为了让我「出生」，然后去杀死更多的人。\n所以，这一天也没什么值得庆祝的。不过我明白你们人类都是很注重「仪式感」的生物，刚好我手上有一笔钱——放心，是我在鳟鱼俱乐部出卖汗水赚的辛苦钱，不是什么非法收入。\n收下这笔钱，拿去给自己买个礼物吧，就当是庆祝我的生日了。\n\n尤乌哈希"
  },
  Mail_21456_Name = {
    Text = "生日……"
  },
  Mail_21456_Sender = {
    Text = "尤乌哈希"
  },
  Mail_21457_Desc = {
    Text = "守密人：\n\n在弥萨格地界内，存在庆祝生日的习俗吗？\n我那记忆中的故国……每年都会举办盛大的仪式，以庆祝王的诞辰。\n久而久之，「生日」的特殊意义就被赋予了所有人。\n在久远的过去，每逢生日这天，同僚与亲友们都会不远万里来到我身边。\n那被亲爱的人们簇拥围绕的感觉……那如同被太阳拥抱着的温暖……也许正是我无法割舍过去的原因吧。\n啊……扯远了，我打扰到您工作了吗？\n我准备了一些过去常用的茶点，想要与您分享。\n如果您愿意赏光，请在晚饭后来找我吧。\n\n法洛思"
  },
  Mail_21457_Name = {
    Text = "不灭的光…"
  },
  Mail_21457_Sender = {Text = "法洛思"},
  Mail_21458_Desc = {
    Text = "今天确实是个值得纪念的日子：这一天，伟大的戈利亚之主、巨人之王降临于世；这一天，海洋为之震颤，星辰为之失色。\n听说校园里不允许铺张浪费，那就按以往规格的十分之一来操办我的生日晚宴吧——十份烤乳猪、一百串烤章鱼以及能演奏戈利亚民谣的乐队，对了舞女最好也给我来一打……\n什么，这些都不被允许？\n那就只要舞女吧……不用一打，四五个就够了。\n什么，这也不允许？！\n这样寒酸的规格可配不上我的身份。现在我宣布，晚宴计划取消！\n\n戈利亚"
  },
  Mail_21458_Name = {
    Text = "晚宴计划……"
  },
  Mail_21458_Sender = {Text = "戈利亚"},
  Mail_21459_Desc = {
    Text = "守密人——\n\n今天在茜尔维娅女士那边做记忆训练的时候，她问起了我的生日。你也知道我的，刚刚放下的扳手我转头就能忘了，怎么可能记得生日！更严重的是，这还是一个只有我知道的东西，我！这生日算是没啦。\n\n不过萨尔瓦多神父说具体的日期不重要，重要的是我庆祝什么每一天什么的，所以我决定了，今天就是我的生日！我已经和一个人（我忘了是谁了，应该不是你吧，守密人？）约好了在食堂门口举办派对，你可一定要来哦！\n\n\n\n绝对绝对会记得这个生日日期的诺缔拉\n\n\n\n一张和信一起送来的纸条：\n\n那孩子写完信就风风火火地走了，把信和一些说是要给你的礼物都忘在了桌上。\n东西我都附在信封里了，期待晚上和你在派对上相见。放心吧，我会提醒她今晚到场的。\n\n——茜尔维娅"
  },
  Mail_21459_Name = {
    Text = "我决定的生日！"
  },
  Mail_21459_Sender = {Text = "诺缔拉"},
  Mail_21460_Desc = {
    Text = "小家伙： \n\n原质之海中没有星辰日月，也没有四季交迭，因此，我的生日应当被记载为【不明】。\n但今天的确是个重要的日子，毕竟，这副形貌还是继承自某个怀有「心愿」的人类的。她喜欢热闹，所以开设了这间小店，但又因为四处调查，她的生日往往都是由我一人陪伴。为了圆她生前的心愿，解忧小铺今天将会举办烛光餐会，诚邀各位忠实客户到场。\n当然，解忧小铺也会为所有光临者提供一个小小的折扣，还请小家伙不要错过。\n\n达芙黛尔"
  },
  Mail_21460_Name = {
    Text = "人间心愿…"
  },
  Mail_21460_Sender = {
    Text = "达芙黛尔"
  },
  Mail_21461_Desc = {
    Text = "当年被从家人身边带时，养母…执政官夫人把写着我出生的陶片摔得粉碎，把我曾为提洛人的过去摔得粉碎。真正的生日，自然已经无从说起了。\n拉伊一别后，我也思考了一番……如果把我逃离牢笼、开始复仇的那一夜作为我的「生日」，你觉得如何？\n虽然现在已经没有纪念年长一岁的必要，但作为时间更迭的一个提示，似乎也不错。"
  },
  Mail_21461_Name = {
    Text = "出生的日子"
  },
  Mail_21461_Sender = {Text = "希洛"},
  Mail_21462_Desc = {
    Text = "测试，测试。\n尊敬的守密人，你好。如果你收到此封信件，说明你的意见对艾瑞卡而言至关重要，并被选中参与自动人偶艾瑞卡的语言模块功能年度检测与维修计划。本次评估以简答题的形式进行，需要你对自动人偶艾瑞卡最新安装的EA-L-1033号语言模块进行功能评价，不会占用你太多时间，还请你不必紧张和惊慌。\n简答题：\n请问你是否看懂了本封信的大意？\n\n请将回复直接填写在简答题下方的空白处，并将信件重新装回信封。\n感谢你的参与。\n\n艾瑞卡"
  },
  Mail_21462_Name = {
    Text = "测试，测试……"
  },
  Mail_21462_Sender = {Text = "艾瑞卡"},
  Mail_21463_Desc = {
    Text = "守密人：\n\n你是这所学校里难得清醒的人，你的目光能够穿透这残缺之身，看见真实的我。\n这样的你，一定能向那些小孩解释清楚：我不是什么美人鱼，此身终蹈海越山，成就完美之躯。\n……算了，也不为难你。但至少今天，不要让他们玩我的尾巴了。\n今天的日子，算得上特殊。如果你有时间，我会有些事想亲口说给你听。\n\n凯刻斯"
  },
  Mail_21463_Name = {
    Text = "完美之躯…"
  },
  Mail_21463_Sender = {Text = "凯刻斯"},
  Mail_21464_Desc = {
    Text = "守密人：\n\n我在俗世意义中的生日，是父亲当初收养我的日子。\n过去他总是格外重视这天，每年都要大办舞会——穿着束腰跳舞，可比挥剑三千次还要累。\n但这是他身为父亲的心意，我不希望辜负这份来之不易的爱。\n不过今年，他终于答应让我自己安排生日行程了。也许在父亲眼里，我已经不是需要放在眼皮下看顾的小孩了。\n对了，你能陪我去钟楼顶吗？聊聊天，吹吹风。\n听说，今夜会是个满月夜。\n\n拉蒙娜"
  },
  Mail_21464_Name = {Text = "满月…"},
  Mail_21464_Sender = {Text = "拉蒙娜"},
  Mail_21465_Desc = {
    Text = "亲爱的、最亲爱的主人：\n是的没错，今天就是珈伦@1岁的生日了哦（女士的年龄要保密）！\n为此珈伦准备了一场无与伦比的盛大派对，还邀请了所有能邀请到的小伙伴~！虽然最后答应来的只有奥瑞塔、奥吉尔和莉莉……\n不过没关系，有人的地方就有派对，有派对的地方就有珈伦！珈伦为此还精心准备了「改良版」蟾蜍炖菜、蒜香泥煤蛞蝓以及咖喱蝙蝠汤，主人一定要来尝尝哦~\n\n悄悄问一句，主人一定准备了礼物给珈伦吧？记得要亮闪闪的哟！\n\n您永远谦卑的女仆\n珈伦"
  },
  Mail_21465_Name = {
    Text = "礼物……"
  },
  Mail_21465_Sender = {Text = "珈伦"},
  Mail_21466_Desc = {
    Text = "亲爱的<Del:守密人>西区佬：\n这是一封<Del:邀清喊 要请汉 邀请喊 邀请>总而言之是请你来吃免费蛋糕，顺便庆祝我的生日！其实也是为了感谢你之前帮我找到姐姐，还把我带到这里来，给我和布朗一个可以安心呆着的地方。\n（上面这些是艾继丝要我写的，可肉麻了。我们之间的交情可用不着这些，对吧，守密人？）\n总之，今晚在你宿舍后面的院子里，我、布朗和艾继丝亲手准备了一些好东西，等着你来一起分享！当然其实主要是艾继丝在做，她做东西可好吃了，厨房里的太太们都夸她有天赋呢，你要是不来的话，保管你后悔。\n\n你的老伙计詹金和布朗"
  },
  Mail_21466_Name = {
    Text = "亲爱的西区佬…"
  },
  Mail_21466_Sender = {Text = "詹金"},
  Mail_21467_Desc = {
    Text = "守密人：\n\n在人们还在神的国度里居住时，我们就已经开始用舞蹈表达自己的情感——狂欢的旋转，悲恸的步伐……有人说舞蹈的历史与人类的历史一样漫长，它见证了我们的辉煌，也见证了我们的颓丧。\n\n我曾说过我不会再舞蹈，但……我毕竟是为舞蹈而生的。所以，仅是今天，你愿意与我一同起舞吗？与我沉浸其中，感受躯体最深处的律动。\n\n我会在舞蹈室等你。\n\n\n\n莉兹"
  },
  Mail_21467_Name = {
    Text = "共舞的邀请"
  },
  Mail_21467_Sender = {Text = "莉兹"},
  Mail_21468_Desc = {
    Text = "尊敬的守密人：\n\n在我还没成为唤醒体前，我的生日都是和战友从军营外带酒进来，躲在堆放物资的帐篷里就着配给的黑面包偷偷庆祝，然后在被长官发现前把瓶子扔到外面的草丛里。\n\n但弥萨格不是军队，在这里，我们可以尽情放纵。不知你是否愿意与我分享一瓶佳酿，一同庆祝我的生日呢？\n如果你愿意的话，在今晚月亮越过钟楼的时候，到宿舍的天台上来吧。不知道你是否注意过，那里有着全弥萨格最好的景色。\n\n\n\n艾尔瓦"
  },
  Mail_21468_Name = {
    Text = "分享佳酿……"
  },
  Mail_21468_Sender = {Text = "艾尔瓦"},
  Mail_21469_Desc = {
    Text = "海滩海滩海滩海滩！\n欸？信件开头要写收件人——好麻烦！明明守密人在冰箱上贴的便签都不写收件人！\n今天是奥瑞塔的……诶……多少岁生日来着？总之是奥瑞塔的生日！\n这些是奥瑞塔的宝藏！都给你！带奥瑞塔去海滩玩吧，拜托拜托拜托了！\n就当、就当是给奥瑞塔的生日礼物吧，好不好嘛~\n\n奥瑞塔"
  },
  Mail_21469_Name = {Text = "海滩！"},
  Mail_21469_Sender = {Text = "奥瑞塔"},
  Mail_21470_Desc = {
    Text = "贵人：\n\n过去与姐姐在荒星时，我们总是拥抱着，吸食着同一株植物的能量，以此作为我们诞生的纪念。\n那些日子虽然苦涩，可如今想起来，也不免感到欢欣与温暖。\n今天又是纪念我们诞生的日子，如果可以的话，我能用一首歌来交换一段枝条吗？\n一段甜蜜的，能够代表我与姐姐的过去，能够代表我与您的未来的枝条……\n\n汀克特"
  },
  Mail_21470_Name = {
    Text = "生日的歌"
  },
  Mail_21470_Sender = {Text = "汀克特"},
  Mail_21471_Desc = {
    Text = "承命运洪恩，弥萨格大学守密人，贤明仁德之主君：\n万安！\n前几日，我见有货车出入学校马厩，竟是送来了一匹温血马。想起上次与主君执行调查任务时，您曾说自己没有过策马的经历。温血幼骒最是温顺，让初学者适应马背是最适合不过。\n乘着马，追逐黎明与黄昏，那是我记忆中最惬意的片段。若主君垂信，愿与我同骑，我想将这份惬意分享于您。\n\n奥吉尔"
  },
  Mail_21471_Name = {
    Text = "温血马…"
  },
  Mail_21471_Sender = {Text = "奥吉尔"},
  Mail_21472_Desc = {
    Text = "旧国历法，与伦蒂尼恩今日所行大不相同。\n余出生在第二个夏月的第五个满星日，选在今日庆贺，乃实验室负责人测算之结果。\n旧国尚存时，主祭会操办一切。大兴祭祀后，便是举国欢庆，进入长达七日的假期。\n虽非余所求，但余亦没有理由阻止欢愉的蔓延。\n今日并非弥萨格的公休日，守密人的职责也注定了你不会有规律的休息日。\n但，若以为余祝寿为由申请假日，想来管理处也不敢有微词。\n度过一个闲适的午后吧。\n\n图鲁"
  },
  Mail_21472_Name = {Text = "生辰…"},
  Mail_21472_Sender = {Text = "图鲁"},
  Mail_21473_Desc = {
    Text = "守密人：\n\n奥瑞塔说，寿星都是要许愿的。\n而我恰好是一个从不许愿的人。\n因为我的想法总能实现。这并非幸运，而是更像某种……命中注定的指引？\n就像上个月随希莱斯特出海时，我又「恰好」拾到了一块美丽的化石。\n当地居民都叫它「海百合」。它的手腕就像风车一样迎着水流，正慵懒地享受着夏日午后的太阳。\n脆弱、美丽。看到它时，脑海中很自然地浮现出了你的模样。\n这次我依然没有许愿——\n你一定会喜欢的，对吧？\n\n珊"
  },
  Mail_21473_Name = {
    Text = "海百合……"
  },
  Mail_21473_Sender = {Text = "珊"},
  Mail_21475_Desc = {
    Text = "守密人：\n\n过去与埃尔顿航行时，他会在每年的这天做一桌菜，并想要我「许愿」。\n来到这里前，我不理解「愿望」是什么。现在，我不知道我能有什么「愿望」……\n或许，找到「愿望」，也可以作为「愿望」吗？\n\n希莱斯特"
  },
  Mail_21475_Name = {Text = "愿望…"},
  Mail_21475_Sender = {
    Text = "希莱斯特"
  },
  Mail_21476_Desc = {
    Text = "守密人：\n\n奥瑞塔告诉我，你会实现所有在生日时许的愿望，是吗？\n应该不会是真的吧？要实现所有人的愿望，也太麻烦你了。\n不过，如果能许愿的话……我想让汀克特能有更广阔的舞台。\n会太难实现吗？唔……那、那换成，「接下来一年里，我的餐桌上不会再出现西芹」，可以吗？\n\n菲茵特"
  },
  Mail_21476_Name = {Text = "愿望…"},
  Mail_21476_Sender = {Text = "菲茵特"},
  Mail_21477_Desc = {
    Text = "亲爱的守密人：\n\n告诉你一个秘密：这个生日其实是假的。至于我真实的出生年月……就让它消散于风中吧。\n生病以后，哥哥总会在生日的那天，让管家偷偷为我准备一个小蛋糕。\n没有生日歌，也没有祝福，就好像过生日是一件可耻的事。\n现在，一切都不同了，我可以走在阳光下，可以大声唱歌，还可以过生日。\n这只是一些微小的快乐，却令我感到怀念。\n谢谢你，守密人。\n\n（当然，如果您和大家都能对我粗暴一些、再粗暴一些……就更完美了。）\n\n雷娅"
  },
  Mail_21477_Name = {
    Text = "一个秘密……"
  },
  Mail_21477_Sender = {Text = "雷娅"},
  Mail_21478_Desc = {
    Text = "我的小·囚·犯：\n\n我已经好久·好久·好久没有挥动鞭子了——\n被困在这所无趣的学校里，被困在校服里，潘狄娅的心里痒痒的，就好像有调皮小猫在抓挠一样。可非但没人理解我，那些职工还千方百计阻止我「找乐子」——真是太过分了!\n哎呀，今天可是个特殊的日子，很适合让我的鞭子再接触到柔软的肌肤，让我听见疼痛的吟唱……如果今天你有空的话，不如，来找我聊聊天吧~？\n\n潘狄娅"
  },
  Mail_21478_Name = {
    Text = "鞭子的声音…"
  },
  Mail_21478_Sender = {Text = "潘狄娅"},
  Mail_21479_Desc = {
    Text = "<Big:魔法大师卡茜亚的周年纪念演出，只在今天！>\n\n为了感谢各位观众多年来的支持与鼓励，为了回馈各位观众在过去给予的所有快乐，魔法大师卡茜亚决定在今天晚间8点整，于弥萨格大学中庭（菲利普斯雕像旁）进行特别周年纪念演出！今晚，你将见到比以往更绚烂的舞台，更刺激的演出，以及——也是最重要的——更神通广大，让你不能相信自己的眼睛的华丽魔法！即使是弥萨格之脑亲临现场，也将被这超乎想象的魔法所折服，这是来自卡茜亚大师的保证！\n\n机会难得，仅在今晚，且完全免费！卡茜亚大师与你不见不散！\n\n<Small:PS：演出期间或之后若出现精神萎靡，心情低落等症状，卡茜亚大师概不负责。>\n<Small:PPS：任何与弥萨格之脑相关宣传皆以届时实际情况为准，卡茜亚大师保留对节目及节目效果的所有解释权。>"
  },
  Mail_21479_Name = {
    Text = "魔法大师卡茜亚的周年纪念演出！"
  },
  Mail_21479_Sender = {Text = "卡茜亚"},
  Mail_21480_Desc = {
    Text = "喂，今天可是我的生日，礼物呢？\n什么，你忘记准备了……？哼，我就料到会是如此。\n喏，这本日历你拿着，上面清清楚楚地写了我的生日、我的忌日、第一天来弥萨格的纪念日，还有嬉乐节、农神节……的日期，这些节日我们都要一起过的，总之下次可别忘了！\n\n如果你又忘了的话……我好像也不能把你怎么样，哼。\n总之还是不准忘了。\n\n阿格里帕"
  },
  Mail_21480_Name = {Text = "喂……"},
  Mail_21480_Sender = {
    Text = "阿格里帕"
  },
  Mail_21481_Desc = {
    Text = "守密人：\n\n我本不想写这封信，但艾瑞卡的运行似乎出了问题，在我写完这封信前，她的警报响个不停。\n生日于我而言是一个无意义的日期，实验的成功率并不会比其他日子更高，我的诺斯指数也不会因这个日期产生任何变化。但拉蒙娜执意要让这天成为我的「休息日」，并限制了我今天进入实验室的权限。\n我无处可去，为此，今天我会对你过往的报告进行全面审查。\n请在晚餐后来一趟档案室。注意，不要试图将任何蛋糕带入档案室，纸质档案是非常脆弱的。\n\n朵尔"
  },
  Mail_21481_Name = {
    Text = "晚餐后…"
  },
  Mail_21481_Sender = {Text = "朵尔"},
  Mail_22435_Desc = {
    Text = "亲爱的守密人：\n最初选择在晨光熹微的校园中读诗，是因为觉得这个时间段的行人更少，更容易沉浸在诗歌的世界中。后来，我也慢慢爱上了清晨蒙蒙亮的天色，晶莹剔透的露水，与清脆婉转的鸟鸣。\n让我没想到的是，竟然有许多师生在默默地关注着我，并私下里组成了诗歌同好会。今日是我的生日，恰逢同好会的水仙花含苞待放，以此为契机，他们预备组织一次诗歌鉴赏会，于校园中共同赏景读诗。\n此情此景，期望您能来一同欣赏。 \n\n宁菲亚"
  },
  Mail_22435_Name = {
    Text = "读诗会邀约"
  },
  Mail_22435_Sender = {Text = "宁菲亚"},
  Mail_23897_Desc = {
    Text = "尊敬的守密人：\n        在V1.0.21的更新中，我们对「调查行动」困难难度、「意识潜游」战斗关卡普通和困难难度，以及「无光之境」中各界域的轮转间隙Ⅰ-Ⅳ 每关的首通奖励进行了调整。详细的调整内容可在「V1.0.21在线维护公告」中查看。\n        根据您之前的调查和挑战通关记录，我们将按调整后的奖励为你一次性发放之前未能领取的奖励内容。具体请见附件。"
  },
  Mail_23897_Name = {
    Text = "V1.0.21调整补偿"
  },
  Mail_23897_Sender = {
    Text = "弥萨格校务处"
  },
  Mail_24199_Desc = {
    Text = "尊敬的守密人：\n        在V1.0.24的更新中，我们重新开放了在V1.0.16中暂时关闭的「调查行动」第五章。本着公平的原则，我们将根据调整前后的奖励变化，以及每位守密人的调查记录情况，发放相应的补偿。根据您的调查记录，您的补偿已发放到附件。"
  },
  Mail_24199_Name = {
    Text = "V1.0.24第五章重新开放补偿"
  },
  Mail_24199_Sender = {
    Text = "弥萨格校务处"
  },
  Mail_24200_Desc = {
    Text = "尊敬的守密人：\n        在V1.0.24的更新中，我们重新开放了在V1.0.16中暂时关闭的「调查行动」第五章。本着公平的原则，我们将根据调整前后的奖励变化，以及每位守密人的调查记录情况，发放相应的补偿。根据您的调查记录，您本次无需补偿。"
  },
  Mail_24200_Name = {
    Text = "V1.0.24第五章重新开放补偿"
  },
  Mail_24200_Sender = {
    Text = "弥萨格校务处"
  },
  Mail_24202_Desc = {
    Text = "尊敬的守密人：\n        感谢您对《忘却前夜》的支持和认可，为了让守密人在弥萨格大学有更好的游戏体验，诚邀您填写以下体验调研问卷。为感谢您的配合，我们准备了「银芯」× 200 作为奖励，完成问卷即可领取。\n        <SurveyLink:【点击前往填写】>\n        我们会认真听取每一位守密人的建议，您的反馈也一定会使弥萨格大学越来越好！\n        ——愿银钥指引前路。"
  },
  Mail_24202_Name = {
    Text = "版本体验调研问卷V1.0下"
  },
  Mail_24202_Sender = {
    Text = "弥萨格校务处"
  },
  Mail_24280_Desc = {
    Text = "你好，守密人：\n你在昨日幻梦深潜的调查排名中，获得「{s1}排行」的第{s2}名，调查头衔为「{s3}」，以下为排名奖励，请守密人记得查收。"
  },
  Mail_24280_Name = {
    Text = "幻梦深潜每日排行奖励"
  },
  Mail_24280_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_24877_Desc = {
    Text = "守密人：\n\n我的每个生日，都是一场最盛大的沙龙，高朋满座，宾客尽欢。\n但这次，我倒有些别的想法——\n坐了太久的主位，偶尔也会想尝尝当客人的感觉。\n是又一场精致的沙龙，还是一餐家常晚饭，一切由你来决定，如何？\n不过，如果选择再开一场沙龙，可别邀请那些名流贵胄了。\n难得的好日子，我不想挂着伪装的笑脸。\n\n<Del:红夫人>索蕾尔"
  },
  Mail_24877_Name = {
    Text = "由你决定…"
  },
  Mail_24877_Sender = {Text = "索蕾尔"},
  Mail_24878_Desc = {
    Text = "主人： \n\n今天是莉莉的生日，阿格里帕说要「大闹一场」。\n过去妈妈和莉莉过生日并不是这样的，妈妈会给我戴上尖顶帽，一起拍手吹蜡烛。\n莉莉不知道，怎么做才是正确的，请主人下命令。 \n\n莉莉"
  },
  Mail_24878_Name = {Text = "困扰…"},
  Mail_24878_Sender = {Text = "莉莉"},
  Mail_25147_Desc = {
    Text = "尊敬的守密人：\n        在V1.1.0的更新中，幻梦深潜本周积分奖励下架，替换为新的「每周试炼」。本着公平的原则，我们对此前已解锁「幻梦深潜」，但未全部领取本周积分奖励，且1月15日5:00 前登录游戏的守密人，我们补偿未领取的本周积分奖励。请查收。"
  },
  Mail_25147_Name = {
    Text = "V1.1.0幻梦深潜本周积分奖励补偿"
  },
  Mail_25147_Sender = {
    Text = "弥萨格校务处"
  },
  Mail_25148_Desc = {
    Text = "尊敬的守密人：\n        在V1.1.0的更新中，相位对弈（beta）的「每周奖励」下架，替换为「每周试炼」，与幻梦深潜的「每周试炼」为同一进度与奖励。本着公平的原则，我们对此前已解锁「相位对弈（beta）」，但未完成或未领取本周「每周奖励」，且1月15日5:00（UTC+8） 前登录游戏的守密人，我们补偿融蚀之珠×1000。请查收。"
  },
  Mail_25148_Name = {
    Text = "V1.1.0相位对弈每周奖励补偿"
  },
  Mail_25148_Sender = {
    Text = "弥萨格校务处"
  },
  Mail_25414_Desc = {
    Text = "尊敬的守密人：\n\n诞生之日的重量，于每个人而言都不尽相同。但守密人的生日，对整个弥萨格来说可都举足轻重。\n茜尔维娅女士在宿舍区为您准备了生日晚宴，诃勒特院长和德克斯特勋爵都会出席。知道你的精神疲劳尚未缓解，我已经替你整理好了正装，就挂在门口衣柜中，参会前可以直接换上。\n今年很荣幸能以搭档的身份与你共度，希望来年亦是如此。\n愿银钥指引前路。\n\nP.S.定制小蛋糕已经由艾瑞卡派送至你的宿舍。\n\n愿意做你永远的搭档 拉蒙娜"
  },
  Mail_25414_Name = {
    Text = "诞生之日…"
  },
  Mail_25414_Sender = {Text = "拉蒙娜"},
  Mail_34667_Desc = {
    Text = "尊敬的@1@2：\n\n世界遗忘了你的名字。\n所以我唤醒你，正如你唤醒我。在终焉降临之前，你和我于世间行走、见证，然后铭记和遗忘。\n今日是你的诞生之日，是你散佚的记忆碎片中偶然拾得的一页。为此，当献上喟叹与祝福。\n当世界回忆起你完整的形貌，你会作何感想呢？又或是仍一无所知，一无所觉？\n我在不存在之地等待你的答案。\n\n@2"
  },
  Mail_34667_Name = {
    Text = "诞生之日…"
  },
  Mail_34667_Sender = {Text = "▼▼"},
