  },
  Mail_36865_Desc = {
    Text = "尊敬的守密人：\n        在V1.2.4的更新中，我们对「幻梦深潜」每周试炼的奖励进行了调整，不再提供「融蚀之珠」「拟态凝晶」和「蔷薇金券」奖励。本着公平的原则，我们对更新前已解锁「幻梦深潜」，但未全部领取本周试炼奖励，且3月11日5:00 前登录游戏的守密人，我们补偿本周试炼中未领取的原「融蚀之珠」「拟态凝晶」和「蔷薇金券」奖励。请查收。"
  },
  Mail_36865_Name = {
    Text = "V1.2.4每周试炼调整奖励补偿"
  },
  Mail_36865_Sender = {
    Text = "弥萨格校务处"
  },
  Mail_36866_Desc = {
    Text = "尊敬的守密人：\n        在V1.2.4的更新中，通关意识潜游「血与沙」「扭曲核心」「骑士的愿望」普通模式新增了解锁全新钥令「咆哮的血与沙」「短暂的永恒」「最后的誓言」。对更新前已完成以上篇章普通模式的守密人，我们将补发对应的钥令。请查收。"
  },
  Mail_36866_Name = {
    Text = "V1.2.4意识潜游钥令补发"
  },
  Mail_36866_Sender = {
    Text = "弥萨格校务处"
  },
  Mail_36867_Desc = {
    Text = "尊敬的守密人：\n        在V1.2.4的更新中， 「超验存在」掉落的独特技能升级素材和拟态凝晶数量有所提高。本着公平的原则，对更新前已领取本周「超验存在」奖励的守密人，我们将按守密人已领取奖励的关卡推荐等级，补发与提升掉落相等价值的「拟态凝晶」。请查收。"
  },
  Mail_36867_Name = {
    Text = "V1.2.4超验存在奖励调整补偿"
  },
  Mail_36867_Sender = {
    Text = "弥萨格校务处"
  },
  Mail_36871_Desc = {
    Text = "尊敬的守密人：\n根据昨日通关幻梦深潜的最高难度，你将获得以下奖励，请记得查收。"
  },
  Mail_36871_Name = {
    Text = "每日幻梦奖励"
  },
  Mail_36871_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_39293_Desc = {
    Text = "尊敬的守密人：\n        在V1.2.7的更新中，通关意识潜游「如歌的雕琢」「苍白后裔」「一步之遥」普通模式新增了解锁全新钥令「蚀骨的拥抱」「湖畔回眸」「跨越回溯之扉」。对更新前已完成以上篇章普通模式的守密人，我们将补发对应的钥令。请查收。"
  },
  Mail_39293_Name = {
    Text = "V1.2.7意识潜游钥令补发"
  },
  Mail_39293_Sender = {
    Text = "弥萨格校务处"
  },
  Mail_39548_Desc = {
    Text = "亲爱的守密人：\n\n对永恒的生命而言，纪念生辰似乎并无必要。和无垠的时间长河相比，你们人类称之为难忘或是精彩的回忆都显得有些……微不足道。\n而你们却发明了无数的节日和庆典来纪念这些「微不足道」——当然，这也是人类引发我兴趣的原因之一。你们确实足够可爱。\n不过，与你的相遇显然不能算在这些「微不足道」的瞬间里，因为你与他们不同……而这种「不同」将在未来掀起何种风暴，我亦十分期待。\n好了，请原谅我的絮叨……既然今天是我的生辰，那么我请求行使一下「寿星的权利」。\n至于需要你做什么，嘘……切勿心急，谜底就在我的卧室里，请于今夜午时独自前往。\n\n旺达"
  },
  Mail_39548_Name = {
    Text = "寿星的权利……"
  },
  Mail_39548_Sender = {Text = "旺达"},
  Mail_39549_Desc = {
    Text = "今天是墨菲大人的生日——生日，就应该要有宴会与庆典！\n后勤管理处那些人做得还不错，但他们实在是不太会做戏，还遮遮掩掩的——本小姐早就看到他们在往唤醒系仓库里放蛋糕装饰了。唔……你应该不会惩罚那些职员吧？他、他们做得是真的很不错，就是没有藏好惊喜而已……\n就写到这里了，好像有人在找我出去——他们最好不要用蠢兮兮的彩纸糊本小姐一身。\n顺便一提，切蛋糕的时候，你会在吧？\n\n墨菲"
  },
  Mail_39549_Name = {
    Text = "生日宴…"
  },
  Mail_39549_Sender = {Text = "墨菲"},
  Mail_43571_Desc = {
    Text = "尊敬的守密人：\n        在V1.2.10的更新中，「雾都纪行」活动任务【完成调查主线第 1 章「东区秘事」困难难度】和【完成调查主线第 2 章「以蜡像之名」困难难度】新增了奖励：「银芯」× 1000。对更新前已领取完以上任务奖励的守密人，我们将补发对应的银芯。请查收。"
  },
  Mail_43571_Name = {
    Text = "V1.2.10雾都纪行奖励补发"
  },
  Mail_43571_Sender = {
    Text = "弥萨格校务处"
