    Text = "弥萨格校务处"
  },
  Mail_44836_Desc = {
    Text = "尊敬的守密人：\n        在V1.3.0的更新中，我们对「幻梦深潜」每周试炼 1 胜、3胜增加了奖励：「代理凭证」×1。对更新前已领取以上奖励的守密人，我们将补发相应数量的「代理凭证」。请查收。"
  },
  Mail_44836_Name = {
    Text = "V1.3.0每周试炼奖励补发"
  },
  Mail_44836_Sender = {
    Text = "弥萨格校务处"
  },
  Mail_44837_Desc = {
    Text = "可敬的苍白使者：\n\n几个孩子今日送来了花束与糕点，我这才想起，远在洪积历法之前百余年的今天，我蒙受父神的恩赐，领受生命来到人世。那是多么久以前的事了啊，童年的记忆早已模糊，唯有本多萨教堂内熏香的味道还萦绕在我脑海之中，挥之不去。而今即使教堂还在，熏香的配方也不会是当年的那个了。\n\n抱歉，伤春悲秋并非我来信的目的。我用孩子们带来的糕点准备了一场茶歇，希望你能来与我一同分享——倒不是为了庆贺我的生日，而是为了庆贺生命存在的每一天，希望存在的每一天。\n\n不知你的生日是何时呢？请务必在一杯茶后告诉我。\n\n\n\n萨尔瓦多"
  },
  Mail_44837_Name = {
    Text = "苍白的使者……"
  },
  Mail_44837_Sender = {
    Text = "萨尔瓦多"
  },
  Mail_44843_Desc = {
    Text = "尊敬的守密人：\n        在V1.3.0的更新中，我们下架了「核心课题」的特权：在「幻梦深潜」和「相位对弈（beta）」获得守密人经验翻倍。为表歉意，我们将为购买了本期「核心课题」的守密人提供每日「守密人经验」× 240 的补偿，持续到本期学期课题结束。请查收。"
