  },
  Mail_47308_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_48005_Desc = {
    Text = "亲爱的守密人：\n\n冒昧打扰，希望我糟糕的笔迹不会破坏您的好心情，我实在是不太擅长书写……\n写这封信是为了告诉您，我的生日似乎到了。为此我做了一些小饼干，希望您也能尝一尝。\n说实话，我不确定这个日期是否正确。感染融蚀后，有关我存在的痕迹正在一点点消失。朵尔小姐曾问我，清醒地看着自己被大家遗忘，是一种什么样的感觉？\n这很难形容……就像是站在一片漆黑里，一条发光河流的边缘，人们都在河流的另一头互相说话、各自忙碌，在我面前匆匆走过。我只能看着他们，却发不出一点声音。\n这是一种很孤独的感觉。幸运的是，那些人里不包括您。\n至少您还记得我的故事，不是么？\n\n另，十二个小饼干已随信附上。\n\n梅森"
  },
  Mail_48005_Name = {
    Text = "冒昧打扰……"
  },
  Mail_48005_Sender = {Text = "「24」"},
