  },
  Mail_50344_Desc = {
    Text = "小树苗：\n\n风带来了你的气息，比刚认识你那时，闻起来更甜了些。\n你在我的爱中长大，被我的爱滋养成熟……就像蜂和蜜糖一样。\n今天是个特殊的日子，能来与我见一面吗？\n我已经依你要求，乖乖等待很长一段时间了……是时候该给我一些奖励了，你说对吗？\n\n泰旖丝"
  },
  Mail_50344_Name = {
    Text = "蜜糖一样的…"
  },
  Mail_50344_Sender = {Text = "泰旖丝"},
  Mail_51376_Desc = {
