  },
  Mail_53149_Desc = {
    Text = "我早已决定，将余生的每日都献给那一位……权当是为我愚笨之行的赎罪。\n浅薄之身的「生日」，不值一提，不足挂齿。\n今天与过去的、未来的任何一天都没有区别，我会一如既往前往礼拜堂。\n但，如果您想让我在今日离开礼拜堂，作为弥萨格的客人，我自是不会违背主人的意志。\n若，您想见证我的祈祷，也随时欢迎您来……诚惶诚恐，不胜欢迎。\n\n弥利亚姆"
  },
  Mail_53149_Name = {
    Text = "修行一日…"
  },
  Mail_53149_Sender = {
