  Mail_54803_Desc = {
    Text = "尊敬的守密人：\n        在V1.5.1的更新中，我们提高了「成长记录」守密人等级21-80级的「银芯」奖励，并为「界域精通」Ⅰ~Ⅴ 阶段完成任务追加了「调查徽章」× 1000 的奖励。对更新前已领取完以上奖励的守密人，我们将补发对应的「银芯」或「调查徽章」奖励。请查收。"
