  Mail_55168_Desc = {
    Text = "尊敬的守密人：\n「在春天凋零以前」活动已结束，现将守密人剩余的「欢欣的诗文」、「惆怅的诗文」和「遗憾的诗文」按照每200个兑换「蔷薇金券」× 5000 的比例进行转换，请守密人查收。"
  },
  Mail_55168_Name = {
    Text = "诗文回收"
  },
  Mail_55168_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_56101_Desc = {
    Text = "守密人%sirormadam%：\n\n今天凌晨，一朵玫瑰在初春的鸟鸣里盛开了。\n它本应是一个含苞的春枝，却在圣瓦伦丁节，在我诞生的这一天，盛开在一个不属于它的季节。\n我回忆起了西岱。每年生日这天，西岱的街头总是很热闹。我听到花开的声音，听到人们令人脸红的情话。可我已经很久没有机会触碰到它们了……直到今天。\n您相信巧合吗，守密人？我想，巧合是一种语言，而玫瑰是一种修辞。今天，在弥萨格纷繁的花园里，这朵玫瑰绽放着，它的花瓣大方地舒展开，就像是一首令人心醉的诗。\n所以，今天，守密人……您愿意和我一起，来看看这朵玫瑰的盛开吗？\n我和花，都期待着您的到来。\n\n奥尔拉"
  },
  Mail_56101_Name = {
    Text = "一朵玫瑰开在春天……"
  },
  Mail_56101_Sender = {Text = "奥尔拉"},
