  Mail_61154_Desc = {
    Text = "尊敬的守密人：\n「燃烧的群宴·复刻」活动已结束，现将守密人剩余的「原生胫骨」、「圆叶菊石」和「螺旋遗迹」按照每个兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
  },
  Mail_61154_Name = {
    Text = "燃烧的群宴货币回收"
  },
  Mail_61154_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_61155_Desc = {
    Text = "尊敬的守密人：\n「多重疗愈·复刻」复刻活动已结束，现将守密人剩余的活动货币「记忆拼图」按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人记得查收。"
  },
  Mail_61155_Name = {
    Text = "记忆拼图回收"
  },
  Mail_61155_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_62392_Desc = {
    Text = "守密人：\n\n我的演奏曾侍奉于帝王座前，也曾被万千世人憧憬。然而那些溢美之词于我而言毫无价值，我所追求的不过是音乐的极致。\n比起在华丽而盛大的场合供人欣赏，独自在无人的森林中演奏更加令我放松。\n原本我不喜欢自己的练习有人旁听，那些只是我通往完美的草稿，一些无意义的废料。\n但自从知晓您、找到您之后，我所有的乐声都有了意义。\n是您给予了我最伟大而崇高的乐音，拯救了我于迷途之中，哪怕您自己并不知晓……\n今日是我的生日，原本我已经将它淡忘，但现在，我想纪念一下自己的新生，和赐予我新生之人。\n恰巧近日有些新作的曲谱，想邀请您稍作鉴赏。请原谅我的姗姗来迟，我的身份尚不适合现身于弥萨格同僚之前，只能在等待地平线收敛落日所有余晖后再向您递上这封邀请函。\n今晚学校后方的森林中，我会开一场特别的音乐会，观众席只有一个。\n期待您的莅临。\n\n哈姆林"
  },
  Mail_62392_Name = {
    Text = "秘密音乐会…"
  },
  Mail_62392_Sender = {Text = "哈姆林"},
  Mail_65350_Desc = {
    Text = "尊敬的守密人：\n「雪山消融之时」活动已结束，现将守密人剩余的活动货币「寒冻花苞」「银霜花苞」和「日光花苞」按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人记得查收。"
  },
  Mail_65350_Name = {
    Text = "花苞回收"
  },
  Mail_65350_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_65441_Desc = {
    Text = "尊敬的守密人：\n「沉渊之祀·复刻」活动已结束，现将守密人剩余的「祀者之泪」、「祀者之血」和「祀者之髓」按照每个兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
  },
  Mail_65441_Name = {
    Text = "沉渊之祀活动货币回收"
  },
  Mail_65441_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_65442_Desc = {
    Text = "尊敬的守密人：\n「万象门扉」活动已结束，现将守密人剩余的活动货币「终末指针」按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人记得查收。"
  },
  Mail_65442_Name = {
    Text = "终末指针回收"
  },
  Mail_65442_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_67147_Desc = {
    Text = "守密人：\n\n    宇宙的维度对我而言并不唯一，穷极之门内可以窥见万千世界与无限存在。那里超越一切奇想与数学逻辑，自然也无从确定「诞生之日」的日期。\n    所以，就将你我的初遇定为那个时刻吧。你所在的时间连续体的刻度中，应当会在今天举行专属于我的仪式，实现我许下的愿望。\n    那么，跨越银钥之扉，来到我的身边吧。我将传授你…一些关于终极本源的、属于宇宙的知识。今夜，亿万光辉体将为你我二人闪耀。\n    我在穷极之门等你。\n\n塔薇"
  },
  Mail_67147_Name = {
    Text = "跨越银扉…"
  },
  Mail_67147_Sender = {Text = "塔薇"},
  Mail_67933_Desc = {
    Text = "我感受到了你片刻的茫然——那无上的造物主，即使是直视也近乎妄想，又如何伤及分毫？但你做到了。\n又一道目光坍塌，坚硬的铠甲，在一块块前赴后继的碎片下，留下了划痕与豁口。\n%player%，无坚不摧的，唯有你坚定的意志。"
  },
  Mail_67933_Name = {
    Text = "从迷惘中看清道路"
  },
  Mail_67933_Sender = {
    Text = "阿利斯泰尔"
  },
  Mail_67934_Desc = {
    Text = "你的四肢在颤抖，%player%。你几乎已经无力站立。恐惧攥住了你，让你大脑空白，无法控制自己的呼吸……但你依然向着前方举起了银钥。\n在人类所有美好的品格里，勇气是最为高尚的那一个。面对天灾与猛兽，我们曾举起石锤与长矛。如今面对神明，你依旧如此。\n人类文明因勇气而建立，也终将因勇气生生不息。"
  },
  Mail_67934_Name = {
    Text = "勇气的赞歌，于颤栗中响起"
  },
  Mail_67934_Sender = {
    Text = "阿利斯泰尔"
  },
  Mail_67935_Desc = {
    Text = "我们曾谈论起这个世界，你说，你并不喜欢它。这里充斥着利益、阴谋、欺骗、杀戮，即便没有融蚀与神明，它也本就千疮百孔，摇摇欲坠。从阿库特醒来之后，在你短暂的记忆里，你已见过无数比融蚀更失序、更可怖的人心。\n可当造物主举起祂的利刃时，你依然挡在这个世界身前。湮灭是神明的意志，而你拒绝了祂。\n我明白，%player%。没有守密人不憎恶这个世界，也没有守密人不真正爱它。因为在那些肮脏中，我们曾见过那些如银芯般闪耀的光辉。\n守密人的职责，便是守护那些微弱的光辉，永世长存。"
  },
  Mail_67935_Name = {
    Text = "人类精神永存"
  },
  Mail_67935_Sender = {
    Text = "阿利斯泰尔"
  },
  Mail_67936_Desc = {
    Text = "第一次看见融蚀，第一次面对融蚀的真相，第一次感知到神明的声音……在我漫长的人生中，历经了无数颓唐的时刻，我不知道自己能做些什么，不知道这一切努力与牺牲的意义所在——但那些都不及你此刻所面对的。\n人类就是这样，在一次次的颓唐中重新站起，迈向前方。\n道路的尽头或许亦是万丈深渊，但总会有人想要去看一看。"
  },
  Mail_67936_Name = {
    Text = "颓唐，而后新生"
  },
  Mail_67936_Sender = {
    Text = "阿利斯泰尔"
  },
  Mail_67937_Desc = {
    Text = "维度的界限打开，我终于能再次与你联络。\n和你所见的相比，这个维度的目光异常孱弱，或许是因为这个维度没有你的存在。牺牲了几乎一切之后，我替你解决了祂。\n难以想象你正面对着什么。但无论如何，湮灭的意志，我将与你一同对抗。这是每一个弥萨格人的誓言。\n很高兴，能再次与你并肩。\n愿银钥指引前路。"
  },
  Mail_67937_Name = {
    Text = "并肩作战，再一次"
  },
  Mail_67937_Sender = {
    Text = "未知发件人"
  },
  Mail_67938_Desc = {
    Text = "疯狂，一个轻松、甚至美好的词汇。\n一个混沌的宇宙，产生了一个混沌的文明。混沌是这个世界的真相。顺应混沌，享受疯狂，这是一件多么轻松的事。与之相比，清醒与对抗，是如此艰难。你将祭献全部的欢愉与生命，只为追寻一个遥不可及的答案。\n可你仍然选择清醒，%player%。因为我们生来不是要做奴隶的。\n你让祂看到了，%player%——祂的造物，祂的碎片，从不甘做盲目痴愚的奴隶。你与祂对抗，战胜祂的一道又一道目光，选择守护这个并不完美、并不轻松的世界。\n在这选择中，你已拥有了永恒的自由。"
  },
  Mail_67938_Name = {
    Text = "你从不甘做盲目痴愚的奴隶"
  },
  Mail_67938_Sender = {
    Text = "阿利斯泰尔"
  },
  Mail_67939_Desc = {
    Text = "我感受到了一道目光的坍塌。我感受到了你切肤的疼痛。\n这是守密人这个称号上所铭刻的责任。你选择踏上的道路，比我所走的艰难万倍。不是所有人都有勇气直面无上的神明，你的勇气令我感到欣慰，敬叹。\n造物主的力量会让你承受多大的痛苦，我无从想象。我所感知到的，只是你所承受的沧海一粟。我是一个困守黑池的废人，%player%，我已无力参与你与造物主的对决，只能通过我的感知与你时刻相连。这将是我的生涯中，最后、也最重要的使命。\n在这条孤独的道路上，无论你是否得见，弥萨格都将一直陪伴在你身边。"
  },
  Mail_67939_Name = {
    Text = "悲痛不会使你屈服"
  },
  Mail_67939_Sender = {
    Text = "阿利斯泰尔"
  },
  Mail_67940_Desc = {
    Text = "我听见了无上意志的低语——宏伟的文明，人间的悲欢，环绕你远离你的无数的人，一切从未存在过。\n在黑池的无数个日夜，这景象令我感到恐惧。树木扎根于土地，然后向上生长，迎接太阳——记忆，记忆是我们的土壤，是我们生长、站立、最后将要回归的地方。我畏惧失去土地，漂浮在虚无中，没有来处，没有终点。\n谢谢你，%player%。我想，我见证了一场伟大的对决。这是人与神明的战斗。这是守护与毁灭的战斗。\n这是铭记与遗忘的战斗。\n你做到了，%player%。你完成了无人敢想象的事。你从铭记中获得了无可匹敌的力量。你以这力量，为铭记而战。\n你已于这亘古的土壤中，寻到属于你的太阳。"
  },
  Mail_67940_Name = {
    Text = "为了铭记而战"
  },
  Mail_67940_Sender = {
    Text = "阿利斯泰尔"
  },
  Mail_68825_Desc = {
    Text = "尊敬的守密人：\n「神王复苏」活动已结束，现将守密人剩余的活动货币「惫倦绪思」、「悲愁绪思」和「欢悦绪思」按照每个兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
  },
  Mail_68825_Name = {
    Text = "神王复苏货币回收"
  },
  Mail_68825_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_68826_Desc = {
    Text = "尊敬的守密人：\n「欲海翻波·复刻」活动已结束，现将守密人剩余的「丰穰种核」按照每枚兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
  },
  Mail_68826_Name = {
    Text = "丰穰种核回收"
  },
  Mail_68826_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_68898_Desc = {
    Text = "最最最亲爱的主人：\n\n作为万能女仆，珈伦能够记住大人们许许多多重要的日子，上到宴会日、生日、纪念日，下到第一次购买宠物的日子，绝对不会出一点错。但对于珈伦自己来说，能够纪念的特别的日子就只有这一天啦。\n很久很久以前，珈伦还在皇宫里当侍女，第一次去向厨师要一块贵人们没吃完的甜点作为生日蛋糕的时候被大骂了一顿，那个厨师把蛋糕扔在了我的脸上，那时候我就想，原来蛋糕是这么好吃的东西，我一定要找到一个对我很好的主人，让我每年生日都能吃到蛋糕。\n现在我有特别特别优雅大方的索蕾尔夫人，和特别特别善良的主人您，当年的愿望已经实现啦！但人总是会越来越贪心……啊不进步的嘛，现在我的愿望是每年生日的时候都可以陪在主人的身边，另外如果每年都有亮闪闪的礼物就更好了。\n听了这么多，您一定会给我准备的吧，对吧对吧？\n\n您永远谦卑的女仆\n珈伦"
  },
  Mail_68898_Name = {
    Text = "年年如此…"
  },
  Mail_68898_Sender = {Text = "珈伦"},
  Mail_68899_Desc = {
    Text = "小树苗：\n\n看到你一直以来的成长，让我越来越确信选择你，帮助你，是我做过最正确的决定。\n我感受到了丰收的喜悦，一切信任与爱的浇灌都给予了我甜美的回报，是你给了我希望与未来。\n现在我可以抛却繁衍的执念，专心去享受那繁衍之外的，爱的果实。\n这个世界不再需要亚兰女王，但或许可以容纳一个普通女人想要爱侣陪伴的生日愿望。\n就像最常见的情侣那样，一起去购买食材，一起烹饪美食，或许还有许多我不曾体验的事物，那么亲爱的你能够引领我，度过一个温馨平淡的生日吗？\n\n泰旖丝"
  },
  Mail_68899_Name = {
    Text = "平凡生活…"
  },
  Mail_68899_Sender = {Text = "泰旖丝"},
  Mail_68900_Desc = {
    Text = "守密人：\n\n卡茜亚大师是世界上最最杰出的表演大师，可以完美模仿出任何表情，但人类情感这种东西真是无论怎样都搞不明白的世界谜题。\n我问过许许多多的人，他们都不能讲清情感的原理，直到我问到朵尔，她告诉我世界上有一门叫做心理学的学科，哪怕不能感同身受，但学好心理学就可以掌握所有情感的理论。\n这实在、实在是太吸引人啦！难道困扰卡茜亚这么久的疑惑就要彻底解开了吗？\n话说回来，我是来告诉你，这周的心理学课程我会加入你的班级课堂，卡茜亚决定做你的同桌，之前我落下的内容你要好好帮我补课哦，同桌~\n啊对了，顺便一提，今天是我的生日，这里我应该开心，你也应该开心，对不对？\n如果是非常开心的事，那就在学校里大闹一场吧，我会让校园变得像梦境一样美的！\n\n卡茜亚"
  },
  Mail_68900_Name = {
    Text = "心理学…"
  },
  Mail_68900_Sender = {Text = "卡茜亚"},
  Mail_68901_Desc = {
    Text = "可敬的苍白使者：\n\n感谢这一年来你的帮助与关心，你对待他人的赤诚之心就像是父神所教导的那般高尚，即使与你相处的机会并不频繁，但每次与你见面时就仿佛遇到相识已久的老友一般，令我如沐春风。\n生日这一天虽然并无特别，但作为友人见面的理由，还是令人心生期待，除了你，我想不到有任何其他人可以作为共度这一天的人选。\n如果你感兴趣的话，我想邀请你体验我近来的新爱好——钓鱼，当然，不是为了烹饪和食用，只是单纯享受这样静静等待命运给予神奇礼物的过程。我想与你分享这样宁静的感受，去到自然之中，在湖畔安然静坐。\n一位老友、两支鱼竿，想必将是再好不过的一天。\n\n萨尔瓦多"
  },
  Mail_68901_Name = {
    Text = "钓鱼的新爱好…"
  },
  Mail_68901_Sender = {
    Text = "萨尔瓦多"
  },
  Mail_68902_Desc = {
    Text = "主人：\n\n今年的生日，艾继丝和詹金送给了我一只长得很像奥瑞塔的玻璃风铃。\n我把它挂在了房间的窗户上，有风吹过的时候就会发出好听的声音，让我想起母亲曾经抱着我靠在窗边讲故事的时候。\n不用担心，主人，虽然我每天都在思念母亲，但有了主人和大家陪我，莉莉不会感到孤单。\n现在莉莉学会了自己看故事书，每天傍晚的时候，橘色的阳光照进屋子，照在风铃上，在故事书上照出一块一块摇晃的波纹，映得房间暖暖的。\n莉莉好喜欢在这时候发呆，看着夕阳下的云朵和风铃，感觉好美好美。\n今天主人有时间的话，也来试试和莉莉一起发呆吧。\n\n莉莉"
  },
  Mail_68902_Name = {
    Text = "玻璃风铃…"
  },
  Mail_68902_Sender = {Text = "莉莉"},
  Mail_68903_Desc = {
    Text = "小家伙：\n\n虽然这个特别的日子是为了纪念那个人类而定下的，但我不得不承认，折扣日对于顾客和商家来说都是一种极其具有吸引力的售卖方案。\n上一次生日的时候，解忧小铺的成交订单几乎比得上平时半年的销量，尤其是那些被我拿出来当作庆祝彩头的特价商品全部被抢购一空。是该说弥萨格的客人们都太照顾我的生意，还是连精明谨慎的调查员们都抗拒不了折扣的诱惑呢。\n总之为了继续双赢的快乐，今年我的生日宴会依然会举行折扣活动，一年仅此一次，力度很大，欲购从速。记得帮我在弥萨格好好宣传一番，为了便于记忆，就将这一天称为双十日吧。\n另外，我为你偷偷留下了一些有意思的小东西，一定要早点来见我哦。\n\n达芙黛尔"
  },
  Mail_68903_Name = {
    Text = "折扣日…"
  },
  Mail_68903_Sender = {
    Text = "达芙黛尔"
  },
  Mail_68904_Desc = {
    Text = "承命运洪恩，弥萨格大学守密人，贤明仁德之主君：\n万安！\n如果说每位骑士的毕生愿望就是追随一位伟大的主君，那么我的骑士生涯已然无憾。\n我的人生中除了幸运，也包含了太多不幸的悲剧与壮烈的鲜血，我知道因此弥萨格的许多人都曾对我心生同情。\n先不说仅仅比较苦难，弥萨格中已有太多不幸的人，在这样充满苦难的世界上，为守护而流尽鲜血并不是什么需要悲伤的事。正相反，无论是过去还是现在，我都为此感到荣耀，并时刻做好了牺牲此躯的准备。\n但萝坦阁下说我每天板着脸操心的样子看着太累，让我在生日这天好好地玩一下，并叫来了詹金教我玩游戏，说是要让我找回童年。\n说来惭愧，我童年时忙于训练，的确没有什么玩耍的经历，没想到这种据说五岁小孩都能精通的游戏是这样困难，看来在骑士之道外，我需要学习的东西还有很多。\n若主君今日得闲，不知能否前来与我们一同游玩，我看到詹金在连赢十局之后已经开始无聊，如果主君在此，一定能带来一场精彩的对弈。\n\n奥吉尔"
  },
  Mail_68904_Name = {
    Text = "困难的游戏…"
  },
  Mail_68904_Sender = {Text = "奥吉尔"},
  Mail_68905_Desc = {
    Text = "喂：\n\n有了那本日历，想必你今年一定没有忘记尊贵的迷宫之主的生日。\n我允许你来我的房间献上礼物，顺便在这一天尽心服侍我。\n比如什么刷牙洗脸、更衣进餐，还有那些打扫房间、更换被单的事，你们有个词叫什么来着，大扫除！\n对，这些大扫除的工作就都交给你了，我已经受够了那些家务，今天无论如何，我都要重回曾经在罗马的时光，享受一下衣来伸手、饭来张口的生活。\n今天不管是谁也别想让我自己干一点活，谁也别想！\n\n阿格里帕"
  },
  Mail_68905_Name = {
    Text = "重回过去…"
  },
  Mail_68905_Sender = {
    Text = "阿格里帕"
  },
  Mail_68906_Desc = {
    Text = "守密人：\n\n时间过得真快，没想到曾经以为会持续到死掉的那种生活，现在我已经几乎不会想起了。\n如今本小姐已经对食堂所有的小蛋糕了如指掌，再怎么鞭策那群没用的厨师，他们也做不出什么新花样了。\n所以新的一年，我的美食地图要变得更大、更远，先定一个小目标：吃遍伦蒂尼恩所有的蛋糕店。\n至于跑腿排队的光荣工作，就还是交给你啦！能得到本小姐的信任，你也不用太过高兴，只要心怀感激地称颂本淑女的名号就好。\n不过话说回来，那群笨蛋厨师多少还是有些诚心的，从他们遮遮掩掩的悄悄话中我已经听到他们似乎准备了一个巨大的十层蛋糕——哈，他们还是这么不会掩藏惊喜。\n虽然创意有些老套，但或许这次生日会我可以多邀请一些人，比如这一年来交到的新朋友。\n作为本小姐在弥萨格的第一个朋友，我允许你替我在蛋糕上切第一刀。\n\n墨菲"
  },
  Mail_68906_Name = {
    Text = "十层蛋糕…"
  },
  Mail_68906_Sender = {Text = "墨菲"},
  Mail_68907_Desc = {
    Text = "亲爱的守密人：\n\n聪慧如你，一定已经从弥萨格的神奇档案里知道了这一信息——今天，是「好运侦探」生命中值得纪念的日子。\n出生，赢下第一局21点，赢得第一百场赛马，破获第一场密室杀人案，带来死亡的失败——一切都发生在这神奇的6月6日。\n因此，要不要和我来一局双人桥牌？就在今天，让这个日子变得更值得纪念，如何？\n\n莱克"
  },
  Mail_68907_Name = {
    Text = "来一局吧？"
  },
  Mail_68907_Sender = {Text = "莱克"},
  Mail_68908_Desc = {
    Text = "这封信并非问候，而是一个警告——不要试图控制我，不要试图给我套上锁链。\n我只属于我自己。\n我可不像那个和我长得一样的家伙一样，还对人、对世界，抱有幼稚的期待。\n\n我会杀了任何妄图成为我“主人”的家伙，说到做到。\n\nH"
  },
  Mail_68908_Name = {
    Text = "我属于…"
  },
  Mail_68908_Sender = {
    Text = "血链·希洛"
  },
  Mail_68909_Desc = {
    Text = "守密人：\n\n或许我曾对您讲述过我对于水的喜爱，相比于喧闹的人间，水中的世界是那样静谧、安宁。\n我曾飘荡在水草与珊瑚之间，也曾与鱼群对话。当离水面越遥远，水中的颜色便越幽暗，被水波轻柔推动着从水底看向天空时，那斑驳的光影呈现出令人迷幻的色彩，是我心中最美的风景。\n你知道吗？有些海洋生物能够记住人的样子，当你再次到访，这些“朋友”还会热烈地靠近迎接，譬如我认识一只聪明的小章鱼，以及一条嫩黄色的海鱼。\n在生日的这天，我又思念起水下的世界，不知道您是否愿意与我进行一次潜泳，我由衷地希望能将这份宁静的天地，以及我神奇的朋友们一同分享给您。\n\n宁菲亚"
  },
  Mail_68909_Name = {
    Text = "水中世界…"
  },
  Mail_68909_Sender = {Text = "宁菲亚"},
  Mail_68910_Desc = {
    Text = "守密人：\n\n自从你来到弥萨格，我已经习惯了用培养婴儿的方法来处理与你相关的事宜，从你平时的反应来看，你的孱弱也远超我的期待。\n不过作为你的师长兼第一监护人，我很高兴看到这一年来为你处理麻烦和善后的情况越来越少，虽然你刚刚入学时大脑一片空白的样子十分令人绝望，但你的成长速度的确可以称得上天赋与努力兼有。\n恭喜你已经成为了一位合格的守密人，没有辜负我的期待。\n在我的生日这样没什么特殊的一天，我已经为你准备好了一份属于成功守密人的礼物——阿利斯泰尔曾经用过的特训方案，怎么样，是不是很期待？\n不要问为什么是我给你准备礼物，不能进入实验室的日子总要找点事做，不是吗。\n等你准备好了，就来训练室找我。\n\n朵尔"
  },
  Mail_68910_Name = {Text = "礼物…"},
  Mail_68910_Sender = {Text = "朵尔"},
  Mail_68911_Desc = {
    Text = "守密人：\n\n一年时间对于舞者来说，只是几万次的旋转、几万次的跳跃，除去上一双陪了我很久的舞鞋被换下外，一切好像都没有改变，一切又好像都有所不同。\n相比从前习惯的孤独，这一年我始终拥有一个忠实的观众、一个有些笨拙的舞伴。\n每当你坐在舞蹈室时，我都会感到身体更加轻盈，如同我儿时刚刚学习舞蹈的时候，充满了莫名的激情与动力。\n或许我并没有自己想的那样纯粹而高尚，在将一生都奉献给舞蹈的同时，我也希望能够拥有你的注视，聆听你的掌声。\n生日的这天天气很好，我能预感到今夜星空将十分晴朗。我最热情的观众、我的专属舞伴，你是否愿意与我一起走到那片有着美丽湖泊的森林中，一起跳一支属于月亮与星星的舞蹈？\n\n莉兹"
  },
  Mail_68911_Name = {
    Text = "专属舞伴…"
  },
  Mail_68911_Sender = {Text = "莉兹"},
  Mail_68912_Desc = {
    Text = "守密人：\n\n从我的重生之日开始，弥萨格的人们帮助了我很多，或许我仍不能习惯合作的感觉，但至少在与你们同行的时候，我已经可以把后背放心地托付出去，这种感觉……也不错。\n我的人生中大多数时候都充满了伤害与背叛，我总将对抗这些当作我战斗的意义，直到我的生活中再也没有其他任何东西，我的目光早已不能从复仇之中挪开。\n现在跟随着你们的脚步，我才发现战斗除了伤害与报复还可以拥有很多意义，甚至是像萝坦所说的，战斗也可以只是战斗。\n我学会了享受战斗的乐趣，享受那种酣畅淋漓的感觉，享受单纯地成为一个勇猛的战士。\n如果我的战斗能带来更多，那么，我将享受那种荣耀。\n而你，无论现在还是未来，我许诺我的剑刃永远不会指向你。\n\n希洛"
  },
  Mail_68912_Name = {
    Text = "战斗的意义…"
  },
  Mail_68912_Sender = {Text = "希洛"},
  Mail_68913_Desc = {
    Text = "亲爱的守密人：\n\n说实话，我对生日愿望这样的东西并没有太多想法，以前在我尚且“正常”的时候，吃饱穿暖、按时交上房租、照顾好詹金就已是每天最大的愿望。现在还能安安稳稳地度过一年，还能看着詹金胡闹一年，已经足够令人满足。\n说来惭愧，在詹金面前，我总是摆出一副姐姐的样子管教她，但对你来说，我总会给你添上许多麻烦，甚至我自己也不记得是哪一个我惹了麻烦。\n你始终不变的温和与耐心让我既温暖又不好意思，或许这是我人生中第一次有人用这样包容的态度照顾我，我感到发自内心的荣幸和感激。\n今年我为大家烤了一个大大的蛋糕，是曾经纺织厂的阿姨教给我的配方，虽然比不上厨师们的手艺，但那份特别的味道我和詹金都非常喜欢，这次不用担心材料问题，可以让每个人都吃到满足，请一定要来赏光品尝。\n我已经说服了其他的我老老实实地过一个生日，她们今天一定、一定不会再给你添麻烦了！\n如果可以的话，请在需要的时候随时呼唤我吧，无论是洗衣、打扫、收纳，我都很擅长，我也希望能够有机会回报你的那份温柔。\n\n梅森"
  },
  Mail_68913_Name = {Text = "报答…"},
  Mail_68913_Sender = {Text = "「24」"},
  Mail_68914_Desc = {
    Text = "守密人：  \n\n作为一个负责接收大家愿望的人，我好像怎样努力都无法习惯生日这天轮到自己许愿这件事，对我来说，我好像并没有什么想要的东西。\n朵尔告诉我，我需要找到自己内心深处真正渴望的东西，问问自己所做的一切都是为了什么。\n我想了很久很久，我其实希望每个来找我许愿的人的愿望都能实现，再继续问下去，我大概是喜欢人们愿望实现时露出的笑脸，和他们真心簇拥着我、感谢着我，称赞我完成了神女的职责的样子。\n朵尔说，那是我希望自己的价值得到认可，成为一个有用的人，我觉得她说得对。\n但她又说，人的价值不需要由他人来决定，没有什么事是所谓有用的，重要的只有是否顺从了自己的内心，哪怕成为别人口中无用的人。\n不愧是朵尔，总是能说出这样高深的话来，可是我到底要成为有用的人还是没用的人呢？我好像又开始糊涂了……\n不过要顺从内心的话，可能我还是希望当一个有用的人吧。如果生日这天能看到大家的笑脸，应该是我最想要的礼物。\n\n希莱斯特"
  },
  Mail_68914_Name = {
    Text = "有用的人…"
  },
  Mail_68914_Sender = {
    Text = "希莱斯特"
  },
  Mail_68915_Desc = {
    Text = "亲爱的守密人大人：\n\n我早已经习惯了像阴沟里的蛆虫一样的生活方式，不如说那才是我生来的命运，我全然接受了它、并欣然拥抱它。\n虽然我一直感激你们让我重新品尝到了自由的美妙滋味，但没有什么人能接受我那些特别的爱好，这也是理所应当的。毕竟在这里的大多数人都是些温和的好人，无法理解潮湿角落生长的苔藓需要的并不是明媚的阳光，而是阴暗的空气。\n除了你，我尊敬的好心的大人，只有你能真心理解我、帮助我，使我获得发自内心的幸福，你所给予我的疼痛是那样的令人满足、令人安心，让我能确认自己的存在。\n如果曾经我没有什么贪恋的愿望可以在生日时许下，那么现在我希望能够追随在你的身后，为你奉献我的身心。\n当然，请不要因为温柔就对我和颜悦色，尽情鄙视我、责骂我、鞭笞我吧！\n\n雷娅"
  },
  Mail_68915_Name = {
    Text = "苔藓的心意…"
  },
  Mail_68915_Sender = {Text = "雷娅"},
  Mail_68916_Desc = {
    Text = "亲爱的小狗狗：\n\n我几乎已经爱上了这样和你玩猫抓老鼠游戏的日子，就像老套的英雄小说，正义的使者总能在最后一刻阻止邪恶反派的阴谋，多么感人，多么伟大。\n只不过看着你不断挣扎做无用功的样子，真是令人忍不住发笑。\n这个世界早就完蛋了，没有任何办法得到拯救，这颗星球会像万千死亡星球一样，被▼&#x5B▼87;&4;▼。\n算了，就陪你玩玩吧，直到现在我忽然有些能够理解N的趣味，在注定的结局到来以前，做怎样的事其实并没有什么区别。\n在你亲爱的师长生日这天，我依然为你准备了一个大大的惊喜，在生日结束的倒计时之前，希望你能找到那个隐藏的“炸弹”哦。\n在我们都被彻底消融前，你还能给我带来多少乐趣呢？\n\n\n「朵尔」"
  },
  Mail_68916_Name = {
    Text = "惊喜炸弹…"
  },
  Mail_68916_Sender = {
    Text = "熔毁·朵尔"
  },
  Mail_68917_Desc = {
    Text = "守密人：\n\n最近伦蒂尼恩的上流圈子之中流行起了一阵自己绘制设计图，请人定制特别首饰的风潮。\n那些自诩多么懂得艺术的贵妇们各个从攀比宝石的大小一转开始攀比设计图的精妙，殊不知她们背后偷偷聘请知名画家的小动作简直像是掩耳盗铃一样明显。\n拜这阵风潮所赐，我的生日礼物清单中也多出了不少附庸风雅的宝石和首饰，其中有一颗不错的鸽血红，正缺少一枚相配的戒托。\n我想与其去找那些无趣的老头，不如请我的骑士为我画上一张充满心意的图纸，就当作送给我的礼物怎么样？\n我会好好期待着你的作品，相信你的品味一定不错。\n\n索蕾尔"
  },
  Mail_68917_Name = {
    Text = "设计首饰…"
  },
  Mail_68917_Sender = {Text = "索蕾尔"},
  Mail_68918_Desc = {
    Text = "守密人：\n\n在与你的初见以前，在万千的门扉背后，我早已见过无数个相同又不同的你。\n我记得你的喜怒哀乐，记得你的每一次选择，记得你在不同世界中坚持走下去的样子。\n于我而言，在这许许多多的你之中，你是最特别的那一个。我曾把观测过的世界在心中命名编号，你所在的世界被我称作希望，而这个名字取在遇到你的那天。\n在这名为希望的一天，我想你或许会有兴趣看一看其他的世界，如同体验宇宙的双眼，我将带领你，看一看我于门扉前静静观看的一切。\n也看一看我眼中的你。\n\n塔薇"
  },
  Mail_68918_Name = {
    Text = "不同的你…"
  },
  Mail_68918_Sender = {Text = "塔薇"},
  Mail_68919_Desc = {
    Text = "原本弥萨格之简明作风甚得余心，但自从弥利亚姆那个女人到来之后，余的生活便开始不得安宁。\n余不拒绝那些渴望寻求安定、寻求庇护之人，于此混浊世界之中寻求慰藉乃是生灵常情，无可厚非。\n但余一直不喜以全能神明自居，何况在利莫里亚沉没之后，此间也无需再造一个高高在上的神明。\n弥利亚姆大概一直难以走出过去的阴影，才将那一套愚信的作风搬到现在，令余无论走到校园何处都会备受瞩目，乃至纠纠缠缠，实在烦人。\n今日生辰，想必那个女人一定早早备好仪式大肆操办，余闻之乱耳，视之头痛，便不到场沾惹烦恼了。\n若你有意，可来信后所附地址与余散步静心。\n切记，不要让那个女人发现。\n\n图鲁"
  },
  Mail_68919_Name = {
    Text = "躲清静…"
  },
  Mail_68919_Sender = {Text = "图鲁"},
  Mail_68920_Desc = {
    Text = "我每天都饥饿难耐，只要一时半刻不喝血就难受，但自从尝过你的血，那些普通的血食在我嘴里就像蜡块一样难吃，你那血液美妙的味道则每天在喉咙中回味引诱着我。\n我知道把一个人吸干能喝到多少血，那样的美味可以说转瞬即逝。为了不让你死得太快，我会学着忍耐饥饿，学着期待下一次的美味，直到再次品尝到你鲜血的那天。\n哈，天呐，不敢相信我居然做到了，我都怀疑自己是不是已经进化了。看在我这么忍耐的份上，至少在这个所谓生日的日子，就让我尝一次你香甜的美味的血吧，就尝一点，怎么样？\n我用在鳟鱼俱乐部赚的钱给你买了营养补剂，这次你一定不会再贫血了。\n\n饿了很久的尤乌哈希"
  },
  Mail_68920_Name = {
    Text = "美味的血…"
  },
  Mail_68920_Sender = {
    Text = "尤乌哈希"
  },
  Mail_68921_Desc = {
    Text = "尊敬的守密人：\n\n很高兴这一年来能看到你在训练课上的持续进步，很快你就可以超越年轻时的我，成为一名强悍的士兵了。能够成为你的训练教官，我感到非常荣幸。\n今年的生日我收到了一双很适合登山的长靴，不知道你是否有兴趣和我进行一场徒步，检验一下自己增长的体能，顺便去看一次山顶的日出，那种群山之间远离城市的景色一定很美。\n当然，如果再有一场山野露营的野餐，配上一瓶驱寒的烈酒，那就更完美了。\n\n艾尔瓦"
  },
  Mail_68921_Name = {
    Text = "徒步登山…"
  },
  Mail_68921_Sender = {Text = "艾尔瓦"},
  Mail_68922_Desc = {
    Text = "搭档：\n\n这一年来发生了好多事，可能对于你来说，这并不是一段美好的校园生活。\n我承认过去的一年里我对你的督促多有逼迫，而关心略欠体贴，一切的训练都显得有些拔苗助长，让你一下子承受了太多。\n但我希望你知道，你在我心中永远是最重要的那个人，在弥萨格的守密人之外，你是我唯一的搭档。\n或许在今天，我是说仅仅生日这一天，我可以试着任性一次，你也可以忘掉所有的责任，我们不用管任何的作业与训练，去尽情地放松一下。\n去市区的游乐园？剧院？百货大楼或是街头市集……怎样都好，我希望把缺失的东西尽量补偿给你。\n同样的，我也希望这什么都不去考虑的一天能够有你陪伴，所有行程就都由你决定吧。\n\n拉蒙娜"
  },
  Mail_68922_Name = {
    Text = "放松的一天…"
  },
  Mail_68922_Sender = {Text = "拉蒙娜"},
  Mail_68923_Desc = {
    Text = "亲爱的守密人：\n\n在我于人间度过的岁月中，曾经那些可爱的仆从们会在每年的今天为我举办盛大的宴会，变着花样地努力讨好我。\n明明是无事发生的平凡一天，在那些莫名其妙的笑脸中也真变得令人开心起来。论苦中作乐、无中生有的本领，人类的确长于此道。\n哪怕在这所把坟墓建立在校园里的学校，你们仍然能如此顽强地创造快乐，真是令我惊奇。\n只不过那些普通人的礼物实在乏味，所谓的生日派对也难以置信的无聊，庸俗的人终究占了大多数。\n只有你，只有想起你时我还会有些许兴味，让我重新品尝到旧日一样的乐趣。\n我命令你现在立刻到我的房间来，与我游戏到天明。如果伺候得好，我可以勉为其难地允许你亲吻我的手背。\n\n旺达"
  },
  Mail_68923_Name = {Text = "命令…"},
  Mail_68923_Sender = {Text = "旺达"},
  Mail_68924_Desc = {
    Text = "<Del:西区佬>守咪人：\n本来我没打算再写这种肉麻的东西，艾继丝一直在我旁边念叨什么纪念啊意义的，非要让我给你写这封信不可。\n看在艾继丝的份上，我就勉强说两句。那个什么，在这里待了一年了，我对学校的住宿和吃喝总体都还满意，唯独宿舍的床单实在有点太滑溜溜了，搞得我总是睡不习惯。难道你们不觉得只有那种粗粗的棉布睡着才舒服吗？\n要说还有什么可以挑剔，就是食堂的饭菜都太健康了，吃完虽然饱了，但总感觉嘴里没味道，完全比不上街头美食的口味！\n所以今年的生日会我不打算麻烦那些厨师了，让本美食大师带大家前往东区的神秘小巷，品尝一下我和布朗都特别推荐的小摊，包管你们马上就被街头美味折服！\n当然，今天所有花销由西区佬买单，你没意见吧？\n\n你的老伙计詹金和布朗"
  },
  Mail_68924_Name = {
    Text = "街头美食…"
  },
  Mail_68924_Sender = {Text = "詹金"},
  Mail_68925_Desc = {
    Text = "贵人：\n\n除了姐姐之外，你是第一个如此真心支持着我的人，多亏你之前的建议，我现在已经和唱片公司发布了一系列专辑，并且很快就要举办我的个人演唱会了。\n我想把在这个星球举办的第一次演唱会定在生日的那天，来纪念我在这里的新生。\n希望你能够来现场聆听我全力以赴的演唱，我想将你和姐姐作为特殊嘉宾在最后的环节邀请到台上，陪着我一起唱我的新歌，你意下如何？\n对了，这件事不要告诉我的姐姐，毕竟这也同样是她的生日，我想给她一个惊喜。\n至于我和姐姐约定好的要为自己许下的生日愿望，我希望能够在这个星球让我的歌声再次闪耀。\n\n汀克特"
  },
  Mail_68925_Name = {
    Text = "演唱会…"
  },
  Mail_68925_Sender = {Text = "汀克特"},
  Mail_68926_Desc = {
    Text = "亲爱的守密人：\n\n不知不觉又过去了一年，我在弥萨格的每一天都非常快乐，能够和大家一起玩、一起上课、一起吃很多很多好吃的，这是我人生中最幸福的时光。即使偶尔出任务的时候我会有点紧张，但和大家一起战斗，艾继丝从来都不会害怕。\n非常不好意思这一年我还是给您添了许多麻烦，虽然很多时候是詹金又在搞怪，但她也只是想让大家开心，希望您不要介意我们的粗心和冒犯。\n说到詹金，今年她提议在我的生日这天举办一场捉萤火虫大赛，她准备了很多透明的罐子，说是要做成很多很多的萤火虫灯，最后谁做出的灯最亮，谁就会获得捉虫大王的称号。\n虽然捉虫大王听起来有点傻，但那片在夏天总是充满萤火虫的森林的确很美，如果您在忙碌之余有些闲暇的话，也欢迎您来和我们一起去森林中，看一看那片星星一样闪烁的风景。\n\n艾继丝"
  },
  Mail_68926_Name = {
    Text = "捉萤火虫大赛…"
  },
  Mail_68926_Sender = {Text = "艾继丝"},
  Mail_68927_Desc = {
    Text = "守密人！前几天去大海游泳的时候，奥瑞塔遇到了一个会放电的新朋友！它长得圆圆的，扁扁的，像一张大披萨！\n奥瑞塔本来和它打招呼，忽然感觉身上麻麻的，新朋友也一下子走掉了。\n回来之后朵尔跟我说那是电鳐在放电，奥瑞塔不太懂，但感觉新朋友好厉害！正好奥瑞塔的生日到了，守密人陪奥瑞塔去把新朋友接回来吧，就和奥瑞塔的伙伴们一起住！那种麻麻的感觉，守密人也一定会喜欢的！\n\n奥瑞塔"
  },
  Mail_68927_Name = {
    Text = "会放电的新朋友…"
  },
  Mail_68927_Sender = {Text = "奥瑞塔"},
  Mail_68928_Desc = {
    Text = "尊敬的守密人：\n\n儿时生日于我而言，是父亲不假辞色的要求，是不能放松半点的演奏练习。\n不可骄傲、不可浮躁、不可怠惰，除却母亲会偷偷为我准备一块小小的蛋糕，这一天对我来说只是平白遭受一次严格的训话，以指点过去一年我的种种不足。\n直到今天，我已并非音乐的学徒，且因您能够触碰那道恢宏的大门，走入至高的音乐殿堂，但从小以来的训诫早已使我不会对凡俗的乐趣有任何欲望。\n唯有音乐，唯有为您演奏那命中注定的安魂之曲，是我此生最终的追求，是我唯一能感到意义存在的时刻。\n如果您愿意将今夜入睡前的时光交给我，我愿彻夜为您演奏那刻在我灵魂中的乐曲，直到天明。\n\n哈姆林"
  },
  Mail_68928_Name = {
    Text = "演奏的心愿…"
  },
  Mail_68928_Sender = {Text = "哈姆林"},
  Mail_68929_Desc = {
    Text = "毛头小子：\n\n自从到了你们这儿，原本想着终于摆脱了那个迂腐的疯女人，结果你们这鬼地方的规矩比那个女人还多，老子已经很久没有尝到痛快是什么滋味了！\n大口喝酒不许，调戏美人不许，篝火晚宴不许，就连你们这里的烤肉都比非利士的差远了！真不知道这种淡得没味儿的生活你们都是怎么过下去的。\n不过强者不会抱怨环境，经过老子一番征伐，我已经在你们的城市重新成为了一位伟大的帮派领袖。\n值此伟大的戈利亚之主的生日，我大发慈悲地邀请你参加我的小弟们为我举行的宴会，好酒好肉和美人应有尽有，绝对能让你这个没见过世面的小屁孩儿开开眼。\n看在之前交情的份上，我就不向你要什么礼物了，你只需要带着你的尊敬，来为强者的再次崛起送上祝福。\n给我睁大眼睛好好见证吧，明年的今天，明年的明年的今天，无论身在何处，我都将开辟出一片新的征途。\n\n戈利亚"
  },
  Mail_68929_Name = {Text = "征途…"},
  Mail_68929_Sender = {Text = "戈利亚"},
  Mail_68930_Desc = {
    Text = "守密人： \n\n原本我从未想过要庆祝此浅薄之身的生日，只将此当作普通的修行之日，但没想到王在今早找到了我，对我降下口谕，要我今日不得做任何与王或修行有关之事，必须全然为自己度过一天。\n许多日夜来王第一次如此惦念着我，实在使我不胜惶恐、不胜感恩，但我早已将此生全部奉献给王，一时竟然不知该去往何处，该做些什么。\n思索半晌，如今唯一能称得上略有遗憾之事，便是对墨菲那孩子的愧疚。哪怕为了故国复兴，我从未有过半分后悔，欠下她的，我亦自知无可偿还、无法弥补。\n但，如果我还真有什么出于内心想做的事，或许是想厚颜无耻地，再做一次一位母亲应该做的事。\n我特地买来了那孩子曾经喜欢的甜点，就当作成全一个可鄙的、失格的母亲，能否拜托你替我将这份礼物送到她的手中，切莫告诉她是我相赠，只说是你准备的就好。\n企望应允，万分感激。\n\n弥利亚姆"
  },
  Mail_68930_Name = {Text = "弥补…"},
  Mail_68930_Sender = {
    Text = "弥利亚姆"
  },
  Mail_68931_Desc = {
    Text = "啊哈，经过我智慧的思考，我已经完全弄明白了人类生日的意义，所谓专属于某人的特殊的一天，就是为了让人获得稀有的行使特权的机会、得到珍贵物品的机会，以及对他人理直气壮提出愿望的机会。\n无论是怎样平时不敢说、不会想的愿望，在这一天都有机会被满足，哈，这简直是比任何节日都要刺激的放纵日。\n看来从前的那么多年，我都错过了这么多的特权机会，不过好在以我漫长的寿命，以后我还有很多很多的生日可以许愿。\n那么，在生日这天要求所有人陪我痛痛快快地打一场，应该是很好满足的愿望吧？\n\n萝坦"
  },
  Mail_68931_Name = {
    Text = "寿星的特权…"
  },
  Mail_68931_Sender = {Text = "萝坦"},
  Mail_68932_Desc = {
    Text = "守密人： \n\n随着年龄增长，生日逐渐变成了日历上一眨眼就会忽略过去的一天，往往等到不经意想起的时候，生日就已经像流水一般悄悄过去了。\n在成人的世界，欢庆生日只是小孩和无聊闲人的特权，我在这方面同样变成了一个无聊的大人，对生日早已没什么期待。\n曾经有一年我突发奇想，为自己雕刻了一个精美的蛋糕雕塑，之后的几年，我就再也没有因为忘记生日而错过预定蛋糕，而是直接在生日这天从仓库中找出这块永不腐坏的庆祝道具，体验一把吹蜡烛的仪式，生日就算是过完了。\n直到来到弥萨格，我才发现闲人与忙人可以在同一个人身上呈现出共存的状态，且这里的人不仅仅满足于自己一个人无聊，还一定要拉着所有人一起无聊。\n这两年在弥萨格中参加的生日聚会简直要比我前半生参加过的所有生日聚会还要多，更好笑的是我在这种无聊的庆祝中竟然也找到了一丝奇妙的乐趣。\n或许除了悲怆而严肃的主题，描绘一些生活中傻得冒泡的场景，也可以充满了艺术之美。\n说到这里，今年生日的创作计划就来雕一个守密人傻笑半身像，用来捧着我的雕塑蛋糕吧。\n记得早点来我的工作室哦，我的缪斯模特。\n\n珊"
  },
  Mail_68932_Name = {
    Text = "无聊的乐趣…"
  },
  Mail_68932_Sender = {Text = "珊"},
  Mail_68933_Desc = {
    Text = "展信安：\n\n斟酌许久，我于这个寂灭的世界写下这封信。许久以来，我几乎遗忘了自己的生日，在这样的世界，庆祝自然也是无谓的。\n但，自从与你相遇，我变得越来越贪心，日复一日，连习以为常的孤独都有些难耐。\n每当这时，我的心中会生出一种奇异的情绪，对那个世界的我产生一丝羡慕，或许还有微不可查的嫉妒。你看，像我这样自诩理性的人，也会有这样心思可鄙的一天，可见人类的公正与理智都有自己的极限。\n我知道你会对我说出怎样的邀请，但对时空来说，不必要的扰动都应尽量避免，我不应也不会前往你的世界。\n写到这时，我正遥望着宇宙，遥望着隧道开启的地方，如果你恰好也在抬头看，那么我们也算一起注视着同一片星空。\n希望这封信能代替我，跨越时空，漂流到你的掌心，经过你的双眼与唇齿，与你相见、与你相依。\n当你拥抱这张信纸，我会在世界这头想象着拥抱你。\n\n「拉蒙娜」"
  },
  Mail_68933_Name = {
    Text = "共同遥望…"
  },
  Mail_68933_Sender = {
    Text = "环行·拉蒙娜"
  },
  Mail_68934_Desc = {
    Text = "我的小·囚·犯：\n\n你知道吗，就像不同的动物有不同的食谱，不同的人对温暖的需求也是不同的，有的人自己披上一件衣服就足够取暖，有的人需要一双暖和的手、一个暖和的拥抱，而有的人需要的温度则是蜡烛融化的温度。\n那样滚烫的、黏稠的温度刻印在每个神经末梢，清晰地映照出蜡烛蜿蜒滴落的轨迹，微微的疼痛、令人颤栗的触感，直到情不自禁呼喊出来的时候，才能够畅快地感受到自身的存在。\n有时候我会化身蜡烛，享受带来印记的快乐，有时候我也会迷恋蜡烛的温度，渴望那样令人疼痛的、甜蜜的温暖。\n弥萨格的冬天已经到来，最近我已经常常感到寒冷，以及寒冷带来的孤独。亲爱的你应该知道今天是什么日子，我的愿望很简单，想必善良如你，一定会愿意给我带来驱散寂寞的温暖的。\n\n潘狄娅"
  },
  Mail_68934_Name = {
    Text = "温暖的需求…"
  },
  Mail_68934_Sender = {Text = "潘狄娅"},
  Mail_68935_Desc = {
    Text = "守密人：\n\n今年我与汀克特相互约定，我们生日的愿望只能关于自己，不可以为对方许愿。\n虽然是她先赌气提出的这个约定，但显然这下也把她自己难倒了。\n我们两个捆绑纠缠在一起太久，想要像常人一样独立地思考都是一件难事，但重生在拥有这样多帮助与关心的新生活中，没有比现在更适合学习独立行走的时候了。\n那么经过我的仔细考虑，我已经想到了今年要许下的愿望：交到五个新朋友……不，还是三个吧。毕竟改变自己这种事，还是要一点一点慢慢来。\n作为我目前唯一的且如此受人欢迎的朋友，或许你能教给我一些交友的秘诀吗？\n\n菲茵特"
  },
  Mail_68935_Name = {
    Text = "交友的愿望…"
  },
  Mail_68935_Sender = {Text = "菲茵特"},
  Mail_68936_Desc = {
    Text = "守密人： \n\n每年生日许愿时我都会许下同一个愿望，那就是完美血脉的蜕变。我其实一直知道，我对血脉的执念在他人看来可能是执拗、可笑、甚至可怜可鄙的。\n但你不一样，无论何时，我知道你都会支持着我在这条道路上走下去，哪怕碰壁、摔倒、无功而返，在他人的笑声中，你是第一个关心我的人。\n或许无论是你还是任何人都无法理解一个从小被欺压、被羞辱的人所背负的一切，但没关系，在这蜕变之路上的磨难都已化作我的血肉和养分，支撑我不断爬起，不断反抗。\n我已不再是年少时无力的自己，哪怕考验重重，我都会坚定走到最后一刻。\n在此之前，就请你注视着我，等待着我的成功吧。\n对了，你之前给我的五十块，我说了会还给你，现在已经攒够了，还多出两块钱，就当做回报一并给你吧。\n\n凯刻斯"
  },
  Mail_68936_Name = {Text = "还钱…"},
  Mail_68936_Sender = {Text = "凯刻斯"},
  Mail_68937_Desc = {
    Text = "尊敬的守密人：\n\n您好，欢迎填写自动人偶艾瑞卡的年度检修调查问卷，我将收集您在这一年中使用艾瑞卡时的真实体验与遇到的问题，您的意见是艾瑞卡不断改进的方向。\n下面请您在回信中对相关问题由低到高进行打分，非常感谢您的反馈。\n使用时的便捷程度：1-5分\n使用时的响应速度：1-5分\n对需求的理解程度：1-5分\n对用户情绪的照顾程度：1-5分\n查询资料时的准确程度：1-5分\n提出解决方案的实用程度：1-5分\n最后请简要描述您在使用艾瑞卡时曾遇到的问题，以及不满意的部分，这些问题可能在之后得到修复。\n完成问卷后会有周年纪念小礼物送到您的房间，未来的一年您最贴心的助手艾瑞卡依然会陪伴在您的身边，再次感谢您的使用，再会。\n\n艾瑞卡"
  },
  Mail_68937_Name = {
    Text = "年度检修调查问卷…"
  },
  Mail_68937_Sender = {Text = "艾瑞卡"},
  Mail_68938_Desc = {
    Text = "守密人： \n\n每到生日这一天，我都会花上一整天将过去在脑海中细细回忆一遍，将同样的日记再写下一遍。\n远离故乡越久，旧日的记忆仿佛越模糊，那些等待着归人循光而来的日子，那些遥遥仰视王之威仪的日子，似乎都已经记不真切了。\n但我不愿意遗忘，我绝不会遗忘，哪怕等待漫长无尽，哪怕燃烧灵魂，这道光芒也不会黯淡下去，直到故国复苏之日，我便是第一道响应召唤的光。\n我想过无数种重逢的场景，却从未想过会在此处重见王与祭司，按照你们的那句话来说，如果心灵安宁之处就是故乡，这里已可以算是我的第二故乡，而我日记本上所记载的也终于从回忆变作每日崭新的记忆。\n无须任何嘉奖或礼物，能够再次追随在王的身边已是最大的幸福。\n若此身的光芒无法照耀故乡的海底，那么就让它跟随王的脚步，暂且照耀这一片陆地之国吧。\n\n法洛思"
  },
  Mail_68938_Name = {
    Text = "追随吾王…"
  },
  Mail_68938_Sender = {Text = "法洛思"},
  Mail_68939_Desc = {
    Text = "守密人： \n\n恭喜我，也恭喜你，恭喜弥萨格，恭喜我们在黑色恐怖的追逐下又幸存了一年。\n今天不是一个简单的生日，今天是我存活的纪念日，是我顽强生命的赞美日。\n活着，简简单单的两个字蕴含着多么多的艰难，这样滚烫的生命力只有滚烫咖啡的芬芳能够媲美，一起加入咖啡神教吧守密人，让我们赞美清醒，赞美活着的每一\n\n一张和信一起送来的纸条：\n唉，温柯尔这家伙又饮用咖啡过量，神经亢奋加上过度疲惫，直接晕倒在桌子前了，我已经将她安置在了校医室，不用担心。\n不过她昏过去之前拿出了一包珍藏的咖啡豆和信纸放在一起，貌似是要送给你的，我就随信一起附上了，希望等她醒来之后不要后悔。\n至于她的生日，比起庆祝派对，或许让她好好休息一下才是最好的礼物吧。\n——茜尔维娅"
  },
  Mail_68939_Name = {
    Text = "赞美生命…"
  },
  Mail_68939_Sender = {Text = "温柯尔"},
  Mail_68940_Desc = {
    Text = "守密人：\n\n哈哈哈！经过我坚持不懈地在房间各个角落刻下12个提醒，写了36张纸条（或许有更多但是我找不到了）之后，我终于不负众望地记住了今天是我的生日！\n没想到吧，其实连我自己都是今天早上才想起来的，但是这都要归功于这一年来我的辛苦准备，我可不想错过这种好日子。\n上次和大家一起开的派对真的很高兴，尤其是和谁来着玩的什么游戏，还有吃的某种甜点……算了，总之就是高兴！\n小时候过生日妈妈总会给我买一本冒险故事书，我们两个每天睡觉之前就会靠在一起读啊读啊，梦里就会梦到很精彩的冒险。虽然醒来后也会很快忘掉，但那份快乐还会留在脑海里，我相信宝贵的情感是不会被遗忘的。\n况且健忘也有健忘的好处啊，虽然我不记得之前派对上都做了什么，但今天我可以全部重新体验一遍啦，上一次的快乐，就请打包给我再来一份吧！\n\n充满期待的诺缔拉"
  },
  Mail_68940_Name = {
    Text = "再来一次…"
  },
  Mail_68940_Sender = {Text = "诺缔拉"},
  Mail_68941_Desc = {
    Text = "尊敬的守密人：\n        在V1.7.1的更新中，您在「繁衍狂热」中的「血链·希洛」事件已解锁状态异常丢失。由于您在丢失已解锁状态后再次进行了解锁，我们将补发再次解锁消耗的「现实起点」× 3。请查收。"
  },
