  Mail_74347_Desc = {
    Text = "尊敬的守密人：\n「灵魂的牧人·复刻」活动已结束，现将守密人剩余的「义卖券」按照每个兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
