  },
  Mail_74841_Desc = {
    Text = "搭档：\n\n去年的今天，我还远远没有想到时隔一年之后，我便只能将这封信投入一个空空的邮箱。\n那时你刚刚进入弥萨格不久，与一个顽劣又懒惰的学生没什么两样，即使现在想来，我那时常常对你过于严格，也过于在意自己那张理性又矜持的面具了。\n其实去年的这一天我买了一束花，我站在图书馆的门前，看了那束躺在红色丝带与墨绿色的包装纸里的玫瑰很久，最终把它插在了我的床头。\n一年时间花朵早已枯萎，只有那条亮红的缎带被我系在K-0617号银钥上，仍旧艳丽如新。\n我多么、多么想再买一束玫瑰，然而如今它们除了再次在我的床头凋零，已经没有了其他的归宿。\n习惯了将所有事情都详细列出解决方案，后悔的滋味对于我来说，是这样新奇又苦涩。\n但我一直怀抱着一种近乎盲目的信任，认为你的灵魂始终没有离去，你或许暂时在宇宙的某处遨游，但最终仍会回到这里，回到我的身边。\n我并不觉得这是痴人说梦的幻想，只因我每每来到黑池之中遥望你的面庞时，内心中仍能感到与你链接、共鸣的那丝暖和的温度。\n我会始终相信并期冀着重逢的那一天，在我们的手重新相牵的那一刻，我会将今日欠下的玫瑰亲手交到你的手中。\n\n拉蒙娜"
  },
  Mail_74841_Name = {Text = "玫瑰…"},
  Mail_74841_Sender = {Text = "拉蒙娜"},
  Mail_76410_Desc = {
    Text = "尊敬的守密人：\n「雨镇幽影」活动已结束，现将守密人剩余的「苍白野兽头骨」、「幽影野兽头骨」和「殷红野兽头骨」按照每个兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
