  },
  Mail_78792_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_79390_Desc = {
    Text = "尊敬的守密人：\n        感谢您对《忘却前夜》的支持和认可，为了让守密人在弥萨格大学有更好的游戏体验，诚邀您填写以下体验调研问卷。为感谢您的配合，我们准备了「银芯」× 200 作为奖励，完成问卷即可领取。问卷截止时间3月17日9:00，请注意及时填写。\n        <SurveyLink:【点击前往填写】>\n        我们会认真听取每一位守密人的建议，您的反馈也一定会使弥萨格大学越来越好！\n        ——愿银钥指引前路。"
  },
  Mail_79390_Name = {
    Text = "版本体验调研问卷V2.1.0"
  },
  Mail_79390_Sender = {
    Text = "弥萨格校务处"
  },
  Mail_79646_Desc = {
    Text = "尊敬的守密人：\n「埋于记忆之下」活动已结束，现将守密人剩余的「诊断报告」按照每个兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
  },
  Mail_79646_Name = {
    Text = "埋于记忆之下货币回收"
  },
  Mail_79646_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_80091_Desc = {
    Text = "守密人：\n\n当你翻开这封信，就代表我在你心里埋下的暗示已经生效。\n哈，不必担心。这只是为了保证我的生日宴会顺利进行，而施展的微不足道的催眠，不会对你产生什么影响。\n接下来，你会发自内心产生想要逛街购物的冲动，顺从它走到街上吧，从那琳琅的橱窗里挑选一件最和我心意的礼物，再送到我的手里。\n我知道你此刻的疑惑，也认同它的合理性，但寿星总是有些特权的对不对？我之所以如此，只是怕你忘记了这特殊的日子。毕竟，你可是我心心念念的客人。\n最后，我会耐心等待你的来访——别忘记礼物。\n\n克莱门汀"
  },
  Mail_80091_Name = {
    Text = "“亲自”挑选的礼物"
  },
  Mail_80091_Sender = {
    Text = "克莱门汀"
  },
  Mail_81288_Desc = {
    Text = "尊敬的守密人：\n        感谢您对《忘却前夜》的支持和认可，为了让守密人在弥萨格大学有更好的游戏体验，诚邀您填写以下体验调研问卷。为感谢您的配合，我们准备了「银芯」× 200 作为奖励，完成问卷即可领取。问卷截止时间4月14日9:00，请注意及时填写。\n        <SurveyLink:【点击前往填写】>\n        我们会认真听取每一位守密人的建议，您的反馈也一定会使弥萨格大学越来越好！\n        ——愿银钥指引前路。"
  },
  Mail_81288_Name = {
    Text = "版本体验调研问卷V2.2.0"
  },
  Mail_81288_Sender = {
    Text = "弥萨格校务处"
  },
  Mail_81326_Desc = {
    Text = "恩人：\n\n今天对于我和波吕克斯来说，是一年之中唯一的节日。在教会中时，我们并不被允许过度关注自我的意义，我们全部的价值都只存在于侍奉持灯者这一永恒的事业上，在那样的信仰面前，其他任何节日也都是无意义的虚妄。\n但每到了生日这一天，我和波吕克斯依然会偷偷地庆祝，我们会瞒着侍从为对方准备一份尽可能小的礼物，然后隐秘地期待着这一天的到来。\n生日的庆祝时刻往往在深夜——那是我们一天中仅有的自由时刻，波吕克斯灵巧的双手和点子总能让他的礼物胜过我的，有一次他甚至靠积攒掉落的羽毛编织了一朵盛开的花。\n其实我并不擅长准备惊喜，波吕克斯总说我平时的表情早已出卖了一切，而我所拥有的东西在您看来想必更加贫瘠无聊，不过今天我已经想到了一个绝佳的、与您分享喜悦的方式。\n当您在晚上听到窗户被敲响三下，请别害怕，推开窗，我将带您去体验云层与夜风的触感。\n\n卡斯托尔"
  },
  Mail_81326_Name = {Text = "夜游…"},
  Mail_81326_Sender = {
    Text = "卡斯托尔"
  },
  Mail_84142_Desc = {
    Text = "守密人：  \n\n在汇合前，我写下了这封信，正式邀请及向您介绍我的「生日航行」。\n本次航行的第一站，是泰晤士河。我们会登上货船改造成的移动餐厅，一边泛舟，一边品尝罐装蜜渍菠萝和朗姆酒。这是船员生日时才会特供的美味，希望您会喜欢。\n本次航行的第二站，是港口观景台。请您放心，我已经向热气球协会申请了观测权限。当热气球飞上高空，俯瞰整个伦敦航道时，我们会共同切开蛋糕，作为庆祝。\n从前，航行条件有限，所谓的生日蛋糕只是木匠用橡木和焦糖制作的模型，因此我也不知道蛋糕的味道，这次能与您共同品味，我想除了食物的美好外，我还会收获更多。\n第三站，或者，应该被称为第三个环节，是定制星图。我在海图上标注了自己出生时的天体位置，如果您不介意的话，我想将您的也标注进去，这样独一无二的航海星图，将会是最值得珍藏的礼物。\n事实上，在写下这封信时，我曾有过犹豫。这些行为无疑超出了寻常的界限，但今天是个特殊的日子，您对于我来说也是特殊之人，值得我为之打破常规。\n所以请您务必不要拒绝，并按时赴约。\n\n克珀珊特"
  },
  Mail_84142_Name = {
    Text = "「航行」邀请"
  },
  Mail_84142_Sender = {
    Text = "克珀珊特"
  },
  Mail_84355_Desc = {
    Text = "尊敬的守密人：\n「于暴雨中摇曳」活动已结束，现将守密人剩余的活动货币「信号旗」按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人记得查收。"
