  Mail_89744_Desc = {
    Text = "尊敬的守密人：\n        在V2.2.2的更新中，我们提高了「源液捐献-校友捐献基金」的奖励。对更新前已领取完追加奖励的守密人，我们将补发对应的奖励。请查收。"
