  Mail_94424_Desc = {
    Text = "尊敬的守密人：\n「伟大的征服」活动已结束，现将守密人剩余的「美味雷欧烤肉」按照每枚兑换「蔷薇金券」× 40 的比例进行转换，请守密人记得查收。"
