  Mail_94425_Desc = {
    Text = "尊敬的守密人：\n「伟大的征服」活动已结束，现将守密人剩余的「简约幻衣绘形券（二期）」按照每枚兑换「无形者的请柬」× 1 的比例进行转换，请守密人记得查收。"
  },
  Mail_94425_Name = {
    Text = "简约幻衣绘形券（二期）回收"
  },
  Mail_94425_Sender = {
    Text = "弥萨格校委会"
  },
  Mail_94503_Desc = {
    Text = "我的明灯：\n\n自从我与卡斯托尔来到这里，您对我们的照拂堪比赐予了我们新生，感谢您为我们精心准备的生日蛋糕，虽然把您在蛋糕上画的两只小鸟认成了蝴蝶十分抱歉，但我们真的很喜欢这份礼物，这也是我们第一次收到来自他人的生日礼物。\n我们还从诃勒特院长那里收到了学校赠送的贺卡，那枚白色的信封上粘贴了金色的华丽印章，里面写满了美好的祝福，这真是一个温暖的地方，我们的人生中从没有像现在一样幸福的时刻。\n请来与我和卡斯托尔一同庆祝生日吧，这是我们儿时坚持的仪式，作为我们的恩人，我们也为您准备了互换的礼物，是我用卡斯托尔掉落的羽毛编制的一顶头冠。\n我将这粗陋的冠冕献予您，以求聊表我们的崇敬之情，我愿用我的余生追随您左右，践行这所学校伟大的愿景，消除那些真正的罪恶与黑暗。\n许久未曾做这些事，卡斯托尔还笑话我的手艺不如儿时，希望您不要嫌弃。\n\n波吕克斯"
  },
  Mail_94503_Name = {
    Text = "羽毛头冠…"
  },
  Mail_94503_Sender = {
    Text = "波吕克斯"
  },
  Mail_95382_Desc = {
    Text = "可爱的小家伙：\n\n小家伙，今天是我降临的那一天。\n不是作为不停燃烧的大火球，而是那个叫凯蒂古拉的女孩的生日。\n按照生前的习惯，这一天我们会开一个盛大的晚宴，肆意享用美酒和烤肉。\n当然，总有臭小子不会看气氛地调侃我又老了一岁，所以我用拳头问候了他们的脑壳。\n而如今，这个宴会新增了一个功能，供我们怀念曾经度过的时光。\n今年我打算再加一个活动，那就是——狩猎我们的小家伙！\n知道么，我已经迫不及待地想把你抓到我的宴会上，用你那害羞无措的可爱表情、半醉半醒的迷离眼神、自内而发的甘醇香气来装饰我今年的生日晚宴，这将会是我自出生以来，得到的最好的生日礼物！\n现在开始筹备逃跑计划已经晚了，因为当你看到这封信件时……我·早·已·来·到·你·的·门·前。\n别害怕，小家伙，如果一切正常，你只会在这里聆听最好的故事，品尝最美味的食物。\n当然，被捕获的小兽，发生点意外也很正常对吧。\n乖乖跟我走吧小家伙，今晚你那美好的时光，注定要跟我一起度过。\n\n凯蒂古拉"
  },
  Mail_95382_Name = {
    Text = "时光的晚宴…"
  },
  Mail_95382_Sender = {
    Text = "凯蒂古拉"
  },
  Mail_95465_Desc = {
    Text = "尊敬的守密人：\n「名侦探手册·复刻」活动已结束，现将守密人剩余的「决胜筹码」按照每个兑换「蔷薇金券」× 40 的比例进行转换，请守密人查收。"
