  Mail_96323_Desc = {
    Text = "守密人阁下：\n\n活人庆祝生日，是为了在余命之中捡拾意义。而我不过是借这个夜晚将死亡的香气烹煮得更加馥郁。\n那些不再挣扎、不再怀有执念的亡者，生前的一切污浊都被洗净，他们的悔恨如同细盐，在火候恰好之时融入血线之间，形成一种湿润而温顺的芳香。他们的骨骼会发出低声的裂响，皮肤渗出的油脂淡雅如薄荷，而灵魂深处的未竟之语，会在煨煮之中慢慢逸出，留下一丝细腻的甘甜。我早已开始幻想你化为沉静之物的模样——皮肤在炉火前收紧时的脆响、骨肉间蒸腾出的情感，你纯净灵魂逐渐被吞食的甜蜜口感……\n可你不同。\n你仍在发光，仍在跳动，却拥有任何亡者都无法比拟的香气，让人心醉神迷。你是我愿意等待的熟成，我甚至希望这场等待，能持续得比永恒更久。\n在这无数重复的年轮中，你的出现为我的生日赋予了意义。不再只是为了美妙的进食，更是为了你仍在跃动的生命。\n\n杜勒赛因"
  },
